-- =============================================================================
-- city_data Wikipedia leírások – 3/4. fájl
-- Települések: 773 (Magyarszék … Szajla)
-- Futtasd az előző batch(ek) után.
-- =============================================================================

UPDATE public.city_data AS c
SET panel_leiras = v.panel_leiras
FROM (
  VALUES
    ('Magyarszék', 'Pécstől mintegy 20 kilométerre északra, Komlótól nagyjából 10 kilométerre nyugatra fekszik. A település nevének szék eleme vizes, ingoványos területet jelent. Az 1930 körül Magyarszék, Németszék és Kishertelend egyesítésével kialakított község a Baranyai-Hegyhát kapujának tekinthető település. A középkor× óta folyamatosan lakott. A 18. században érkeztek német lakosai, akik külön települést kezdtek kialakítani (Németszék).'),
    ('Magyartelek', 'Pécstől délnyugatra, Szentlőrinctől délre, Sellyétől északkeletre fekszik, az Ormánság északi részén. A szomszédos települések: északkelet felől Gerde, kelet felől Kisasszonyfa, dél felől Gilvánfa, nyugat felől Magyarmecske, északnyugat felől pedig Királyegyháza. Legfontosabb vízfolyása a Pécsi-víz, amely a településtől keletre folyik, az itteni szakasza nagyobb részén egyúttal természetes határt képezve Magyartelek és Kisasszonyfa között.'),
    ('Majosháza', 'A közvetlenül határos települések: északkelet felől Dunavarsány (Nagyvarsány), kelet felől Délegyháza, délkelet felől Kiskunlacháza, dél felől Áporka, nyugat felől Szigetcsép, északnyugat felől pedig Tököl (utóbbi szintén a Csepel-szigeten helyezkedik el). A környék fontosabb települései közül Délegyháza 7, Áporka 5,5, Kiskunlacháza 8, Taksony 10, Dunaharaszti pedig 13 kilométer távolságra található.'),
    ('Majs', 'A szomszéd települések: észak felől Nagynyárád, északkelet felől Sátorhely, kelet felől Udvar, dél felől Bezedek, délnyugat felől Lippó, nyugat felől pedig Töttös. Délkeleten a község határszéle egybeesik az országhatárral, ott valószínűleg a horvátországi Dályokkal (Duboševica) vagy Főherceglakkal (Kneževo) határos. Majs (Majsa, Egyházas-, Kis-, Nagy-) nevét az oklevelek a pécsi püspök levéltára szerint 1235-ben említették először Moysa írásmóddal.'),
    ('Makkoshotyka', 'Miskolctól közúton kb. 80 kilométer-re északkeletre, a Tokaj-hegyaljai borvidéken található. A legközelebbi szomszéd település a 4 kilométerre fekvő Hercegkút, a legközelebbi város pedig a mintegy 7 kilométerre található Sárospatak. A település a 12. század második felében jött létre. István adományozta egy Hugka nevű vitéznek, az ő nevéből ered a „Hotyka” név.'),
    ('Maklár', 'A település a Bükk hegység lábánál elterülő Egri-Bükkalja Alföldbe simuló dombvidékének határmezsgyéjén fekszik, a síkság északi peremvidékén, a Duna–Tisza közén. Közlekedés-földrajzi adottságai jók, melyeket tovább javított a határában megépült M25-ös autóút. Az egri borvidék részeként gazdaságában mindig is jelentős szerepet játszó mezőgazdaság napjainkban az ipari termelésnek adja át helyét, miközben a település fejlődése lépten-nyomon tetten érhető.'),
    ('Makád', 'A település Budapesttől 50 kilométerre, Ráckevétől 10 kilométerre délre található. Nyugatról a Duna folyam, keletről a Ráckevei-Duna övezi, a két ág Makád alatt egyesül, így ez a Csepel-sziget legalsó települése. Szárazföldön csak két települési szomszédja van, észak felől Szigetbecse, északnyugat felől pedig Lórév községek. Szerkezetére a V alakú forma jellemző több párhuzamos és keresztutcával.'),
    ('Makó', 'Első írásos említése 1247-ből maradt fenn, amikor a település helyén folyami átkelő jött létre. A török hódoltság alatt többször elpusztították, de mindig újratelepült. Bár fő megélhetési forrása a kezdetek óta a mezőgazdaság, szellemisége is igen jelentős. Kulturális élete a 20. század elején volt a leggazdagabb, amikor a városban élt és tevékenykedett József Attila, Juhász Gyula és Móra Ferenc is.'),
    ('Malomsok', 'Pápától 18, Győrtől pedig 42 kilométerre fekszik. Jellegzetes kisalföldi település. A közelében két folyó, a Rába és a Marcal folyik. Malomsok nevét 1325-ben említette először egy oklevél possessio Mulunsok (malomsoki birtok) néven helyezkedik el.'),
    ('Marcalgergelyi', 'Szomszédos települések: Külsővat, Nemesszalók, Szergény, Vinár. A település eredeti, rövidebb neve: Gergelyi, XII. századi eredetű, a Gergely keresztnévből származik. A falu első említése egy 1343-as oklevélben található. A XVI. században egy időre elnéptelenedett, de…'),
    ('Marcaltő', 'A szomszédos települések: észak felől Sobor, északkelet felől Malomsok, kelet felől Takácsi, délkelet felől a községhez tartozó, egykor önálló Ihász, dél felől Nemesgörzsöny, nyugat felől Egyházaskesző és Várkesző, északnyugat felől pedig Rábaszentandrás. Ihász településrésze révén délkelet felől Pápa városával is határos, habár a pápai belváros és Marcaltő központja között csaknem 16 kilométernyi a távolság.'),
    ('Markaz', 'Markaz a Mátra hegység lábánál, Gyöngyöstől 14 kilométer-re, a Verpeléten át Egerig vezető 2416-os út mentén található. Északról erdős vidék, délen 154 hektár vízfelületű tó határolja. Az itt élők szőlőműveléssel és bortermeléssel foglalkoznak. A falu határában napfényben gazdag, optimális mikroklímájú területen már az 1400-as évektől gondosan művelt szőlők díszlenek, amelyekből kiváló minőségű, karakteres borokat készítenek a borosgazdák.'),
    ('Markotabödöge', 'A mai községet a Keszeg-ér szeli ketté, a korábban önálló Markota község a vízfolyástól délkeletre, Bödöge pedig attól északnyugatra jött létre. István magyar király Nyáry Lőrincnek adta Bedegh néven a települést. Markota 1222-ben Péter ispán birtokában volt.'),
    ('Markóc', 'Barcstól 25 kilométerre délkeletre, Szigetvártól 20 kilométerre délre, Sellyétől légvonalban nagyjából 5, közúton 7-8 kilométerre helyezkedik el. A déli (magyar-horvát) országhatártól és a Drávától ugyancsak mintegy 5 kilométerre fekszik északi irányban. Egyutcás kistelepülés. Markóc nevét az oklevelekben 1403-ban említették először Markochel néven, később 1492-ben Markowcz néven írták.'),
    ('Maroslele', 'A falutól nem messze torkollik a Maros a Tiszába. A két folyó szabályozása előtt gyakran árvízjárta vidék volt, ahol hatalmas nádasok, ingoványos mocsarak borították a tájat. A falu réti agyagra épült, amely száraz időben mélyen berepedezik, tartós esőzés után pedig könnyen sártengerré változik. A nyár igen meleg, a napsütéses órák száma eléri a 2050-et.'),
    ('Martfű', 'A megye székhelyétől, Szolnoktól kb. 18 kilométer-re, Budapesttől kb. 120 kilométer-re fekszik. Szomszédos települések: Tiszaföldvár (dél felé, kb. 6 kilométer), Mezőhék (kelet felé, kb. 10 kilométer), Kengyel (északkelet felé, kb. 10 kilométer), Rákócziújfalu (északnyugat felé, kb. 10 kilométer), illetve a Tisza jobb partján Vezseny. Természetföldrajzilag az Alföld Közép-Tisza-vidék középtájának Szolnok-Túri-sík nevű kistáján fekszik, a Tisza folyó egyik nagy kanyarulatánál, annak bal partján.'),
    ('Martonfa', 'A falu és környéke már a bronzkorban lakott volt. Később kelták éltek e vidéken helyezkedik el. Martonfa nevét először 1015-ben említették a pécsváradi apátság alapítólevelében, Mortun néven. A pécsváradi apátság alapítólevele szerint I. István király 1015-ben adta az apátságnak. 1158-ban II. Géza király visszaítéli az apátságnak Martonfalva tizedeit a pécsi püspökkel szemben. 1292-1297 körül az apátság idevaló jobbágyait említik.'),
    ('Martonvásár', 'A megye összes (mind a 12) nagyközsége is nagyobb területen fekszik nála. A településen keresztülfolyik a Szent László-patak. Különálló településrésze Orbánhegy, egy mezőgazdasági jellegű külterületi lakotthely, mely Martonvásár központjától 1,6 kilométerre fekszik északnyugati irányban. A 2011. évi népszámlálás adatai szerint a lakónépessége 133 fő, a lakások száma 55, továbbá az egyéb lakott lakóegységek száma 6 volt.'),
    ('Martonyi', 'Szendrőtől 10, Miskolctól mintegy 50 kilométerre északra található. Zsáktelepülés, közúton csak a 2613-as útból Szalonna külterületén kiágazó 26 123-as úton érhető el. A terület már az őskorban is lakott volt. Az első írásos adat a településről 1249-ből származik. Ekkor Martonyi Szalonnához tartozó föld volt, amit az Örsúr nembéliek eladtak Tekus sárosi ispánnak és testvéreinek, és ekkor leírták határát.'),
    ('Maráza', 'Pécsváradtól délkeletre fekszik, a Geresdi-dombság déli lábainál. A szomszédos települések: észak felől Geresdlak, délkelet felől Erdősmárok, dél felől Liptód, délnyugat felől Szellő, északnyugat felől pedig Kékesd. Még az 1887 évi kataszteri térképen is fel volt tüntetve a mai Maráza elődje, Alsó- és Felső-Hidága Maráza északi és keleti felén. Hidágát az oklevelek 1292-1297 között említették először, Hidagay néven, mint a hídágai nemesek birtokát.'),
    ('Maróc', 'A község első említése 1408-ból származik: Maroth, 1426-ban Moroch, 1435-ben Maróczlakus, 1786-ban Marócz elnevezéssel találkozunk. A név eredete bizonytalan, többféle magyarázat is ismeretes. Vannak akik szerint a latin eredetű Mauritius személynév magyarosítása, mások a szláv eredetű moravci (morvák), vagy a magyar Marót személynévből vezetik le.'),
    ('Marócsa', 'Marócsa zsáktelepülés Sellyétől északnyugatra helyezkedik el. Bár közigazgatási területén áthalad a kisvárost Szigetvár, illetve Szentlőrinc térségével összekötő 5806-os út, a falu belterülete kiépített közúton csak Kákics irányából érhető el, az 58 153-as számú mellékúton. A lehetséges verziók közül az A jelű nyomvonalváltozat ugyan valamelyest elkerülné keletről a község területét, de a B változat közvetlenül a falu határában haladna el.'),
    ('Matty', 'Siklóstól 7 kilométerre dél-délnyugatra fekszik, Alsószentmárton és Gordisa között, a Drávától és a horvát határtól mintegy 4 kilométerre északra, a Külső-Drávaszögben. Keselyőspuszta nevű településrésze, mely közvetlenül az országhatár mellett fekszik, csak az 57 123-as számú mellékúton érhető el, a településközpont felől. A település nevét már egy 1221-ből fennmaradt oklevél is említette Moch alakban írva. 1355-ben is Moch alakban írták.'),
    ('Mecseknádasd', 'A Duna–Dráva Nemzeti Park részeként, a Kelet-Mecsek Tájvédelmi Körzet határán, az Öreg-patak festői fekvésű völgyében helyezkedik el. A falu a Mecsek keleti szélén húzódik, ott, ahol a hegyvidék keleti irányban a Baranyai-dombság lankáivá szelídül. A közigazgatási terület egy része már a Geresdi-dombsághoz tartozik. Ezen érhető el Pécs és az ország északabbi részei felől is.'),
    ('Mecsekpölöske', 'Az első írásos emlék 1332-ben említi először a falu nevét Pyliske formában, az itt folyó patak szláv eredetű neve után, a falu 1898-ban nyerte el mai nevét. 1462-ben Töttösök birtokaként volt számontartva. A település a török időkben alatt is lakott volt. Az itt élő emberek kőbányászattal, mészégetéssel, állattenyésztéssel és földműveléssel foglalkoztak.'),
    ('Mecsér', 'Érdekesség, hogy Ásványráró és Mecsér vonalában húzódik az Alsó- és Felső-Szigetközt elválasztó botanikai határ. Mosonmagyaróvár szennyvízterhelése egészen Mecsér községig érezteti hatását. Mecsér községtől egészen Győr határáig első osztályú, fürdésre is alkalmas a Mosoni-Duna vize. Nyelvészek szerint neve szláv eredetű és kardművest jelent. Herényi István munkájában 1189 és 1208 közötti időszakra jelöli a település megjelenését.'),
    ('Medgyesbodzás', 'Orosházától keletre, Csanádapáca és Medgyesegyháza között fekvő település. Szomszédai: észak felől Csabaszabadi, északkelet felől Pusztaottlaka, kelet-délkelet felől Medgyesegyháza, dél felől Magyarbánhegyes, délnyugat felől Nagybánhegyes, nyugat felől pedig Csanádapáca. Északkelet felől viszonylag közel fekszik hozzá Újkígyós is de közigazgatási területeik nem érintkeznek egymással.'),
    ('Medgyesegyháza', 'Békéscsabától mintegy 20 kilométerre délre fekszik, a megye délkeleti részén. Szomszédai: észak felől Pusztaottlaka és Újkígyós, északkelet felől Kétegyháza, kelet felől Nagykamarás, délkelet felől Almáskamarás, dél felől Kunágota, délnyugat felől Magyarbánhegyes, nyugat felől pedig Medgyesbodzás. A város a Gyula-Makó közti 4434-es és a Csanádapáca-Kevermes közti 4429-es utak kereszteződésében fekszik, e két út valamelyikén érhető el mind a négy égtáj irányából.'),
    ('Medina', 'Nevének feltételezhetően nincs köze a szaúd-arábiai Medinának, az iszlám egyik szent városának nevéhez, melynek jelentése város (المدينة – al-Madína). A falu Szekszárdtól kb. 20 kilométer-re északra fekszik, a Sió csatorna jobb partján. Környező települések: Kölesd, Szedres és Felsőnána. 1394-ben egyházi birtokként említik először. 1446-ban Mede néven említik.'),
    ('Meggyeskovácsi', 'A Rába völgyében, annak bal parti oldalán fekszik. Sokáig két különálló község volt, melyek közül Balozsameggyes fekszik délebbre, Rábakovácsi pedig jó 2-3 kilométerrel északabbra. A szomszéd települések: észak felől Ikervár, kelet felől Bejcgyertyános, délkelet felől Egervölgy, dél felől Rum, nyugat felől Csempeszkopács, északnyugat felől pedig Pecöl és Megyehíd.'),
    ('Megyaszó', 'A Hernád mellett fekszik, a folyó bal parti oldalán. A szomszédos települések: észak felől Szentistvánbaksa (4 kilométerre), északkelet felől Monok (13 kilométerre), délkelet felől Legyesbénye (8 kilométerre), dél felől Újharangod (Gesztely különálló településrésze), nyugat felől pedig Alsódobsza (4 kilométerre).'),
    ('Megyehíd', 'Szombathelytől 20 kilométerre keletre, a Gyöngyös-patak mellett fekszik. Főutcája a 8443-as út, közúton csak azon érhető el a megyeszékhely Szombathely, illetve Ikervár felől is. Neve határpatakján, a Gyöngyösön átívelő híddal kapcsolatos. Az Árpád-korban királynéi birtok, mint azt az egykor létezett Famia falunév (Eufémia királyné nevéből) is mutatja. 1237-ben Megyehyd, 1409-ben Megehyd, 1466-ban Kysmegehed, 1469-ben Megyehyd néven szerepel az írott forrásokban.'),
    ('Megyer', 'A Marcal-medencében, a Marcal folyó bal partján fekszik, Rigácstól kb. 2 kilométerre. A 15,4 ha belterületével és az azon fekvő 20 házával hazánk legkisebb önálló települése. A települést először 1332-ben említik meg az oklevelek. Ekkor a debrentei vár tartozéka, a Himfi-család birtokában. A Pápai-családoknak is voltak itt birtokrészei. Mátyás király 1464-ben a Kanizsaiaknak adta.'),
    ('Mekényes', 'A tolnai megyehatár közelében, a Völgységben, a Méhész-patak mellett fekszik. A szomszéd települések: Nagyhajmás (5,5 kilométerre), Lengyel (7,5 kilométerre) és Kurd (8,5 kilométerre). Mekényes egy korábban elpusztult rác falu után kapta nevét, mely a település és Nagyhajmás közt levő völgyben feküdt. A mai falu alapítói a XVIII. században Herrnhut-Darmstadtból bevándorolt német telepesek voltak.'),
    ('Mencshely', 'Nevezik háromtornyú falunak is, mivel három felekezetnek is van temploma a településen. A Balatontól 11, Nagyvázsonytól 4 kilométerre található. Területe a kőkorszaktól bizonyíthatóan lakott volt, de a régiek nem a mai falu helyét, hanem az attól kissé északkeletre fekvő Ragonya nevű határrészt és a falutól keletre eső Berki-kút környékét részesítették előnyben.'),
    ('Mende', 'A Gödöllői-dombság és a Monor–Irsai-dombság határán helyezkedik el, az Alsó-Tápió völgyében, amit a helyiek Barina-pataknak is neveznek. Hét dombra épült, amelyek a címerében is szerepelnek. Budapest határszélétől alig 12, a központjától 35 kilométerre keletre fekszik. A közvetlenül határos települések: északkelet felől Sülysáp, kelet felől Úri, délkelet felől Felsőfarkasd (Gomba része), dél felől Péteri, délnyugat-nyugat felől Gyömrő és Maglód, északnyugat felől pedig Pécel.'),
    ('Merenye', 'Különálló településrésze Ceglédpuszta, mely a központjától északra, mintegy 3-3,5 kilométerre helyezkedik el. Zsáktelepülés, közúton csak a 6-os főútról Nemeskénél észak felé letérve, a 66 116-os számú mellékúton érhető el. Ceglédpuszta irányába ugyanez az út már csak önkormányzati útként folytatódik tovább. Merenye valószínűleg az Árpád-kor óta lakott hely lehetett, nevét az oklevelek 1192-ben már említették. 1417-ben a budai káptalan birtokának írták, később a Batthyány, a gróf Széchenyi család, majd Festetics Imre volt birtokosa.'),
    ('Mernye', 'Kelet-nyugati irányban a Ráksitól Somogyjádig vezető, a 6505-ös és 6701-es utakat összekötő 6513-as út halad végig rajta. Mernye egy csodálatosan szép község, Somogyország szívében helyezkedik el. Érdemes ide ellátogatni. Nevét 1229-ben említették először az oklevelek Merena és Alsó-Merena alakban írva, a székesfehérvári káptalan birtokai között.'),
    ('Mersevát', 'Celldömölktől 5 kilométerre északkeletre, a Marcal folyó mellett fekszik. A szomszédos települések: észak felől Kemenesmagasi, kelet felől Külsővat, dél és délnyugat felől Celldömölk, nyugat felől Kemenessömjén, északnyugat felől pedig Kemenesszentmárton és Vönöck. Vát neve a 9. századi székely-fehér hun (kony) uralkodó Vat nevéből származik. A mai Mersevát Merse és Belsővat 1906-ban való egyesítésekor keletkezett.'),
    ('Mesterháza', 'A Répce mellett, Sárvártól 15 kilométer-re északnyugatra, Bükfürdőtől 8 kilométer-re keletre fekszik. 1426-ban Vesterháza alakban említik először. Neve a német eredetű régi magyar Vester személynévből származik. 1433-ban Vesteryazya, Vesterhazya alakban szerepel. 1479-ben említik először mai nevén Mesterhaza alakban helyezkedik el. Köznemesi volt, többször nemesi előnévként fordul elő az írott forrásokban.'),
    ('Mesteri', 'A Ság-hegy nyugati oldalán, Celldömölktől 7, Sárvártól 15 kilométerre fekszik. Két fő településrésze Felsőmesteri (ide tartozik Intaháza is) és Alsómesteri (itt található a termálfürdő). A két korábbi község 1935-ben egyesült újra helyezkedik el. A személynévként is alkalmazott magyar mester főnévből alakult, de az Alsómesteri határában virágzó korabeli városról, Mestreianaról is nyerhette nevét.'),
    ('Mesterszállás', 'Alacsony, csaknem tökéletesen sík területe a szabályozás előtt hatalmas ártér volt, melyen összefolyt a Berettyó és a Körös árvize és jellegzetes folyami üledéket hagyott maga után. A szabályozás idején a Körös zegzugos és a Tiszától csak méreteiben különböző kanyarulatait átvágták, áradásait pedig gátakkal a kanyarulatok zugaira korlátozták. A község neve először az 1524. évi összeírásban található, amikor Kolbázszékhez tartozó kunszállás volt. 1533-ban királyi birtok.'),
    ('Meszes', 'Szendrőtől 12 kilométerre kelet-északkeletre, a megyeszékhely Miskolctól közúton 45 kilométerre északra fekszik. A közvetlenül határos települések: észak felől Tornabarakony, kelet felől Rakacaszend (6 kilométer), dél felől Galvács, délnyugat felől Szendrő (12 kilométer), nyugat felől Szalonna (7 kilométer), Martonyi (6 kilométer). A legközelebbi város Szendrő.'),
    ('Meszlen', 'Szombathelytől 15 kilométerre északkeletre, a Gyöngyös-sík északi részén fekszik. A szomszédos települések: észak felől Csepreg, kelet felől Acsád, dél felől Salköveskút, délnyugat felől Vasasszonyfa, északnyugat felől pedig Tömörd. Nyugati irányból a legközelebbi település Kőszegpaty, de a közigazgatási területeik nem érintkeznek. Csak közúton közelíthető meg, Kőszeg és Acsád felől egyaránt a 8636-os úton helyezkedik el.'),
    ('Mesztegnyő', 'Gyönyörű természeti adottságokkal rendelkezik. Határának több mint a fele erdő, a patakokon halastavak létesültek és a Boronka-melléki Tájvédelmi Körzet egy része is a területén van. A Boronka ritka természeti értékeit szívesen keresik fel a magyarok és a külföldiek egyaránt. Itt vezet az Rockenbauer Pál Dél-Dunántúli Kéktúra útvonala. Jól járható kerékpárutak vannak, de gyalogosan vagy a 9 kilométer hosszú erdei kisvasúttal is utazhatunk.'),
    ('Mezőberény', 'A közvetlenül határos települések: észak felől Köröstarcsa, északkelet felől Körösladány és Bélmegyer, délkelet felől Békés, dél felől Murony és Kamut, nyugat felől Hunya, északnyugat felől pedig Gyomaendrőd és Csárdaszállás. A felsoroltak közül közúton sem Körösladánnyal, sem Gyomaendrőddel nem tűnik szomszédosnak a közbeékelődő kisebb falvak miatt, e két település határszéleivel csak külterületei révén érintkezik.'),
    ('Mezőcsokonya', 'Külterületének keleti részét érinti a Hetes-Osztopán közti 6706-os út is. Kaposvár vasútállomása 17 kilométerre fekszik innen. Mezőcsokonya községet a történetírók már 1324-ben említik. A falu a Bő nemzetség ősi birtoka volt, melyet Szent István király adományozott részükre. A középkorban két részből állt. A falunak azt a részét, ahol a Szent Márton tiszteletére szentelt egyház emelkedett, Szent Mártonnak nevezték.'),
    ('Mezőcsát', 'Miskolc és Mezőkövesd között, mindkét településtől kb. 35 kilométerre található. A megyeszékhely Miskolctól közel 35 kilométerre délre, Mezőkövesdtől hasonló távolságra délkeletre fekszik, a Borsodi-Mezőség középső részén. Tiszaújvárostól mintegy 20 kilométerre délnyugatra helyezkedik el. Itt van a végállomása a Nyékládházától induló Mezőcsát–Hejőkeresztúr-vasútvonalnak, amely a Budapest–Sátoraljaújhely-vasútvonallal köti össze a települést.'),
    ('Meződ', 'Meződ és környéke már az ókorban is lakott hely volt, területén római korból származó leletek kerültek felszínre. Nevét az oklevelek 1475-ben említették először, Mezeedként, mint a dombói uradalomhoz tartozó birtokot. A török hódoltság után Esterházy Pál herceg birtoka lett.'),
    ('Mezőfalva', 'A ciszterciek alapították 1811-ben Herczegfalva néven. A Mezőfalva nevet 1951-ben kapta. Dunaújvárostól nyugatra, 13 kilométerre, Dunaföldvártól északnyugatra, 20 kilométerre, a megyeszékhely Székesfehérvártól délkeletre, 40 kilométerre fekszik. Perkáta, Nagyvenyim, Baracs, Daruszentmiklós, Előszállás, Nagykarácsony, Sárbogárd, Nagylók és Hantos határolják.'),
    ('Mezőgyán', 'További szomszédai: észak felől Zsadány, dél felől Újszalonta, délnyugat felől Sarkadkeresztúr, északnyugat felől pedig Okány. Délkeleti irányból Romániához, jobbára Nagyszalontához tartozó területek határolják. Sarkaddal közvetlenül nem határos. Természetföldrajzi szempontból a Kis-Sárrét keleti vidékén fekszik. Közigazgatásilag hozzá tartozik Nagygyanté is, amely a település központjától 7 kilométerre nyugatra terül el.'),
    ('Mezőhegyes', 'Szomszédai: észak felől Végegyháza, északkelet felől Mezőkovácsháza, kelet felől Battonya, délnyugat felől Csanádpalota, nyugat felől Pitvaros, északnyugat felől pedig Ambrózfalva, Nagyér és Tótkomlós. Természeti adottságait tekintve különleges, kedvező természeti tényezőinek köszönhetően ősidők óta lakott hely. Kisvárosként is több száz éves múltra tekint vissza: az öreg fák, a régi épületek, a világhírű Ménesbirtok, a népszerű halastavak mind a település részét képzik.'),
    ('Mezőhék', 'Az Alföldön, a megye déli részén található, a Tiszától mintegy 10 kilométerre kelet felé, a Nagykunsági-főcsatorna mellett. Tiszaföldvártól 10 kilométerre keletre, Mezőtúrtól 18 kilométerre nyugatra található. A legközelebbi település a 6 kilométerre délkeletre fekvő Mesterszállás. A szomszédos települések: észak felől Kétpó, kelet felől Mezőtúr, délkelet felől Mesterszállás, dél felől Öcsöd, délnyugat felől Tiszaföldvár, nyugat felől Martfű, északnyugat felől pedig Kengyel.'),
    ('Mezőkeresztes', 'A környező települések: Mezőnagymihály kb. 4, Mezőnyárád 4, Szentistván kb. 8 kilométer-re. A legközelebbi nagyobb város, Mezőkövesd 11 kilométer-re található. A sztráda 139-es kilométerénél építették ki a Mezőkeresztes-Mezőnagymihály csomópontot, amely leágazástól két kilométernyire van a városközpont. Központja a Mezőnyárádtól Szentistvánig húzódó 3304-es, az abból Mezőcsát felé kiágazó 3305-ös és a Vattától Csincsén át idáig vezető 3306-os utakon közelíthető meg.'),
    ('Mezőkomárom', 'A mintegy 1000 lakosú község a Mezőföld nyugati peremén a Sió bal partján, Szabadhídvéggel szemben helyezkedik el. A mezőkomáromi szőlőkből jó bor készül. Ennek bizonyítéka, hogy a tájat az észak-tolnai borvidék részeként borvidéknek nyilvánították. A község nevének előtagja földrajzi helyzetére utal, a szláv eredetű „komárom” szó szúnyogost jelent.'),
    ('Mezőkovácsháza', 'Termálvizes gyógyfürdője van. A nem magyar nemzetiségűek aránya alacsony: a 2011. évi népszámlálás adatai szerint 1%-nál nagyobb arányban csak cigányok és románok élnek itt, nemzetiségi önkormányzata csupán az előbbieknek van. A Csanádi-háton, a román határ közelében fekszik, a Marosból kiágazó Száraz-ér mentén. Békéscsabától 45 kilométer-re délre található.'),
    ('Mezőkövesd', 'A megye negyedik legnépesebb települése. A Bükk-vidék déli szélénél, az Alföld és az Északi-középhegység találkozásánál, a Borsodi-Mezőség vidékén fekszik, Egertől 20, a megyeszékhely Miskolctól pedig 50 kilométerre. A közvetlenül határos települések: észak felől Bogács és Tard, északkelet felől Mezőnyárád, kelet felől Mezőkeresztes, délkelet felől Szentistván, dél felől Egerlövő és Egerfarmos, délnyugat felől Mezőszemere, nyugat felől Szihalom, északnyugat felől pedig Novaj és Szomolya.'),
    ('Mezőladány', 'A közvetlen szomszédos települések: észak felől Benk, kelet felől a folyó túlpartján fekvő Mátyus, délkelet felől a szintén túlparti Tiszakerecseny, dél felől Újkenéz, nyugat felől Tornyospálca (utóbbival szinte teljesen összenőtt), északnyugat felől pedig Mándok. A térség fontosabb települései közül Mándok6, Tuzsér 12, Záhony 20, Vásárosnamény 22, Aranyosapáti 7,5, Benk 5,5, Eperjeske pedig 11 kilométer távolságra található.'),
    ('Mezőlak', 'Pápa nyugati vonzáskörzetében helyezkedik el, a város központjától légvonalban alig több mint 7 kilométerre. A további szomszédos települések: észak felől Nagyacsád, délkelet felől a Pápához tartozó Borsosgyőr, délnyugat felől Mihályháza, nyugat felől pedig Békás. Nagy kiterjedésű külterületi határrészei a fentieken túl érintkeznek még északnyugati irányban Kemeneshőgyész, Magyargencs és Nemesgörzsöny határszéleivel is.'),
    ('Mezőnagymihály', 'A megye déli részén, a Kácsi-patak mentén található, Miskolctól 40 kilométerre délre. Ez a táj síkföld, igazi kis alföld szél. Erdeit a végvári harcok idején kivágták. A terület lápos és ingoványos terület szélén helyezkedett el, mely Borsodi Mezőség Tájvédelmi Körzet néven védett puszta. A szikfoltos területek a múlt század ötvenes-hatvanas éveiben végzett vízszabályozás következményei.'),
    ('Mezőnyárád', 'A közvetlen szomszédos települések: észak felől Bükkábrány (3 kilométer), dél felől Mezőkeresztes (4 kilométer), délnyugat felől Mezőkövesd (10 kilométer), nyugat felől Tard, északnyugat felől pedig Tibolddaróc. A nyárád szó olyan vízfolyást vagy más vizes területet jelent, amelynek környékén sok a nyárfa. Nyárád, vagy Nyárágy nevű személynév is volt, így eredhet a neve személynévből is.…'),
    ('Mezőpeterd', 'A Bihari-síkon található, az Ölyvös-ér közelében. A szomszédos települések: észak felől Váncsod, délkelet felől Biharkeresztes, dél felől Told, nyugat felől pedig Berettyóújfalu. Autóbusszal elérhető Berettyóújfalu, Váncsod, illetve Biharkeresztes felől is. A község első írásos említése 1291-ből való, a 16. század végén lakott hely magyar népességgel.'),
    ('Mezősas', 'Természetföldrajzi szempontból a Bihari-sík központi vidékén, a Kutas-főcsatorna partján fekszik. Szomszédai: észak felől Berettyóújfalu, kelet felől Told, délkelet felől Körösszegapáti, dél felől Magyarhomorog, nyugat felől pedig Furta. Közúti kapcsolata csak Berettyóújfaluval és Körösszegapátival van. Az első írásos emlék a faluról 1213-ból való.'),
    ('Mezőszemere', 'Belterületét az Rima-patak szeli ketté. A közvetlen szomszédos települések: észak felől Mezőkövesd, délkelet felől Egerfarmos, délnyugat felől Mezőtárkány, északnyugat felől pedig Szihalom. Az ország távolabbi részei felől közúton a legegyszerűbben a már említett 3-as főúton közelíthető meg, Szihalomnál letérve.'),
    ('Mezőszentgyörgy', 'Mezőszentgyörgy a Mezőföld szívében, a Balatontól légvonalban alig több mint 8 kilométerre fekvő település. A település a nevét a juhászok védőszentjéről, Sárkányölő Szent Györgyről kapta, ez alapján feltehető, hogy az alapítói a XIII-XIV. század fordulóján itt letelepült pásztorok lehettek. Már 1249-ben említi hivatalos oklevél, mint a székesfehérvári káptalan birtokát.'),
    ('Mezőszilas', 'A településen és környékén a legrégibb idők óta élnek emberek. Alsóbogárd-pusztán őskori földvár nyomaira bukkantak. Az időszámítás előtt e tájat a kelta eraviscus nép lakta. Kelta sírok kerültek elő a Józan-hegy lábánál helyezkedik el. Később a rómaiak uralma alá tartozott a területet. Ebben az időben Fortiana néven kisebb római telep/őrállomás volt e helyen.'),
    ('Mezőtárkány', 'Jellegzetes halmazfalu. Füzesabony délkeleti szomszédságában helyezkedik el, a város központjától mintegy 3-4 kilométerre délkeletre. A további szomszédos települések: észak felől Szihalom, északkelet felől Mezőszemere, kelet felől Egerfarmos, dél felől Kömlő, délnyugat felől Átány és Besenyőtelek, nyugat felől pedig Dormánd. Délkelet felől ugyancsak Besenyőtelekhez tartozó, de jobbára lakatlan külterületek határolják.'),
    ('Mezőtúr', 'A várost keresztezi a Hortobágy-Berettyó csatorna. Szomszédai: észak felől Örményes, északkelet felől Túrkeve, kelet felől Gyomaendrőd, dél felől Szarvas, délnyugat felől Békésszentandrás és Mesterszállás, nyugat felől Mezőhék, északnyugat felől pedig Kétpó. Ezen felül a város területén mindkét vasútvonalnak egy-egy megállási pontja van még: a fővonalon Csugar megállóhely a nyugati határszélen, ahová a 46 346-os út vezet, az orosházi vonalon pedig Pusztabánréve megállóhely, a déli…'),
    ('Mezőzombor', 'A közvetlenül határos települések: észak felől Mád, kelet felől Bodrogkeresztúr, délkelet felől Tarcal, dél felől Prügy, nyugat felől pedig Szerencs. A község Árpád-kori település. Nevét az oklevelek 1298-ban említették először. Ekkor Rátót nemzetségbeli…'),
    ('Mezőörs', 'A község a megye délkeleti részén, Győrtől 20 kilométerre helyezkedik el. Pannonhalmától keleti irányban, 12 kilométerre helyezkedik el. A települést északról a Hideg-ér, Kisbér felől a Bakony-ér határolja. A Bakony-ér még a 18. század közepén is járhatatlan mocsárrá változtatta a község déli részeit, így az alapjaiban a rómaiak által épített kőúton csak a mezőörsi hídon lehetett továbbjutni.'),
    ('Miháld', 'A terület régóta lakott hely, illírek, kelták, avarok éltek itt. A község első írásos említése 1121-ből való, az almádi monostor alapító oklevelében 1332 és 1337 között: Mihad. A név a Mihály személynévből keletkezett. A község nevét Szent Mihály arkangyalról, a falu védőszentjéről kapta. A falunak voltak szlovén lakói a 18. és 19. században, akik a Mura folyó vidékéről telepedtek le, mert evangélikus vallásuk miatt katolikus uraik elüldözték őket.'),
    ('Mihályfa', 'A település a Sümegtől Szalapán és Zalabéren át Zalaegerszegig vezető 7328-as út mentén fekszik, Sümegtől mintegy 7 kilométerre. Központjából ágazik ki déli irányban a 73 166-os út Óhíd község felé, a falutól keletre pedig a 73 165-ös északnak, Kisvásárhely központjába. A település neve 1340-ben bukkant fel oklevelekben Mihalfalwa néven helyezkedik el.'),
    ('Mihálygerge', 'A Dobroda-patak völgyében, a Karancs hegység északi vonulatai között fekszik Mihálygerge, az Ipoly-vidék jellegzetes szalagtelepülése. Litkétől 3, Salgótarjántól 18 kilométerre fekszik. A falutól, amely a Novohrad-Nógrád UNESCO Globális Geopark települése, légvonalban nincs messze az Ipolytarnóci Ősmaradványok Természetvédelmi Terület sem. Két különálló területrészből áll, melyek közül a keletebbi lényegesen kisebb a másiknál és csak lakatlan külterületek alkotják, viszont az északi határszéle egybeesik az államhatárral.'),
    ('Mihályháza', 'Pápa tágabb nyugati vonzáskörzetében fekszik. A szomszédos települések: észak felől Békás, északkelet felől Mezőlak, kelet felől Pápa-Borsosgyőr, kelet-délkelet felől Pápadereske, délkelet felől Nyárád, délnyugat felől Nemesszalók, nyugat felől Vinár, északnyugat felől pedig Kemeneshőgyész. Közigazgatási területe a fentiek mellett, nyugat-északnyugati irányból pontszerűen érintkezik még Szergény keleti határszélével is.'),
    ('Mihályi', 'Magyarország északnyugati részén, a Kisalföldön, a Rábaközben a Kis-Rába két oldalán fekszik. Soprontól keletre 50 kilométerre, Kapuvártól délre 10 kilométer távolságra helyezkedik el. A szomszédos települések: észak felől Kisfalud, északkelet felől Bogyoszló, kelet felől Magyarkeresztúr, délkelet felől Vadosfa, dél felől Beled, nyugat felől pedig Gyóró és Himod.'),
    ('Mike', 'Kaposvártól mintegy 23 kilométerre délnyugatra fekszik, a megye középső részén. A legközelebbi város a tőle keletre elterülő Kadarkút. Központján a Kaposfő és Lábod közti 6616-os út vezet keresztül, ezen érhető el Kaposvár és Nagyatád, a 61-es és a 68-as főutak felől is. Története egészen a korai időkre nyúlik vissza, amire a környéken talált avar, kelta, római és a honfoglalás korából származó leletek alapján lehet következtetni.'),
    ('Mikebuda', 'Budapest központjától légvonalban 55, közúton mintegy 64 kilométer-re délkeletre helyezkedik el. Mikebuda a 13. század második felében alakult ki Mikebuda Felső[forrás?] (Öcsödbuda) és Telekpuszta (Örsbuda) elpusztult helységek, valamint Csőke, Felsőlenc, Dánosi út, Erkusbuda, Szarvas részpusztákból helyezkedik el. A falu határában három Árpád-kori templom romja máig látható.'),
    ('Mikekarácsonyfa', 'Mikefa és Karácsonyfa települések egyesítésével jött létre 1941-ben. A Zalai-dombság területén, ezen belül a Göcsejben fekszik, négy kilométerre délre a tájegység központjának számító Novától. Lankás dombok veszik körül, a környéken sok az erdő. A települést a Cserta patak szeli ketté: Mikefa a bal (keleti), Karácsonyfa a jobb (nyugati) parti oldalra esik.'),
    ('Mikepércs', 'Elsődleges értéke a falusias környezete. A természeti szépségekben és megőrzött hagyományokban, értékekben gazdag település az Alföld és az Erdőspuszták határán fekszik, ezért is nevezik Erdőspuszta kapujának. Természeti környezete a tipikus alföldi tájból vezet át a változatos domborzatú, vadászható állatfajokban gazdag „erdős-pusztákra”. A szomszédos települések: észak felől Debrecen, délkelet felől Hajdúbagos, dél felől Sáránd, nyugat felől Hajdúszoboszló, északnyugat felől pedig Ebes.'),
    ('Miklósi', 'A Balatontól délre, a kelet-somogyi várostól, Tabtól 14 kilométerre fekszik ez a néhány száz lelkes kis község. Központján a Szorosadtól Kapolyig húzódó, a 6508-as és 6511-es utakat összekötő 6516-os út halad végig. A távolabbról érkezők a legegyszerűbben talán a Kaposvár–Szántód közti 6505-ös út felől közelíthetik meg, a település egy, az előbbi úttal párhuzamos országút mentén terül el.'),
    ('Mikosszéplak', 'Vasvár közelében, attól 13 kilométerre keletre fekszik. Zalaegerszegtől északra, Szombathelytől délkeletre található. A település földesurai a 13–14. században a Németújváriak voltak, majd a Kanizsai család is szerzett itt birtokrészeket. A Kanizsai családtól az 1530-as években a Nádasdy család tulajdonába került a falu.'),
    ('Mikófalva', 'A Bükk-vidéken fekszik, Bélapátfalva nyugati szomszédságában. A további szomszédos települések: észak felől Balaton, északkelet felől Bükkszentmárton, délkelet felől Mónosbél, délnyugat felől Egerbocs, nyugat felől Egercsehi, északnyugat felől pedig Bekölce. Mikófalva egykor a Bél nemzetség ősi birtoka volt. A nemzetség a 13. század vége felé ősi birtokain, nemzetségi javakain megosztozott.'),
    ('Mikóháza', 'A Zempléni-hegység északkeleti részén helyezkedik el, a Bózsva-patak völgyében. A környező települések közül Alsóregmec körülbelül 3, Vilyvitány és Sátoraljaújhely-Széphalom 5-5 kilométerre fekszik. A legközelebbi város a 7 kilométerre lévő Pálháza, Sátoraljaújhely város központja pedig mintegy 10 kilométer távolságra van a községtől. Megszüntetéséig érintette a Hegyközi Kisvasút is, melynek nyomvonalán az utóbbi években nagyrészt kerékpárút épült.'),
    ('Milejszeg', 'A 908 hektáros területen fekvő faluban háromszázkilencen laknak és 40,64 fő/km² a népsűrűség. Észak-Göcsej dombvidékén épült település a Cserta folyó partján és a mellette fekvő két dombháton helyezkedik el. A falu külterületének nyugati részén ered a Jám-patak, Babosdöbréte és Milejszeg közt pedig a Pálosfai-patak folyik. A község Zalaegerszegtől 14 kilométerre található, Teskánd–Dobronhegy irányában.'),
    ('Milota', 'Tiszabecs 5 kilométer, Szatmárcseke 14 kilométer, Tiszacsécse 4 kilométer, Túristvándi 14 kilométer, Fehérgyarmat 28 kilométer, Kölcse 7 kilométer távolságra található. Milota és környéke már a honfoglalás idején lakott hely lehetett, amire a település nevét adó Milota (Mélóta)-monda is utal: A monda szerint Mélótát itt, a község régi helyén temettette el Árpád fejedelem.'),
    ('Mindszent', 'Mindszent a Tisza bal partján fekszik, a Kurca-patak torkolatánál, változatos felszínű és tagoltságú tájon, Szentes és Hódmezővásárhely között félúton. Szomszédai: észak felől Szegvár, északkelet felől Derekegyház, délkelet felől Hódmezővásárhely, dél felől Mártély, délnyugat felől Dóc, nyugat felől Baks, északnyugat felől pedig Csanytelek (mindhárom utóbbi a Tisza túlpartján).'),
    ('Mindszentgodisa', 'A Zselic északkeleti részén, Sásd délnyugati szomszédságában helyezkedik el, Pécstől és Kaposvártól is közel azonos távolságra, nagyjából 30-35 kilométerre. Könnyen elérhető Dombóvár és Komló felől is. A közvetlenül határos települések: észak felől Palé, északkelet felől Sásd, kelet felől Oroszló, délkelet felől Bodolyabér, dél felől Kishajmás, délnyugat felől Kisbeszterce, nyugat felől Bakóca és Tormás, északnyugat felől pedig Baranyaszentgyörgy és Baranyajenő.'),
    ('Mindszentkálla', 'Mindszentkálla a Balatontól északra, a Káli-medencében helyezkedik el, a szomszédságában fekvő települések Káptalantóti, Kékkút és Szentbékkálla. Közigazgatási területének déli részén végighalad a Zánka és Gyulakeszi között közel 20 kilométeren húzódó 7313-as út, belterületét azonban csak a 73 135-ös út érinti, amely 7313-asból ágazik ki észak felé Szentbékkálla déli külterületén, majd miután végighalad annak központján, Mindszentkálla érintésével visszatér a 7313-asba.'),
    ('Misefa', 'A néhány utcából álló kistelepülés a zalai dombok között fekszik, a Principális-völgyben, a Keszthelyi-öböltől bő fél órányi autóútra, Zalaegerszegtől 15, Keszthelytől 30, Budapesttől 208 kilométer távolságra. Misefa valószínűleg a 13. században keletkezett magyar falu, első ismert említése Myxefolva, 1352-ből származik. A településnév minden bizonnyal a magyar Mikse személynév és a falva összetételéből, majd elrövidüléséből jött létre.'),
    ('Miske', 'Az Alföld nyugati részén, a Duna bal parti oldalán található, a folyótól légvonalban mintegy 8 kilométerre. Budapesttől mintegy 130 kilométerre délre fekszik, Kalocsától pedig 10 kilométerre délkeletre. A szomszédos települések: észak felől Drágszél, északkelet felől Homokmégy, kelet felől Hajós, dél felől Dusnok, délnyugat felől Fajsz, északnyugat felől pedig Bátya.'),
    ('Miskolc', 'Miskolc Magyarország északkeleti részén, a Bükk-vidék keleti lejtőinél helyezkedik el. Az Észak-Magyarországi régió központja és legnagyobb települése. Az ország negyedik legnépesebb települése Budapest, Debrecen és Szeged után, agglomerációval együtt Budapest és Debrecen után a harmadik legnagyobb, illetve a harmadik legnagyobb belterülettel/beépített területtel rendelkező város (54,21 km²) Magyarországon Budapest és Debrecen (68 km²) után, teljes terület szerint pedig az ország hatodik legnagyobb városa, 236,66 km² közigazgatási területével.'),
    ('Miszla', 'Pincehelytől délre, Gyönktől északra, Nagyszékelytől délnyugatra fekszik. Központja csak a 63 118-as számú mellékúton érhető el, amely Gyönk központjában ágazik ki észak felé a 6313-as útból. A település népességének változása: A 2011-es népszámlálás során a lakosok 95,7%-a magyarnak, 0,4% cigánynak, 1,1% németnek, 0,4% örménynek, 0,4% románnak, 0,4% szerbnek mondta magát (3,9% nem nyilatkozott.'),
    ('Mocsa', 'A Kisalföld keleti szegletében fekszik, a Bársonyos-dombsor lábánál. Határában található a Boldogasszonyi-tó. Komáromtól és Almásfüzitőtől 11-11, Tatától 12, Kocstól 7 kilométer távolságra található. Mocsa első írásos említése 1237-40-ből való, Macha alakban. 1266-ban nagyobbrészt királyi harcos jobbágyok és pohárnok bocsárok lakták. Jövedelmét a királyné udvartartásának fenntartására rendelték. 1284-ben IV.'),
    ('Mogyoród', 'Legmagasabb pontja a Somlyó-domb (Gyertyános 326 méter), amely már az sztrádáról is messziről látszik. Egyik határdombja a szomszédos Fótra árnyúló Kukukkhegy, továbbá Gödöllővel, Szadával, Veresegyházzal, Fóttal, Kerepessel és Csömörrel határos. Fekvésének sajátossága, hogy a lüktető, mozgalmas főváros alig néhány percre van autóval, a település azonban megőrizte nyugodt, falusias légkörét.'),
    ('Mogyorósbánya', 'A Gerecse északi nyúlványai alatt terül el, Tatabányától és Tatától egyaránt 28–28, Esztergomtól 15, Táttól 5 kilométer távolságra. Közelében található a Kőszikla-hegy. Mogyorósbánya (régi nevén Mogyorós) és környéke ősidők óta lakott hely, ahol kő- és római kori leletek kerültek elő a földből, de földvár maradványaira is bukkantak itt. Első írásos említése 1269-ből való, ekkor Munorod, Munoros, 1277-ben Moniorous alakokban jelenik meg neve az oklevelekben helyezkedik el.'),
    ('Mogyoróska', 'A közvetlenül szomszédos települések: észak felől Regéc, északkelet felől Háromhuta, délkelet felől Erdőhorváti, dél felől Baskó, nyugat felől pedig Fony. Fony és Regéc egyaránt nagyjából 4-4 kilométerre található, a többi szomszédjától ennél nagyobb távolságok választják el. A két legközelebbi város a 21 kilométerre lévő Abaújszántó és a 25 kilométerre fekvő Encs.'),
    ('Moha', 'A Móri-árokban, a Gaja-patak mentén fekszik. A legközelebbi város Székesfehérvár, 9 kilométerre helyezkedik el. Első írásos említése az 1240-es évekből származik, de a település határában a neolitikumból és a bronzkorból származó leleteket is találtak. A faluban 1330-ban már kőtemplom állt. A 16. század közepén a török hódítások miatt elnéptelenedett, a törökök kiűzése után az Amadé család birtokába került.'),
    ('Mohora', 'Balassagyarmattól mintegy 10 kilométerre délre fekszik. Főutcája a 2108-as út, közúton ezen érhető el Aszód és Balassagyarmat irányából is. Keleti szomszédjával, Cserháthaláppal és az attól keletebbre fekvő községekkel a 2123-as út köti össze. A címer: Fő alakja egy szakállas török vitéz, fejét hátrakötött hátul lefelé lengő ezüst(fehér) kendő fedi, homlokát arany abroncs veszi körül.'),
    ('Mohács', 'Ez Magyarország legdélebbi Duna-parti települése, leszámítva Kölkedet és Homorúdot, melyeknek vannak még délebbi fekvésű dunai partszakaszai is, de lakott területeik a folyótól távolabb fekszenek. A várostól délre történt 1526. augusztus 29-én a történelmi jelentőségű mohácsi csata, melynek során a magyar sereg igen súlyos vereséget szenvedett a török túlerővel szemben.'),
    ('Molnári', 'A településen polgárőrség működik. Nagykanizsától délnyugatra 16 kilométerre, Letenyétől pedig délkeletre 10 kilométerre található, mintegy 500 méterre a Mura folyótól, amely itt határfolyó Magyarország és Horvátország között. A községet először Molnáry alakban egy 1321-re keletkezett hamis oklevélben említik, mint a kanizsai vár tartozékát, amelyben több nemesnek volt birtoka. 1778-ban – és később is sokszor – Mlinarcénak nevezik, a helybeliek közül többen ma is így mondják.'),
    ('Molvány', 'Szigetvár nyugati-délnyugati szomszédságában fekszik, a város központjától körülbelül 5 kilométerre. A további szomszédos települések: észak felől Patapoklosi, délkelet felől Hobol, dél felől Várad, délnyugat felől Gyöngyösmellék és Kistamási, nyugat felől Nemeske, északnyugat felől pedig Tótszentgyörgy. Zsáktelepülés, közúton csak egy útvonalon érhető el, a 6-os főútról leágazó, körülbelül 1,5 kilométer hosszú 58 108-as számú mellékúton.'),
    ('Monaj', 'A Cserehát középső részében helyezkedik el, Szikszótól 15 kilométerre északra, a megyeszékhely Miskolctól közúton kb. 32 kilométerre északkeletre. A közvetlenül határos települések: észak felől Selyeb (5 kilométer), kelet felől Rásonysápberencs, délkelet felől Léh, dél felől Homrogd (kb. 4 kilométer), délnyugat felől Hangács, nyugat felől Tomor (kb. 8 kilométer), északnyugat felől pedig Kupa (kb. 5 kilométer).'),
    ('Monok', 'A település a Tokaj-hegyaljai Történelmi Borvidék és a világörökség részét képezi. A Zempléni-hegységhez két földtanilag különálló egység csatlakozik, északon a Vilyvitányi-röghegy, délen pedig a Szerencsi-dombvidék. A hegyek ölelésében a Szerencsi-dombság lankás tája oltalmában fekszik a település. Az említett dombság a Hernád folyó és a Tokaji-hegység déli része között terül el és öt észak-déli irányú vonulatra tagolódik.'),
    ('Monor', 'A románul és 1912-ig magyarul is azonos nevű erdélyi települést lásd itt: Monorfalva. Monor Budapesttől 25, Magyarország mértani középpontjától, Pusztavacstól kb. 20 kilométerre található. A város a Duna–Tisza közi homokhátságon, a Pilis–Alpári-homokhát és a Monor-Irsai dombság találkozásánál helyezkedik el, legmagasabb pontja, az Alföldbe simuló Strázsa-hegy (190 méter), mely a hagyomány szerint arról kapta a nevét, hogy a török korban innen kémlelték a környéket, őrizve a falut a portyázó török katonáktól.'),
    ('Monorierdő', 'A Cserhátvidékhez tartozó Gödöllői-dombság része a Monor-Irsai dombság már csak szelíd dombvidék a község északi határán. Felszíne gyengén, helyenként közepesen tagolt. Monorierdő határában, a Monor-Irsai dombságon a tetőszintek átlagosan csupán 150 méter magasak. A Gödöllői-dombság utolsó nyúlványai – úgy is mondják errefelé: „a hegyek kis körme”.'),
    ('Monostorapáti', 'A mai Monostorapáti közigazgatási területén a középkorban több település is létezett:közülük Almád oppidum, mely egykor Hegyesd tartozékai közé tartozott, valamint Győr, Csekőháza, Attak és Bécs, mára már elpusztult települések is. Ezeket a neveket többek között a korabeli adózási jegyzékek őrizték meg az utókor számára. Monostorapáti lakóinak egy része is az egykori Almád lakóinak leszármazottja, a falu ma élő lakói is Almádot tekintik községük ősének.'),
    ('Monostorpályi', 'Területe mintegy 80%-ban a Nyírséghez tartozik. A szomszédos települések: észak felől Debrecen, északkelet felől Újléta, kelet felől Létavértes, dél felől Pocsaj, nyugat felől pedig Hosszúpályi. Vasúton jelenleg nem érhető el. A terület mai felszíni képe a földtörténet negyedkorában alakult ki. Legelterjedtebb talajtani képződmény a futóhomok. Az egykori lefolyástalan, vízzel borított területek legjellemzőbb képződménye a kotu, amely szerves anyagoknak humuszos iszappal történő keveredése.'),
    ('Monoszló', 'A Balatontól 6 kilométerre északra, a Káli-medence keleti szomszédságában megbújó, mindössze két község területét magában foglaló, kis Monoszlói-medencében található. Ez a terület a Balaton-felvidék egyik legrejtettebb völgye, áthaladó útja 2019-ig nem volt, ma is csak Balatoncsicsó felé van, a völgyben található zsákfalu, Balatonhenye felé nincs közúti összeköttetés.'),
    ('Monyoród', 'Mindössze négy települési szomszédja van: kelet felől Versend, dél felől Bóly, nyugat felől Szederkény, északnyugat felől pedig Máriakéménd. A községről az első fellelt írásos emlék egy Anjou-korabeli, 1389-ből származó oklevél. Ez Monorod néven említi.'),
    ('Mosdós', 'Kaposvártól 17 kilométerre keletre, a Külső-Somogyi-dombság lejtőin fekszik. Határát rétekkel, erdőkkel, szőlőkkel tarkított táj öleli és nyugat-keleti irányban átszeli a Kapos folyó. Hozzá tartozik Gázlópuszta, Sárkánypuszta és Jajvölgytelep is. Bár nincs túl közel a Balaton déli partjához, a település szőlő- és borgazdasági szempontból mégis a Balatonboglári borvidék részét képezi.'),
    ('Mosonmagyaróvár', 'Légvonalban Győrtől 35 kilométer-re, Soprontól 56 kilométer-re, Pozsonytól 33 kilométer-re, Rajkától 15 kilométer-re, Bécstől 76 kilométer-re, Budapesttől pedig 140 kilométer-re helyezkedik el, közel az osztrák és a szlovák határhoz. Lakossága körülbelül 34.300 fő, ezzel pedig a megye harmadik és Magyarország 27. legnépesebb települése. A két várost 1939-ben egyesítették, és mára a dualizmus szinte minden jele eltűnt, mivel a két város közötti tér fizikailag és kulturálisan is fejletté vált.'),
    ('Mosonszentmiklós', 'A község a Győr, Mosonmagyaróvár és Csorna közötti háromszögben fekszik, mindhárom várostól nagyjából 20–20 kilométerre. Két, úgynevezett „kinti” községrész tartozik még a településhez: a központtól északra fekvő Gyártelep és a még annál is északabbra, már a vasúton túl található Mosonújhely. A sztrádának csomópontja nincs Mosonszentmiklós területén, de a legközelebbi, lébényi csomópont alig fél kilométerre létesült a község északnyugati határszélétől.'),
    ('Mosonszolnok', 'A település a Mosoni-síkságon helyezkedik el. Felszíne teljesen sík, tengerszint feletti magassága átlagosan 1-2 méterrel magasabb, mint a Szigetköz talajszintje. Az M1-es autópályától 4 kilométerre délnyugatra (a legközelebbi sztrádacsomóponttól 8 kilométerre nyugatra), a 86-os főúttól (illetve az E65-ös európai út itteni szakaszától) 4 kilométerre északnyugatra fekszik.'),
    ('Mosonudvar', 'Mosonmagyaróvártól 2,5 kilométerre délnyugatra fekszik. Újudvar a rendszerváltás előtt a Lajta-Hansági Állami Gazdaság majorja volt. A területet a gazdaság gondozta, az épített játszóteret és tartotta karban az utakat. 2009. április 5-én érvényes és eredményes helyi népszavazást tartottak, amin az újudvariak az elszakadás mellett döntöttek.'),
    ('Mozsgó', 'Szigetvár észak-északkeleti szomszédságában helyezkedik el, a város központjától nagyjából 9 kilométerre. A további szomszédos települések: észak felől Almamellék, kelet felől Almáskeresztúr, délkelet felől Botykapeterd, délnyugat felől Csertő, nyugat felől Szulimán, északnyugat felől pedig Szentlászló.'),
    ('Mucsfa', 'Mucsfa a Tolnai-dombság közepén, Bonyhádtól körülbelül 13 kilométerre, Aparhant és Kisvejke között egy festői völgyben terül el. A falut befogadó völgyben csörgedezik az Apari-patak. A terület talaja jellemzően löszös, barna erdőtalaj. Mucsfa története visszanyúlik a római időkig helyezkedik el. Régészeti kutatások igazolták, hogy a rómaiaknak is volt itt telepük, a régészek egy gyermeksírban játékokra leltek.'),
    ('Mucsi', 'Közigazgatási területének délnyugati, lakatlan részein áthalad a Bonyhád-Kurd közti 6538-as út is. A település első írásos említése Mulsche alakban 1403-ból ismert. A török hódoltság során elnéptelenedett, és csak az 1720-as években érkeztek új, Fulda környékéről származó német telepesek. Aponyi Uraság, lakosai katolikusok, fekszik Tolnához nem meszsze, és annak filiája, határja a’ természetnek szép javaival bővelkedik.'),
    ('Muhi', 'A középkori Mohi területe, ahol a híres csata történt, nem azonos a mai Muhival. Központján észak-déli irányban a 3606-os út vezet keresztül, a nyugati szomszédjával, Hejőkeresztúrral a 3308-as út köti össze. A terület az őskortól lakott. A 13. században két település állt itt a jelentős hadi és kereskedelmi út mellett: Mohi mezőváros és Poga falu. 1241-ben Mohi közelében zajlott a Sajó-menti csata, amelyben a tatárok legyőzték…'),
    ('Murakeresztúr', 'A településen polgárőrség működik. Első említése 1347-ből való Keresztur néven, amely a településen alapított bencés monostorra utalt. A 14. századi település ínséges körülmények között élt, és sűrűn pusztították. A 16. századi apátságnak négy portája volt, amely birtoklásán a Széchyek és az apátság többször vitatkozott. Maga a falu az ínséges körülmények miatt nem sok jelentőséggel bírt, adót se fizettek.'),
    ('Murarátka', 'Letenye nyugati szomszédságában fekszik a Mura folyó partján, Magyarország és Horvátország határa mentén, nem messze a két ország és Szlovénia hármas határától. Területén áthalad az M70-es autóút is, lakott területén a 7538-as út halad végig. A községet ma is sűrű erdők veszik körül a jellegzetes dombos zalai lankákon helyezkedik el. A település nevét először 1353-ban említik források Ratk, Rathk alakokban. 1403-ban az elnevezés a falu két részére utal: Alsowrathk és Felsewrathk.'),
    ('Murga', 'A Dunántúli-dombságban, a Tolnai-Hegyháton fekszik. A megyeszékhely, Szekszárd körülbelül 20 kilométerre található. A szomszédos települések: Hőgyész, Kalaznó, Kéty, Tevel és Kisdorog. A közúti tömegközlekedést a Volánbusz biztosítja. Első írásos említése 1446-ból származik, Morga néven helyezkedik el. Ekkor a Morgai család birtoka volt. A középkori település a török hódoltság ideje alatt elpusztult és lakatlanná vált.'),
    ('Murony', 'Szomszédai: észak felől Mezőberény (7 kilométerre), kelet felől Békés (7 kilométerre), dél felől Békéscsaba (11 kilométerre, ezen belül Mezőmegyer 6 kilométerre), nyugat felől pedig Kamut (5 kilométerre). Neve ószláv eredetű lehet, valószínűleg hangyabolyt jelent. Eredetileg Monor és Muruly néven hívták, de később a végső »ly« → »ny«-re…'),
    ('Mád', 'A közvetlen szomszédos települések: észak felől Erdőbénye, északkelet felől Bodrogkisfalud, kelet felől Bodrogkeresztúr, dél felől Mezőzombor, délnyugat felől Szerencs, északnyugat felől pedig Rátka és Tállya. A térség fontosabb települései közül Mezőzombor és Rátka 5-5, Tállya 7 kilométerre fekszik. A legközelebbi város a 10 kilométerre lévő Szerencs.'),
    ('Mágocs', 'A mecseki Hegyhát tájegység legjelentősebb települése. Ez utóbbi településsel közös vasútállomása van a Dombóvár–Bátaszék-vasútvonalon. Az állomás Mágocstól körülbelül 5 kilométerre délre található. A település északi részén fekvő tórendszer, valamint Dombóvár Újdombóvár városrésze irányában a 65 195-ös út indul a városból, a 6539-esből kiágazva. A Baranyai-Hegyhátnak ez a része földrajzi értelemben a Völgységhez tartozik.'),
    ('Mályi', 'A megyeszékhely Miskolc déli szomszédságában helyezkedik el, a város központjától mintegy 11 kilométerre. Miskolccal ténylegesen csak északnyugati külterületeinél határos. A további szomszédos települések: észak-északkelet felől Kistokaj, kelet felől Sajólád, dél és délnyugat felől pedig Nyékládháza. Északi széle mellett elhalad a 3603-as út, nyugati határszélét pedig érinti még a 2515-ös út is.'),
    ('Mályinka', 'Miskolctól közúton 41 kilométerre nyugatra fekszik. A környező települések: Bánhorváti (11 kilométer), Dédestapolcsány (4 kilométer), Nagyvisnyó (7 kilométer), Nekézseny (11 kilométer), Tardona (7 kilométer). A legközelebbi városok: Kazincbarcika (kb. 16 kilométer), Bélapátfalva (kb. 21 kilométer) és Ózd (29 kilométer). Csak közúton érhető el, Lillafüred vagy Dédestapolcsány felől, mindkét irányból a 2513-as úton.'),
    ('Mánd', 'Szomszédai: észak felől Kömörő, északkelet felől Fülesd, délkelet felől Nemesborzova, dél felől Nagyszekeres, nyugat felől pedig Penyige. Kelet felől Kisszekereshez tartozó külterületekkel határos, de maga a település távolabb esik tőle, dél-délkeleti irányban. A legközelebbi szomszédja Nemesborzova, mely légvonalban kevesebb, mint 2, közúton körülbelül 3 kilométerre fekszik.'),
    ('Mándok', 'A megye, és egyben a Nyírség északkeleti részén fekszik, a Tisza bal parti oldalán. A szomszédos települések: északkelet felől Eperjeske, kelet felől Tiszamogyorós, délkelet felől Benk és Mezőladány, dél felől Tornyospálca, délnyugat felől Fényeslitke és Komoró, nyugat felől Tuzsér, északnyugat felől pedig Tiszabezdéd. A térség fontosabb települései közül Záhonytól 14,5, Tuzsértól 6, Fényeslitkétől 16, Kisvárdától pedig 21 kilométer távolságra található.'),
    ('Mánfa', 'Mánfa a Mecsek – Hegyhát üdülőkörzetben helyezkedik el. A mai település Mánfa és Budafa (Pécsbudafa) egyesüléséből jött létre. Nevét az oklevelek Manfa és Márnfa alakban írták. A település birtokosai a Bátmonostori-, Kisvárdai családok voltak, majd a pécsi püspökség birtoka lett. A török időkben is lakott hely volt, azonban lakossága megfogyatkozott.'),
    ('Mány', 'A környező községek és városok közül Zsámbék 3 kilométer, Bicske 2,5 kilométer, Csabdi 5 kilométer, Herceghalom 8 kilométer, Biatorbágy 18 kilométer távolságra található. Az 1104-esről letérő, arról leválasztott útszakasz keleti fele, az 5+200-as kilométerszelvénynél lévő elágazástól a Deák Ferenc utcai kereszteződésig öt számjegyű országos közútként számozódik, 11 041-es számú mellékútként, a folytatása a központban önkormányzati út.'),
    ('Márfa', 'A Villányi-hegység déli lejtőjén helyezkedik el, Harkánytól északnyugatra. A szomszédos települések: észak felől Szava, kelet felől a ma már Harkányhoz tartozó Terehegy, dél felől Kovácshida, délnyugat felől Drávaszerdahely, északnyugat felől pedig Diósviszló. Nevét az oklevelek 1332-ben említették először, Markfalwaként. A 15. században Márkfalva néven említették az oklevelekben helyezkedik el.'),
    ('Máriahalom', 'Dorogtól 12, Esztergomtól 20, Budapesttől 38 kilométerre helyezkedik el. A faluról először 1255-ben tettek említést Terra Keroa (Keroa földje) néven. 1271-től egységesen a Kerwa név fordul elő írásos formában, 1471-től a Kyrwa, a török korban Kirbaként…'),
    ('Máriakéménd', 'Pécsváradtól délre helyezkedik el. A szomszédos települések: észak felől Kátoly és Szellő, kelet felől Liptód, délkelet felől Versend és Monyoród, dél felől Szederkény, délnyugat felől Olasz, nyugat felől Hásságy, északnyugat felől pedig Berkesd (települési szomszédai közül csak Kátollyal, Szellővel és Szederkénnyel van közvetlen közúti összeköttetése).'),
    ('Márianosztra', 'A Börzsöny délnyugati részén fekszik. A szomszédos települések: észak felől Nagybörzsöny, kelet felől Kóspallag, dél felől Szob, délnyugat felől Ipolydamásd, nyugat felől pedig Letkés. Egy exklávé jellegű külterületi településrésze található még a faluközponttól pár kilométerre délkeletre is (itt találhatók Bibervár romjai, a Toronyalja-horgásztó, illetve egy pálos kolostor emlékhelye és mellette, a Pálos-réten egy kedvelt amatőrcsillagász-észlelőhely is), ennek révén határos dél felől még Szokolyával, Kismarossal és Nagymarossal is.'),
    ('Máriapócs', 'Népessége alapján a megye és az Észak-Alföld legkisebb városa. Az egyházi közigazgatás tekintetében a Nyíregyházi Egyházmegye területéhez tartozik. A Pócs a Paulus (Pál) név magyar származéka. A név Mária előtagja a 18. században került hozzá, a községben lévő Mária-kegyhelyre utalásként. Pócs nevét az oklevelek 1280-ban említik először, birtokosai ez idő tájt a Hontpázmány nemzetség tagjai lehettek, akik a település…'),
    ('Márkháza', 'Salgótarjántól délnyugatra, Bátonyterenyétől nyugatra fekvő település a Keleti-Cserháthoz tartozó Kakukk-hegy lábánál. A Novohrad-Nógrád UNESCO Globális Geopark települése. Ez az út áthalad Márkháza közigazgatási területén, de a belterületét illetően a község zsákfalunak tekinthető, mivel csak egy útvonalon, a Nagybárkány területén kelet felé kiágazó, 21 137-es jelzésű mellékúton érhető el.'),
    ('Márkó', 'Veszprémtől 9 kilométerre nyugatra, Herendtől 5 kilométerre keletre fekszik. Mindkét irányából a 8-as főútról leágazó 8313-as úton közelíthető meg. A legközelebbi település, Bánd 3 kilométerre nyugatra fekszik. Régészeti leletek és középkori oklevelek tanúsága szerint a mai település helyén egykor több település, többek között Szent Márk falva állhatott.'),
    ('Márok', 'Villány keleti szomszédságában helyezkedik el. A további szomszédos települések: északkelet felől Töttös, kelet felől Lippó, délkelet felől Kislippó, délnyugat felől pedig Magyarbóly. Két különálló településrésze Hercegszentmárton és az attól délkeletre fekvő Németmárok. Márok megállóhely Hercegszentmárton településrész északi szélén helyezkedik el, közvetlenül az 57 105-ös út mellett.'),
    ('Márokföld', 'A kisközség a magyar–szlovén határ közelében, Lentitől 17 kilométerre északnyugati irányban található. Csesztregtől a 86-os főútra van összeköttetése a határ mentén húzódó, 7423-as úton. A Nemesnép-Kebeleszentmárton (Kobilje) határátkelőhelytől 3 kilométerre helyezkedik el. Nevét 1345-ben említik először, possessio Markfeulde névalakban helyezkedik el.'),
    ('Márokpapi', 'Márokpapi a Beregi-síkságon fekszik, a megyeszékhely Nyíregyházától mintegy 70 kilométerre északkeletre. Éghajlata a mérsékelten meleg és mérsékelten hűvös határán van. Az évi napsütéses órák száma 1950, a középhőmérséklet 9,4-9,5 °C, a csapadék 630–660 mm. Uralkodó szélirány az északi és a délkeleti. Erdőtársulásait jelentős mértékben tölgyesek alkotják.'),
    ('Mártély', 'A Tisza bal partján fekszik, Hódmezővásárhelytől 10 kilométerre északnyugatra. További szomszédai: észak felől Mindszent, keletről Hódmezővásárhely Barattyos nevű, külterületi városrésze, nyugatról pedig Dóc (utóbbi már a folyó túlpartján). Mártély (Szentadorjánmártély, Saint Adrianus) Árpád-kori település, melyet még I. István király adományozott a zalavári apátságnak halászatával együtt.'),
    ('Mátraballa', 'Szomszédos települései északnyugat és észak felől Nádújfalu, északkelet felől Ivád, kelet felől Pétervására és Kisfüzes, délkelet felől Mátraderecske, dél felől Bodony, nyugat felől pedig Mátramindszent. A falu határában csak alacsonyabb magaslatok találhatók, a környék legmagasabb pontja a 305 méteres Bolya-bérc. Területe a Tarna vízgyűjtőjéhez tartozik, a falun keresztülfolyó patak a kis folyó felső szakaszának egyik mellékága.'),
    ('Mátraderecske', 'Pétervására déli szomszédjában, Mátraballa és Recsk között, a Mátra északi lábánál található kiránduló- és gyógyfürdőhely. A falu nevét már az 1332–1337. évi pápai tizedjegyzék is említette De Reske néven, tehát ekkor már egyháza is volt. Később, 1479-ben pedig Derechke néven említették. A 19. század elején a Grassalkovich, Orczy, Bay, Balogh, Kubinyi, Ondrekovics, Recsky, Ivády, Liszkay, Gomba és Kecskeméti és Ullmann családok birtoka volt, a 20.…'),
    ('Mátramindszent', 'Budapest felől a település közúton legegyszerűbben az M3-as autópályán, majd a 21-es és a 23-as főutakon érhető el: a sztrádáról Hatvannál kell letérni, a 21-esről pedig Kisterenyénél kell keletre fordulni. A két vonal itteni közös állomásán 2007 óta nincs személyforgalom. A környéken réz- és bronzkori leletek kerültek elő, bizonyítva, hogy igen régen megtelepedett az ember a kedvező adottságú területen.'),
    ('Mátranovák', 'Zsáktelepülés, közúton csak Mátraterenyén át közelíthető meg, a 2303-as útból kiágazó 23 109-es számú mellékúton helyezkedik el. Jelenleg a legközelebbi működő állomás Kisterenyén van, mióta a Kisterenye–Kál-Kápolna-vasútvonalon is megszűnt a személyforgalom. Mátraterenye 1984-ben jött létre Homokterenye, Mátranovák és Nádújfalu egyesülésével.'),
    ('Mátraszele', 'Salgótarjántól délkeletre, a Zagyva mentén, Homokterenye és Bárna közt fekszik. A Novohrad-Nógrád UNESCO Globális Geopark települése. Csak közúton érhető el, Kazár felől a 2301-es, Salgótarján, illetve Mátraterenye felől pedig a 2303-as úton. Külterületeit északon érinti még a Bárnára vezető 23 106-os út is. Mátraszele nevét 1304-1321 között említette először oklevél a Rátót nemzetség birtokaként, ekkor Fel-Szele és Al-Szele nevek alatt említették az oklevelek. 1449-ben Kürt és Zobor helységekkel együtt.'),
    ('Mátraszentimre', 'Tulajdonképpen hat, a Magas-Mátra hegyeiben szétszórtan elhelyezkedő lakott helyekből áll, ezek Mátraszentimre, Mátraszentistván, Mátraszentlászló, Bagolyirtás, Fallóskút és Galyatető. Mátraszentimre a Magas-Mátra hegyvidékén helyezkedik el. Magyarország legmagasabban fekvő települése, (750-835 méter. A legmagasabban fekvő településrésze pedig Galyatető).'),
    ('Mátraszőlős', 'Mátraszőlős a Cserhát délkeleti lábánál fekszik, a Hévíz-patak partján (így nevében a Mátra- előtag megtévesztő). Átlagos tengerszint feletti magassága 200 méter. A Novohrad-Nógrád UNESCO Globális Geopark települése. A legközelebbi város Pásztó 5 kilométerre helyezkedik el. Salgótarján körülbelül 26 kilométerre, Budapest pedig mintegy 90 kilométerre van a településtől.'),
    ('Mátraverebély', 'A Zagyva völgyében helyezkedik el, a Mátra és a Cserhát között. Négy települési szomszédja van: északkeleti, keleti és délkeleti irányból Bátonyterenye, dél felől Tar, nyugat felől Sámsonháza, északnyugat felől pedig Márkháza. A Novohrad-Nógrád UNESCO Globális Geopark települése.'),
    ('Mátyus', 'A Beregi-síkon, az ukrán határ mellett fekszik, a Tisza jobb partján. A Beregi-Tiszahát hajdan egyutcás falucskája az idők során Lónya felé terjeszkedett. A Tisza partjához közeli, 1098 hektáros kisközség 139 lakásában manapság mintegy 400-an élnek, ők többnyire mezőgazdasággal foglalkoznak. A soros elrendezésű szalagtelkeken emelt újabb lakóházak jobbára jellegtelenek.'),
    ('Mátyásdomb', 'Természetföldrajzilag a terület a Mezőföldhöz tartozik. A község eredetileg Feketepuszta néven alakult 1952. január 1-jén, de a tanácstestület még abban a hónapban úgy határozott, hogy a településnév Mátyásfalva legyen. Ezt 1952. február 13-án a megyei tanács is jóváhagyta, végleges nevét azonban a Belügyminisztérium ugyanazon év júliusában Mátyásdomb formában rögzítette.'),
    ('Mátészalka', 'A megyeszékhely Nyíregyházától 52 kilométerre keletre, Debrecentől 77 kilométerre északkeletre található. A szomszédos települések: észak felől Ópályi, északkelet felől Szamosszeg és Tunyogmatolcs, kelet felől Kocsord, dél felől Nyírcsaholy, délnyugat felől Nyírmeggyes, nyugat felől Jármi, északnyugat felől pedig Papos.'),
    ('Mátételke', 'Mátételke Bács-Kiskun megye déli részén, a Bácskában található nagy múltú település, amely a történelem folyamán többször újratelepült. A falu Bácsalmástól északnyugatra 9, Bajától 28, az 55-ös főúttól 2,5 kilométerre fekszik. Korábbi neve Matheovics volt, 1904-től nevezik hivatalosan Mátételkének. Első okleveles említése 1651-ben kelt, e szerint Bornemisza polgár Pál végrendeleteiben leányaira hagyományozta Matheovics pusztát. 1662-ben I.'),
    ('Máza', 'Erdők és gondozott mezőgazdasági területek fogják közre. Természeti adottságai igen jó lehetőséget biztosítanak erdei kirándulásokra, vadászatra, pihenésre helyezkedik el. A települést említő első írásos adatok 1235-ből valók. A későbbi századokban itt élő magyar és német népcsoportok kizárólag földműveléssel foglalkoztak, egészen az 1829-es bányanyitásig, melyet követően kialakult egy földművelő-iparos réteg is.'),
    ('Méhkerék', 'Magyarország legnagyobb román lakossággal rendelkező települése. Szomszédai: északkelet felől Újszalonta, délkelet felől Kötegyán, délnyugat felől Sarkad, északnyugat felől pedig Sarkadkeresztúr. Kelet felől Romániához (jobbára Nagyszalontához) tartozó területek határolják, északi irányból pedig aránylag közel fekszenek az ottani határszéléhez Mezőgyán legdélebbi határrészei, de a két település közigazgatási területei nem érintkeznek egymással.'),
    ('Méhtelek', 'Szomszédai a határ magyar oldalán: észak felől Nagyhódos, kelet felől Garbolc, délnyugat felől Zajta, nyugat felől pedig Rozsály. Délkeleti és déli irányból a romániai Szárazberekhez (Bercu) és Kispeleskéhez (Pelișor) tartozó területek határolják. A környék fontosabb települései közül Kölcse 20, Csaholc 14, Túrricse 10, Tisztaberek 7 kilométer távolságra található.'),
    ('Mélykút', 'A Bácskai-síkvidéken helyezkedik el, Jánoshalmától 10, Bácsalmástól 13, Kiskunhalastól 33, Bajától 36, Szabadkától 39 kilométerre. A közvetlenül határos települések: északkelet felől Kisszállás, kelet felől Tompa, délkelet felől Csikéria, dél felől Bácsszőlős, délnyugat felől Bácsalmás, nyugat felől Tataháza, északnyugat felől pedig Jánoshalma. Határában folyik a Kígyós-főcsatorna.'),
    ('Méra', 'A Hernád völgyében fekszik, a folyó jobb parti oldalán, a megyeszékhely Miskolctól közúton 45 kilométerre északkeletre. Közvetlen szomszédai észak felől Novajidrány (kb. 6 kilométer), dél felől Encs (4 kilométer), északnyugat felől pedig Szalaszend (kb. 5 kilométer). Az előzőeken túl határos még, a folyó túlpartján fekvő települések közül északkelet felől Vizsollyal, kelet felől Hernádcécével, délkelet felől pedig Abaújkérrel, de ezek egyikével sincs közvetlen közúti kapcsolata.'),
    ('Mérges', 'A Rába völgyében, eredetileg annak jobb partján jött létre, egy patkó alakú kanyarulatban. A folyónak a 20. század legelső éveiben elvégzett szabályozásával – ami az itteni kanyarulat kiegyenesítését is jelentette – belterülete átkerült a bal parti oldalra, miközben kiterjedt külterületei továbbra is a jobb parti oldalon fekszenek. A folyón emiatt kis híd is létesült, de annak fennmaradása az eltelt idők során többször is veszélybe került.'),
    ('Mérk', 'A környező települések közül Vállaj 1,5, Tiborszállás 5, Fábiánháza 7,5, Nagyecsed pedig 10,5 kilométer távolságra található. A közvetlenül szomszédos települések, településrészek a határ magyar oldalán: észak felől Tiborszállás, kelet felől Ágerdőmajor, dél felől Vállaj, nyugat felől Terem, északnyugat felől pedig Fábiánháza. Határszéle északkeleten, egy rövid, körülbelül egy kilométeres szakaszon egybeesik a magyar-román államhatárral.'),
    ('Mónosbél', 'A Bükk-vidéken, a Mónos-patak két oldalán helyezkedik el. Bélapátfalvától 3 kilométerre délre, Egertől 19 kilométer távolságra észak-északkeletre helyezkedik el. Keleti határában a Bükk hegyei emelkednek: az 570 méter magas Kis-szoros tető, az 548 méter magas Hársas-tető és az 543 méter magas János-hegy. A közvetlenül határos települések: észak és kelet felől Bélapátfalva, dél felől Szarvaskő, nyugat felől Egerbocs, északnyugat felől pedig Mikófalva.'),
    ('Mór', 'Egy ősi bortermelő térség, a Móri borvidék központja. A megyeszékhelytől, Székesfehérvártól mintegy 26 kilométerre északnyugatra fekszik, átlagos tengerszint feletti magassága 200 méter környékére tehető. A közel tizenegyezer hektáros kiterjedésű, változatos tájegyüttes főleg dombsági, illetve hegységi felszínekből tevődik össze. Fejlődésének története a Vértes kialakulásához kapcsolódik.'),
    ('Mórahalom', 'A Dorozsma–Majsai-homokháton, Szegedtől mintegy 20 kilométerre nyugatra helyezkedik el, közvetlenül a déli (szerbiai) országhatár mellett. A szomszédos települések: észak felől Zákányszék, kelet felől Domaszék, délkelet felől Röszke, nyugat felől Ásotthalom, északnyugat felől pedig Ruzsa. Dél felől a vajdasági Horgoshoz tartozó külterületek határolják.'),
    ('Móricgát', 'Mindössze három települési szomszédja van: észak felől Bugac, kelet felől Jászszentlászló, dél felől pedig Szank. Nyugat felől Bugachoz tartozó, jobbára lakatlan külterületek határolják. Móricgát, előző nevén Móritz Gattya területe a régészeti források szerint mát a bronzkorban is lakott hely volt, de területén szarmata korból való leletek is napvilágra kerültek.'),
    ('Mórichida', 'A Kisalföldön fekszik, a Marcal és a Rába völgyében, Győrtől 32 kilométer-re délre. A Rábától egy kilométerre, közvetlenül a Marcal folyó jobb partján épült. Tájföldrajzilag a Kisalföld nagytájához, azon belül a Marcal-medencéhez tartozik. Talaja legnagyobbrészt laza meszes homok, homokos öntésiszap, ill. a két folyó közti részeken kötöttebb, agyagos öntéstalajok.'),
    ('Mórágy', 'A Geresdi-dombságban, Bátaszéktől 6 kilométer-re északnyugatra található. Központját azonban az 5603-as út elkerüli, oda csak az 56 104-es számú mellékútra letérve lehet eljutni. Az 1990. évi népszámlálás szerint 848 lelket számláló helység csaknem hatezer éves történelmi múltra tekint vissza. A Velencei-hegységen kívül Magyarországon egyedül itt bukkan felszínre a Kárpát-medence különböző mélységeiben húzódó Variszkuszi-hegységrendszer egy gránit tömbje.'),
    ('Múcsony', 'A Szuha és a Sajó völgyében fekszik, Miskolctól közúton 23 kilométerre északra. A közvetlenül határos települések: észak felől Rudolftelep, északkelet felől Edelény, délkelet felől Sajószentpéter, dél felől Berente, délnyugat felől Kazincbarcika, nyugat felől Szuhakálló, északnyugat felől pedig Izsófalva. Szuhakállóval gyakorlatilag összenőtt, de Rudolftelep, valamint a térség két városa, Kazincbarcika és Edelény is 4-5 kilométeres távolságon belül található.'),
    ('Mőcsény', 'Hozzá tartozik 1934 óta Palatinca, 1959 óta pedig Zsibrik. A megye déli részén helyezkedik el, Bonyhád és Bátaszék között, előbbihez valamivel közelebb. Három településrésze egyértelműen elkülönül egymástól, közúton mindegyiket legalább két kilométernyi távolság választja el a másik kettőtől. Mőcsény központja északnyugaton, Zsibrik délnyugaton, Palatinca pedig keleten helyezkedik el a többi településrészhez képest.'),
    ('Nadap', 'Nadap a Velencei-hegység délkeleti részén terül el. A Velencei-tótól 2 kilométerre északra található. Autóbusszal elérhető Székesfehérvár, Velence és Kápolnásnyék felől. A község a táj legmagasabban fekvő helysége a maga 202 méterével, ami 100 méterrel magasabb a tó víztükrénél helyezkedik el. Nadap valószínűleg fontos település volt a honfoglalás időszakában.'),
    ('Nagyacsád', 'Pápa északnyugati szomszédságában helyezkedik el, a város központjától mintegy 8 kilométerre. Mindössze két másik közvetlen települési szomszédja van: észak felől Nemesgörzsöny, dél és nyugat felől pedig Mezőlak. Központján annak főutcájaként a 8406-os út halad végig, azon érhető el Pápa és Celldömölk térsége felől is. Működése fénykorában Kisacsád felől kisvasút is kapcsolódott az állomáshoz.'),
    ('Nagyalásony', 'Pápától délnyugatra, Vid, Dabrony és Dáka közt fekvő település. Ajka felől a 8401-es, Pápa irányából a 8403-as úton érhető el, a két útvonal a község központjában keresztezi egymást. Neve szláv személynévből alakult ki: a Vlasin-ból Oláson, majd Alásony lett. Nagyalásony korai történetéről kevés adtunk van. A középkori falu első említése Olosun alakban 1240-ből ismert.'),
    ('Nagyar', 'Szomszédai: észak felől Tarpa, kelet felől Szatmárcseke, délkelet felől Kömörő, dél felől Penyige és Fehérgyarmat, nyugat felől Kisar, északnyugat felől pedig Tivadar. A környék fontosabb települései közül Fehérgyarmat 10, Szatmárcseke 8, Tarpa 10, Tivadar pedig 5 kilométer távolságra található. A település központján végighúzódik, nyugat-keleti irányban a 4130-as út, ezen érhető el Kisar és Szatmárcseke felől is.'),
    ('Nagyatád', 'A „parkok, szobrok és a fürdők városa”. A Belső-Somogy déli részén, a Balatontól mintegy 60 kilométerre, a Barcstól Balatonkeresztúrig húzódó 68-as főútvonal mentén, a Rinya-patak partján található. Ma már (2019-es állapot szerint) teljesen kikerüli a város lakott területeit: az elkerülő szakasz átadása óta az annak délkeleti kezdőpontjától a belvárosba (majd onnan tovább Berzence és a horvátországi Kapronca irányába) vezető útvonal a 681-es, a centrumból az elkerülő szakasz északi végpontjáig vezető út pedig a 6821-es számozást viseli.'),
    ('Nagybajcs', 'A Kisalföld szigetközi részén, Győrtől 12 kilométerre észak-északkeletre, a Duna partján helyezkedik el. A település területén torkollik bele az előbbi útba, Vámosszabadi Győrszabadi településrésze felől az 1303-as út. A Nagy-Duna partján fekvő község magja a kora középkorban egy kis halásztelep volt. Első említése Boych írásmóddal 1252-ből származik.'),
    ('Nagybajom', 'A közvetlenül határos települések: észak felől Libickozma, északkelet felől Somogyfajsz és Újvárfalva, kelet felől Somogysárd és Pálmajor, délkelet felől Kiskorpád, dél felől Jákó, délnyugat felől Kutas, nyugat felől Böhönye, északnyugat felől pedig Mesztegnyő.'),
    ('Nagybakónak', 'A község Nagykanizsától északkeletre fekszik. Van egy erdőterület a határában, amelynél 7 község határa találkozik: Nagybakónak, Újudvar, Gelsesziget, Gelse, Orosztony, Kerecseny, Zalaújlak. Ezért ezt a területet "Héthatárnak" nevezik. Északról Gelse, Orosztony, keletről Zalaújlak, Csapi, délről Nagykanizsa, Nagyrécse, nyugatról pedig Újudvar és Gelsesziget határolja.'),
    ('Nagybaracska', 'Nagybaracska a Duna-Tisza közének délnyugati csücskében fekszik a Bácska területén. Nyugati része közvetlenül a Ferenc-csatorna keleti partján található, amely elválasztja a Mohácsi-szigettől. Vízrajzi viszonyait meghatározó módon befolyásolja a Duna közelsége. A talajvízszint meglehetősen magas, állandó összefüggésben van a folyam vízszintjének változásával.'),
    ('Nagybarca', 'A Bán-patak völgyében fekszik, a megyeszékhely Miskolctól közúton 30 kilométerre északnyugatra. A környező települések: észak felől Vadna (kb. 6 kilométer-re), északkelet felől Sajóivánka, kelet felől Kazincbarcika (kb. 10 kilométer-re), dél-délnyugat felől Bánhorváti (5 kilométer-re), északnyugat felől pedig Sajóvelezd. A legközelebbi város Kazincbarcika.'),
    ('Nagyberki', 'A Kapos folyó jobb partján található Kisberki településrész, ettől délkeletre pedig Vadaskert. Bár nincs túl közel a Balaton déli partjához, a település szőlőtermő területei mégis a Balatonboglári borvidék részét képezik. Nagyberki már ősidők óta lakott hely. A község határában talált leletek, sáncok, földvárak illetve feltárt, úgynevezett „halom” temetkezési helyek arra utalnak, hogy itt kelták laktak az idősszámítás előtti évezred közepén és messze földön híres telepet építettek ki.'),
    ('Nagyberény', 'Siófoktól körülbelül 17 kilométerre délkeletre található. Vasútja ritkán, lassan közlekedik, fennmaradása is kétséges. Sommal közös megállóhelye (Som-Nagyberény megállóhely) elhanyagolt, fa talpfái felújításra szorulnának. A település neve az ismert írott források közül először a Szent László által a veszprémi püspöknek kiállított megerősítő levelében fordul elő.'),
    ('Nagybudmér', 'Villánytól északra fekszik, Borjád nyugati és Kisbudmér északi szomszédságában. A további szomszéd települések: észak felől Belvárdgyula, délnyugat felől Ivánbattyán, nyugat felől pedig Kiskassa. A szomszédai közül, Borjádon felül csak Kisbudmérral van közúti kapcsolata. A település népességének változása: A 2011-es népszámlálás során a lakosok 91,2%-a magyarnak, 4,1% cigánynak, 19,7% németnek, 0,5% románnak, 0,5% szlováknak mondta magát (7,8% nem nyilatkozott.'),
    ('Nagybánhegyes', 'Orosházától délkeletre fekszik, Mezőkovácsháza északi szomszédságában. További szomszédai: észak felől Medgyesbodzás, kelet felől Magyarbánhegyes, nyugat felől Kaszaper, északnyugat felől pedig Csanádapáca. Az írásos adatok azt bizonyítják, hogy Bánhegyesse néven már a 15. században is lakott volt. Nevét Maróti János macsói bántól kapta, a hegyes szó pedig rétet, kaszálót jelent.'),
    ('Nagybörzsöny', 'Lakossága 570 fő (2025. jan. 1.). Nagybörzsöny a Börzsönyi-peremhegység nyugati peremén, a Börzsöny-patak partján található. Közigazgatási területe nyugaton az Ipolyig terjed, ebbe folyik - már Vámosmikolánál - a Börzsöny is, keleten pedig mélyen benyúlik a Börzsöny erdei közé. Területének csaknem háromnegyede a Duna–Ipoly Nemzeti Parkhoz tartozik.'),
    ('Nagycenk', 'A Nyugat-magyarországi peremvidéken az Ikva-síkon helyezkedik el. A határ délnyugati rész dombvidéki jellegű és a Soproni-hegység nyúlványaihoz kapcsolódik. Fontos elérési útvonala az M85-ös autóút is, amely a forgalomba helyezése óta jelentős mértékben tehermentesíti a települést az áthaladó forgalom alól. A Győr–Sopron-vasútvonalon levő egykori megállója (Nagycenk–Hidegség megállóhely) az 1990-es években megszűnt.'),
    ('Nagycsepely', 'Balatonszárszótól 10 kilométerre, Balatonföldvártól 15 kilométerre fekszik. Nevének „…eredetét ugyancsak vitatják. Az egyik feltevés szerint az 1150-ben lejegyzett Sepel személynévből (mely török vagy szláv eredetű), egy másik szerint a magyar népies cseplye ~ csepely »sarjadék erdő, bokros cserjén hely« jelentésű szóból származik.” A nagy előtag megkülönböztető szerepű, és a 20. század elején kapta a község, az országos közigazgatási rendezéskor.'),
    ('Nagycserkesz', 'Nyíregyháza nyugati agglomerációjában helyezkedik el, a megyeszékhelytől és Tiszavasváritól egyaránt nagyjából azonos, mintegy 15 kilométernyi távolságra. Mindkét település felől a 36-os főúton érhető el. Tiszalökkel a 3612-es, Tiszaeszlárral a 3634-es, Nyírtelek Belegrád, Görögszállás és Varjúlapos településrészeivel a 3635-ös, utóbbi település központjával pedig a 3636-os út köti össze.'),
    ('Nagycsány', 'Az Ormánság középső részén fekszik, Siklóstól nyugatra, Sellyétől keletre, Vajszló nyugati szomszédjában. Szentlőrinc városával az 5805-ös út köti össze. A Szentlőrinc felé vezető utat 2012-ben felújították. Nagycsány'' (Csány) nevét 1244-ben említették először az oklevelek. 1257-ben Chan néven írták. 1244-ben Zadur fia Péter birtoka volt és ekkor Vajszló-val, majd 1257-ben a sámodi uradalommal volt határos. 1283-ban Péter fia Demeter Mirajt nevű birtokát eladta. 1300 körül fia Péter mester birtokát lerombolta.'),
    ('Nagycsécs', 'A környező települések közül Muhi 2, Sajószöged 4 kilométerre fekszik, a legközelebbi város a mintegy 7 kilométerre lévő Tiszaújváros. Neve lehetséges, hogy szláv személynévből ered, de az is lehet, hogy a cech régi magyar jelentése(himlőhely) szóból származik. Valószínűsíthetően innen ered a csécsi szalonna elnevezése. A település környéke az őskor óta lakott. 1241 tavaszán a falu határában zajlott le a magyar vereséggel végződő muhi csata.'),
    ('Nagydobos', 'A Nyírség keleti csücskében, a Kraszna folyó bal partján helyezkedik el. Határában szelíd dombok és sík területek váltják egymást. Nyíregyházától 60 kilométerre északkeletre, Vásárosnaménytól 8 kilométerre délre, Mátészalkától 16 kilométerre északra fekszik. A szomszédos települések: észak felől Vásárosnamény, északkelet felől Olcsva, kelet felől Szamosszeg, dél felől Ópályi, délnyugat felől Nyírparasznya, nyugat felől Pusztadobos, északnyugat felől pedig Perényitanya (Vásárosnamény különálló településrésze).'),
    ('Nagydobsza', 'A legközelebbi városok Szigetvár és Barcs, előbbitől 11, utóbbitól 19 kilométerre fekszik. Első írásos említését vizsgálva, egyes kutatók cseh eredetűnek vélik (a cseh dub (tölgy) szóra utalva, mivel 1100 körül csehek telepedtek le az akkoriban tölgyesekkel borított vidékre), míg más vélemények szerint az ütőhangszerre utaló Dobsa személynévből ered.'),
    ('Nagydorog', 'A közvetlenül határos települések: észak felől Bikács, északkelet felől Györköny, délkelet felől Pusztahencse, dél-délkelet felől Tengelic, dél-délnyugat felől Kajdacs, nyugat felől pedig Sárszentlőrinc. A település első írásos említése 1397-ből származik. Zsigmond király ekkor adta a Kanizsai családnak a simontornyai várat és a hozzátartozó birtokokat…'),
    ('Nagydém', 'Az enyhe lankák, az alacsony dombok, és sekély völgyek változatos látványt nyújtanak. Nagydém és környéke ősidők óta lakott helynek számit, az itt talált bronzkori, kora vaskori régészeti leletek alapján. Az első rendelkezésre álló írásos emlékek 1333-ban Nagdeem néven említik. 1554-ben lakatlan, s amit újra 1761-ben népesítenek…'),
    ('Nagyecsed', 'A Délkelet-Nyírség és a Szatmári-síkság határán helyezkedik el, Mátészalkától 14, Győrtelektől 10, Porcsalmától 16, Vállajtól 14 kilométerre. Lakott területét kettészeli a Kraszna folyó. A település neve 1220-ban egy idevaló poroszló nevében fordul elő először (prist. Zomoy de villa Euchetii alakban), azonban már Anonymus is megemlékezett a település határában, az Ecsedi-láp szigetein felépült úgynevezett Sárvárról Gesta Hungarorumában: a honfoglalás idején Tas vezér „vonult a Szamos folyó felé arra a helyre…'),
    ('Nagyesztergár', 'Hangulatos, nyugodt falusias légkörű település, igazi kikapcsolódást biztosít az idelátogatóknak. Főutcája a Zircet Mórral összekötő 8216-os út, amely itt nagyrészt a Radnóti Miklós út, a község keleti részében a Kölcsey Ferenc út nevet viseli. Az Esztergár név feltételezések szerint a faragó, esztergályos jelentésű szláv strugar szóból származik, ami a magyar nyelvben nyerte el mai alakját.'),
    ('Nagyfüged', 'A közvetlenül szomszédos települések: észak felől Ludas, északkelet felől Nagyút, kelet felől Tarnazsadány, dél felől Zaránk, délnyugat felől Visznek, nyugat felől Adács, északnyugat felől pedig Karácsond. Délkelet felől a legközelebbi község Tarnaméra, de közigazgatási területeik (kevés híján) nem határosak. Az első okleveles forrás 1301-1302. évben Fygug névalakban említi…'),
    ('Nagygeresd', 'A környék már a kőkorszakban is lakott volt. A település nevét először 1260-ban említik oklevelek Gueruzd néven helyezkedik el. A Geresd Árpád-kori személynév, vélhetően a György korabeli megfelelője volt. A 16. században Kis- és Nagygeresd néven két különálló település létezett, melyeket 1928-ban egyesítettek. Mindkét jelentős nemesi lakossággal bírt, akik nagy szerepet játszottak…'),
    ('Nagygyimót', 'Nagygyimót az Öreg-Bakony északi lejtőjének végén, Pápa várostól keletre 6 kilométer távolságra fekszik. A közvetlenül határos települések: észak felől Vaszar, északkelet felől Vanyola és Csót, kelet felől Béb, délkelet felől Homokbödöge, dél felől Adásztevel, délnyugat felől Pápa, északnyugat felől pedig Takácsi. Északnyugati határszélét érinti a 8305-ös út is.'),
    ('Nagygörbő', 'A falu első említése 1274-ből való Vindornyaszőlős határtelepüléseként. Földje mindig is rosszul termett, ezért komolyabb település sokáig nem alakult ki. Szétválása Kisgörbőtől a 16. század végén történt meg. A 18. század elejétől Sümegcsehi, 1758-tól pedig Kisgörbő anyaegyháza alá tartozik. A 20. században sok helyi lakos a település határain túl keresett munkát magának, korábban summásként a távoli urasági földeken, a második világháború után a környező városok iparában.'),
    ('Nagyhajmás', 'A község területe I. Szent István uralkodása idején a Szentemágócs nemzetség tulajdona volt. A települést először Hagmas néven Károly Róbert uralkodása alatt keletkezett oklevél említi. Az akkori falu magyar lakossága a török hódoltság ideje alatt teljesen kicserélődött. A 17. század végén lakói rácok voltak- az 1695-ös országos összeírás Ráchajmás néven vették számba, amelynek földesura Karanchich N., török földesura Koczi Zada Achmed. 1720 körül jelent meg újra a faluban a magyar lakosság, hivatalosan ettől az időtől tartozik Baranyához.'),
    ('Nagyhalász', 'A Közép-Nyírség északi részén, a Rétközben helyezkedik el, a megyeszékhely Nyíregyházától 18, Ibránytól 3, a Tiszatelekhez tartozó Kétérköztől 6, Dombrádtól 21, Vasmegyertől pedig 5 kilométerre. A közvetlen szomszédos települések: északkelet felől Tiszatelek, kelet felől Tiszarád, délkelet felől Kemecse, délnyugat felől Kótaj, nyugat felől pedig Ibrány.'),
    ('Nagyharsány', 'A település a Szársomlyó ölében, a Villányi-hegység déli lejtőjén, Siklóstól 8 kilométerre keletre, Villánytól 6 kilométerre nyugat-délnyugatra, Pécstől pedig 35 kilométerre délkeletre található. A szomszédos települések: észak felől Villánykövesd, északkelet felől Villány, délkelet felől Beremend, dél felől Kistapolca, délnyugat felől Siklósnagyfalu, nyugat felől pedig Kisharsány.'),
    ('Nagyhegyes', 'Területe 13 276,41 hektár (belterület: 175,35 hektár, külterület: 13 101,06 hektár) Nagyhegyes a Hortobágy keleti szélén, a Hajdúság délnyugati határán a Keleti-főcsatorna mellett, a Debrecen, Hajdúszoboszló, Balmazújváros városok által meghatározott urbanizációs környezetben épült. Közúton Debrecentől nyugati irányban 24, Hajdúszoboszlótól északi irányban 11, míg Balmazújvárostól déli irányban 9 kilométerre helyezkedik el.'),
    ('Nagyhódos', 'Központjától alig 3 kilométerre keletre található Magyarország, Románia és Ukrajna hármashatára. A szomszéd települések a határ magyar oldalán: délkelet felől Garbolc, dél felől Méhtelek, délnyugat felől Rozsály, nyugat felől pedig Kishódos. Északkelet felől a legközelebbi település az ukrajnai Nagypalád (Велика Паладь). A településen végighalad, nagyjából délkelet-északnyugati irányban a 4143-as út, közúton az ország belseje felől csak ezen érhető el, a két végponti település, Gacsály vagy Tiszabecs irányából.'),
    ('Nagyigmánd', 'A Kisalföld keleti szegletében, az Igmánd–Kisbéri-medencében helyezkedik el. A sztrádáról a 13-as főútra lehajtva jutunk el Nagyigmándra, ezen érhető el északi irányból Komárom, déli irányból pedig Kisbér felől is. Központján az a 8136-os út halad át, amely Tata és Győr térségét köti össze a köztük fekvő kisebb települések feltárásával.'),
    ('Nagyiván', 'A Hortobágy egyetlen igazi pusztai falva, három oldalról is körbeveszi a jórészt védett szikes puszta. Szolnok, a megyeszékhely kb. 80 kilométer-re található. Szomszédos települések: Tiszafüred-Kócsújfalu, Tiszaörs. A pusztán át elérhető még Hortobágy, Nádudvar-Mihályhalma, Püspökladány, Karcag-Tilalmas, Berekfürdő, Kunmadaras, Tiszaigar. A közúti közösségi közlekedés autóbuszos szolgáltatója a Volánbusz.'),
    ('Nagykamarás', 'Közös hivatali székhely, körjegyzőséget alkot Medgyesbodzással és Dombiratossal. Szomszédai: északkelet felől Kétegyháza és Elek, délkelet felől Lőkösháza, dél felől Kevermes és Dombiratos, délnyugat felől Kunágota, nyugat felől Almáskamarás, északnyugat felől pedig Medgyesegyháza. Éghajlata kontinentális, jellemző a hideg tél és a meleg nyár. Az évi napsütéses órák száma igen magas az országos átlaghoz viszonyítva.'),
    ('Nagykanizsa', '14 840 hektáros kiterjedésével a megye legnagyobb közigazgatási területű települése, kiterjedése csaknem másfélszerese a megyeszékhely Zalaegerszeg területének. Zalaegerszeg után a megye második legnépesebb települése. Földrajzilag a Zalai-dombság területén helyezkedik el, délebbi városrészei pedig a Zalaapáti-háthoz tartoznak. Alacsony (100–110 méter) fekvésű vidék, a hajdani mocsárvilág lecsapolására számos csatorna szeli át a környékbeli nedves réteket, legelőket.'),
    ('Nagykapornak', 'A Zalai-dombság középső részén helyezkedik el, az észak–déli irányban húzódó Principális-völgy keleti felén, a megyeszékhely Zalaegerszegtől keletre. A közvetlenül határos települések: észak felől Orbányosfa, észak-északkelet felől Padár, északkelet felől Almásháza, kelet felől Tilajújhegy (Tilaj része), kelet-délkelet felől Tilaj, délkelet felől Szentpéterúr, dél-délkelet felől Nemesrádó, dél felől Misefa, délnyugat felől Nemessándorháza, nyugat felől Kisbucsa, északnyugat felől pedig Nemesapáti.'),
    ('Nagykarácsony', 'Országos ismertséget ad a településnek, hogy a karácsonyi ünnep előtt különleges ünnepi képeslapot lehet küldeni, melyet ez alkalomra szóló postai bélyegző lenyomattal érvényesít a postahivatala. Baracs innen 10, Sárbogárd 14, Cece és Dunaújváros egyaránt 19-19, Dunaföldvár 15, Solt 23 kilométer távolságra található. Vasúton a Mezőfalva–Rétszilas-vasútvonalon érhető el, amelynek két megállási pontja is van a község területén: Nagykarácsony megállóhely és Nagykarácsony felső megállóhely.'),
    ('Nagykereki', 'Különálló településrésze Nagyzomlin, mely a központjától jó 5 kilométerre délre helyezkedik el. A szomszédos települések a határ magyar oldalán: észak felől Kismarja, dél felől Ártánd, délnyugat felől Bedő, nyugat felől pedig Bojt. Kevés híja van annak, hogy nem határos északnyugaton még Hencidával is. Határszéle keleten mintegy 12 kilométer hosszban egybeesik az országhatárral.'),
    ('Nagykeresztúr', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. A falu neve a 20. század elején Kétkeresztúr néven volt ismert. Kiskeresztúr és Nagykeresztúr egyesüléséből alakult ki és ekkor 44 házban 300 magyar és tótajkú lakosa volt. Ekkor Alsó- és Felső-Veselény, Csevicze-, Kiskeresztúr-, Lápos- és Rózsás puszták is hozzá tartoztak. Keresztúr, Nagykeresztúr nevét először 1332-1337 között a pápai tizedjegyzék említette, tehát már akkor egyházas hely volt.'),
    ('Nagykinizs', 'Miskolctól mintegy 31 kilométerre északkeletre fekszik, a Hernád mellett. Lakott területe és közigazgatási területének túlnyomó része a folyó bal parti oldalán terül el, de körülbelül 1 négyzetkilométernyi terület tartozik hozzá a jobb parti oldalról is. A szomszédos települések: észak felől Kiskinizs, északkelet felől Hernádkércs, délkelet felől Monok, dél felől Szentistvánbaksa, nyugat felől pedig Halmaj.'),
    ('Nagykorpád', 'Közigazgatási területének délkeleti sarkánál elhalad a Kaposfő-Lábod közti 6616-os út is. Neve először az 1232-1337. évi pápai tizedjegyzékben fordult elő Corpad alakban helyezkedik el. Az 1554. évi török kincstári adólajstrom szerint 11 ház állt itt. Az 1571. évi adólajstromban Erdőkorpád alakban volt bejegyezve, ekkor…'),
    ('Nagykovácsi', 'Budapest II. és XII. kerületének közelsége rövid idő alatt a budapesti agglomeráció egyik legkedveltebb településévé tette. Zsáktelepülés jellegéből adódóan burkolt közúton csak egy irányból, Budapest felől közelíthető meg. A földrajzilag szomszédosnak tekinthető községek közül nem érintkezik a területe Tinnyéével. A Nagykovácsi-medencétől északra Solymártól és Pilisszentivántól a Zsíros-hegy és a Nagy-Szénás vonulata választja el.'),
    ('Nagykozár', 'A Mecsek déli lábainál, a Baranyai-dombság vidékén fekszik, Pécs délkeleti szomszédságában. A megyeszékhely központjától mintegy 7 kilométer választja el, de Újhegy városrész első házaitól alig 500 méterre helyezkedik el. A további szomszédos települések: észak felől Bogád, északkelet felől Romonya, kelet felől Ellend, délkelet felől Magyarsarlós, dél felől Szemely, délnyugat felől pedig Kozármisleny.'),
    ('Nagykutas', 'A falutól délre húzódó dombsor tetején 18-19. században épült boronafalú, zsúpfedeles szőlőhegyi pincesor faluképi jelentőségű. A falu központjában impozáns látványt nyújt az 1740-es években épült, 2002-ben felújított templom, és az 1992-ben épült faluház, mely számos rendezvénynek adhat otthont. Nagykutas Árpád-kori település. Nevét 1211-ben már említették az oklevelekben Kuthus néven helyezkedik el.'),
    ('Nagykálló', 'A Nagykálló név néhány lehetséges magyarázata: sokáig Nagykállóban volt a környék legnagyobb kallómalma, a kál szó jelentése „nagy”, a kálló régen gyülekezőhelyet jelentett (ezt őrzi például az „elkallódik” szavunk). A város a megye délkeleti részén, Magyarország északkeleti részén található. A román határ 47 kilométerre, az ukrán határ pedig 70 kilométerre található a várostól.'),
    ('Nagykáta', 'Budapest és Szolnok között körülbelül félúton helyezkedik el. Területe 8161 hektár, ebből 646 belterület. Viszonylag kisszámú lakossága ellenére fontos központ a területen – gyakran a Tápió-vidék fővárosa címmel illetik -, hiszen a környező települések lakóit is ellátja adminisztratív, kulturális, egészségügyi és üzleti szempontból is, így a teljes kiszolgált lakosság 50-60 000 főre tehető.'),
    ('Nagykónyi', 'Tölgyesek és mohos bükkösök határolják e jellegzetes dunántúli tájat. A Koppány folyó a község északi részét szeli át. A település közvetlen közelében található a gyulaji erdő, amely a környékbeliek közül sokaknak ad munkát, a látogatóknak pedig gyönyörű látványt nyújt. Jellegzetes növénye a kárpáti sáfrány, amely hazánkban ezen a vidéken kívül csak a soproni erdőségekben található meg.'),
    ('Nagykökényes', 'Nagykökényes első ismert birtokosai a Szolnok nemzetség tagjai voltak, de itteni birtokukat korán elvesztették, azt a Kökényes-Radnót nemzetség kapta meg. A Kökényes-Radnót nemzetség a 12. század közepén birtokos volt, premontrei rendű monostort alapított, melynek kegyurai is voltak. 1312–1315 között a települést még az e nemzetségből származott Radnót birtokában találjuk, kinek utód nélküli halála után, 1322-ben Kökényest I.'),
    ('Nagykölked', 'Körmendtől 7 kilométerre északnyugatra fekszik, az osztrák határ közelében. Délnyugati határszélét az államhatártól kevesebb, mint egy kilométer választja el. A szomszédos települések: észak felől Ják, kelet felől Rádóckölked, dél felől Harasztifalu, nyugat felől pedig Szentpéterfa. Kevés híja van annak, hogy a közigazgatási területe délnyugat felől ne érintkezzék még Vasalja határszélével is.'),
    ('Nagykörű', 'A Tisza mellett fekszik, Szolnoktól mintegy 25 kilométerre északkeletre. A közvetlenül szomszédos települések: északkelet felől Tiszabő, kelet felől Fegyvernek, dél felől Törökszentmiklós, délnyugat felől ez utóbbi városhoz tartozó Óballa (az eddigi négy mind a Tisza túlpartján), nyugat felől Csataszög, északnyugat felől Hunyadfalva, észak-északnyugati irányból pedig Kőtelek.'),
    ('Nagykőrös', 'Budapesttől körülbelül 80 kilométerre délkeletre fekszik, Cegléd és Kecskemét között félúton. Az Alföldön, a Duna–Tisza közi homokhátságon, a Pilis–Alpári-homokháton terül el. A város területének kb. 67%-a erdő, uralkodó fafajtája a tölgy, a nyár, az akác és a kőris. A város neve az utóbbiból származik. A szomszédos települések: északon Nyársapát, északkeleten Törtel, keleten Kocsér, délkeleten Szentkirály, délen Kecskemét, nyugaton Lajosmizse, északnyugaton pedig Csemő.'),
    ('Nagylak', 'Az egykori mezőváros ma Romániához tartozik. A jelenlegi magyar területen lévő Nagylak a Maros jobb partján található romániai Nagylak város határrésze volt. A két belterület, Kendergyár és Újtelep alkotja a mai magyarországi községet. Közigazgatásilag hozzá tartozik a kb. 40 fő által lakott Balatán külterület is.'),
    ('Nagylengyel', 'A településen polgárőrség működik. Nagylengyel Zalaegerszegtől délnyugatra, a Göcsej kapujában terül el. Környékén nagy kiterjedésű szőlőhegyek és erdők találhatóak, helyenként 280 méteres tengerszint feletti magasságot elérő dombokkal. A 18. században a rósászeghi Rósás és Grebenár, mileji Salamon, és az ákosházi Sárkány nemesi családok voltak földbirtokosok a településen helyezkedik el.'),
    ('Nagylóc', 'Szécsény szomszédságában, attól délkeletre fekvő település, amely a Novohrad-Nógrád UNESCO Globális Geoparkhoz tartozik. Legközelebbi szomszédai nyugat felől Rimóc, dél felől Hollókő, északkelet felől pedig Nógrádmegyer és Magyargéc, bár Hollókőt leszámítva egyikkel sincs közvetlen közúti kapcsolata. Már a honfoglaláskor is lakott település. A lóc jelentése szláv nyelven: vadászok, fogók.'),
    ('Nagylók', 'A környező települések közül Hantos 4,5, Sárosd és Mezőfalva 11-11, Nagyvenyim 11,5, Dunaújváros pedig 17,5 kilométer távolságra található. Viszonylag közel fekszik hozzá Sárszentágota és Sárkeresztúr, de utóbbi két községgel közvetlen közúti összeköttetése nincs. A terület már a római időkben is lakott hely volt, a környéken ókori sírokat találtak, melyek kocsirészeket is tartalmaztak.'),
    ('Nagylózs', 'A szomszédos települések: észak felől Pinnye, kelet felől Ebergőc, délnyugat felől Sopronkövesd, északnyugat felől pedig Pereszteg. Közigazgatási területe messze északkeleten, egy hosszabb szakaszon Hegykő, délkeleten pedig egy egészen rövid szakaszon Röjtökmuzsaj határszélével is érintkezik. Sopronból autóbusszal közelíthető meg.'),
    ('Nagymizdó', 'Körmendtől 9 kilométerre délkeletre fekszik, a Kemenesháton, a Rába völgye mellett. A szomszédos települések: Katafa, Szarvaskend és Hegyhátsál. Vasútállomással nem rendelkezik. A mizdó név a mézadó szóból származik. Az itt élő szolgálónép látta el mézzel a királyi udvart, és a nyugati határőrizet embereit. A település ősidők óta lakott. Határában neolitikus cserepekre és kőeszközökre bukkantak a régészek.'),
    ('Nagymágocs', 'A településnek a legfőbb turisztikai látványossága az itt található Károlyi-kastély. A községben egy éven át nevelkedett Petőfi Sándor fia, Petőfi Zoltán. Nagymágocs Szentes és Orosháza között helyezkedik el, a Mágocs-ér mellett. Szomszédai: észak felől Fábiánsebestyén, északkelet felől Árpádhalom, dél felől Székkutas, délnyugat felől Derekegyház-Tompahát, nyugat felől Derekegyház, északnyugat felől pedig Szentes-Lapistó.'),
    ('Nagymányok', 'A Mecsek hegység keleti kiágazásának északi oldalán fekszik, szép természeti környezetben. Területének déli része hegyes-dombos, a többi irányban nagyrészt síkság. A fővárostól, Budapesttől 170, a megyeszékhelytől, Szekszárdtól 27, Pécstől pedig 45 kilométerre helyezkedik el. Az első írásos emlék 1015-ből maradt fenn, amikor Damaslaus herceg a Manek alakban…'),
    ('Nagynyárád', 'A település német neve Großnaarad. Horvátul több elnevezés is létezik. A töttösiek Jaradnak, a lánycsókiak Naradnak, a hercegszántóiak Narodnak, a mohácsiak Njarodnak hívták a falut. Az oszmán hódoltság alól felszabadított, majd javarészt németországi telepesekkel újratelepített délkelet-dunántúli tájegység, az úgynevezett „Schwäbische Türkei” jellegzetes települései közé tartozik.'),
    ('Nagyoroszi', 'A Börzsöny északkeleti lábánál fekszik. A szomszédos települések: észak felől Ipolyvece, északkelet felől Patak, kelet felől Horpács, délkelet felől Borsosberény, délnyugat felől Diósjenő, nyugat felől Kemence és Bernecebaráti, északnyugat felől pedig Drégelypalánk. Csak kevés híja van annak, hogy nem határos nyugat-északnyugat felől még Honttal is.'),
    ('Nagypall', 'Nagypall a Mecsek lábainál, ezen belül is a Zengőtől délkeletre található, Pécsváradtól mintegy három kilométerre. Az ország távolabbi részei felől a 6-os főúton érhető el a legegyszerűbben, pécsváradi letéréssel. Nagypall megállóhely a belterület keleti szélén, a mai Petőfi utca végén létesült, egykori helye a jelenlegi állapotában csak burkolatlan úton közelíthető meg.'),
    ('Nagypeterd', 'Szigetvártól keletre, Szentlőrinctől nyugatra fekszik, mindkét várostól egyaránt körülbelül 7–8 kilométerre. A szomszédos települések: észak felől Nyugotszenterzsébet, északkelet felől Nagyváty, kelet felől Kacsóta, délkelet felől Szentdénes, dél felől Rózsafa, nyugat felől pedig Botykapeterd. A település mellett már a római korban is hadiút húzódott.'),
    ('Nagypirit', 'A nyugati és északi határrészt a folyót kísérő rétek fedik, az egykori mocsaras "Marcal-bozót" mára megszelídült nyomaként. Dél és kelet felé már kicsit magasabb, szántókkal borított felszín húzódik. A legközelebbi szomszéd falu, az innen keletre elterülő Kispirit mindössze fél kilométerre fekszik. Távolabb, déli irányban erdőket is találhatunk. A település közlekedési helyzete viszonylag kedvezőtlen, csak Boba, illetve Csögle irányából érhető el, a 8415-ös úton.'),
    ('Nagypáli', 'A település földrajzilag a Dunántúl délnyugati részén, a Közép-zalai dombság, ismert nevén Göcsej és Kemeneshát között fekszik, enyhe lejtésű, széles dombhátakon. Vízrajzilag a Zala folyó vízgyűjtőjéhez tartozik. A megyeszékhely, Zalaegerszeg északi szomszédságában helyezkedik el, a város központjátől nagyjából 8 kilométerre. A további szomszédos települések: észak felől Lakhegy, kelet felől Egervár, nyugat felől Kispáli, északnyugat felől pedig Nagykutas.'),
    ('Nagyrada', 'A településen polgárőrség működik. A régészeti leletek azt igazolják, hogy Pribina–Kocel időszak területe ide húzódott. IX–X. századi temetőt tártak fel. Valószínű továbbra is lakott hely lehetett. Rada neve először a zalavári apátság Szent István korabeli (1019) alapító levelében fordul elő. Lakosai az általuk megtermett javakból tizedet fizettek, és művelték az apátság itteni földjeit.'),
    ('Nagyrozvágy', 'Miskolctól 112 kilométerre keletre fekszik, a Bodrogköz északi részén, a szlovák határ mellett. A szomszéd települések: kelet felől Kisrozvágy körülbelül 2 kilométerre, dél felől Cigánd 11 kilométerre, nyugat felől pedig Pácin 7 kilométerre helyezkedik el. Délkelet felől határos még Ricse területével is, de a két község belterületei közúton csaknem 10 kilométer távolságra vannak egymástól, beékelődik közéjük nemcsak Kisrozvágy, de a Nagyrozvágytól 5 kilométerre keletre fekvő Semjén is.'),
    ('Nagyrábé', 'Lakott területéhez igazából csak két település van közel, Bihardancsháza észak-északnyugat, illetve Bihartorda észak-északkelet felől, de külterületei a központjától messze elnyúlnak, főleg északi és keleti irányban. Ily módon határos északon Sáppal, keleten Bakonszeggel, délkeleten Zsákával, délen Darvassal, délnyugaton Füzesgyarmattal, nyugaton Biharnagybajommal és északnyugaton Báránddal, továbbá kevés a híja, hogy nem határos északon még Földessel is.'),
    ('Nagyrákos', 'Az Őrségben, az Őrségi Nemzeti Park területén elhelyezkedő egykori mezőváros Őriszentpétertől 3 kilométerre délkeletre, Zalalövőtől 12 kilométerre nyugatra fekszik a Zala folyó mellett. Vasúton a Boba–Bajánsenye-vasútvonalon közelíthető meg, amelyen egy megállója van, Nagyrákos megállóhely. Jellegzetes őrségi szeres település. A vasúttól északra fekszik keleten Alsószer, nyugaton Csárdaszer, a kettő között északon Nemesszer, míg a vasúttól délre Belsőszer és Devecserszer.'),
    ('Nagyrécse', 'Nagykanizsától északkeletre, a Bakónaki-patak melletti dombos területen fekszik. Kiterjedt külterületei révén a térség több más településével is határos, ezek az alábbiak: észak felől Nagybakónak, északkelet felől Csapi és Kisrécse, kelet felől Zalasárszeg és Zalaszentjakab, délkelet felől pedig Miháld. Déli és nyugati irányból egyaránt Nagykanizsához tartozó területek határolják.'),
    ('Nagyréde', 'A falu igen gazdag múltját kétkötetes monográfiában dolgozta föl a néhai dr. Molnár József, a falu szülötte. Első fennmaradt okleveles említése 1275-ben történt villa Rede inferior (Alsóréde falu) alakban helyezkedik el. Birtokosa ekkor az Aba nemzetség Rédey ága volt. E család leszármazottai a települést két részre osztották, így Alsó-, Kis- Szentmártonréde valamint Felsőréde és Nagyréde, Boldogasszony-Réde és Fancsatelke nevű falurészekre helyezkedik el.'),
    ('Nagyrév', 'A Tisza bal partján fekszik, a megyeszékhely Szolnoktól délre. Közigazgatási területének szomszédai észak felől Tiszajenő, északkelet felől Cibakháza, délkelet felől Kunszentmárton, dél felől Tiszainoka, nyugat felől pedig Tiszakécske, amely a Nagyrévhez legközelebbi város is egyben.'),
    ('Nagysimonyi', 'A Kemenesháton, a Ság-hegytől 5 kilométerre északnyugatra, Celldömölktől 7 kilométerre nyugatra helyezkedik el. A megyeszékhely Szombathelytől mintegy 40 kilométerre helyezkedik el. A szomszédos községek: észak felől Ostffyasszonyfa, kelet felől Tokorcs (2,5 kilométer), dél felől Mesteri, délnyugat felől pedig Sitke (3,5 kilométer). Közigazgatási területe a központjától távol érintkezik még egy-egy rövid szakaszon északkelet felől Kemenesmihályfa, északnyugat felől pedig Sárvár határszélével is.'),
    ('Nagyszakácsi', 'Nagykanizsától keletre, Marcalitól délnyugatra, Somogyzsitfa, Tapsony, és Mesztegnyő közt fekvő település. Központján a Szenyér és Hollád közti 6803-as út halad keresztül, ezen érhető el a 68-as és a 7-es főutak felől is. Közigazgatási területének északnyugati részét átszeli a Marcali-Galambok közti 6805-ös út is, de lakott területeit az nem érinti.'),
    ('Nagyszekeres', 'Szomszédai: észak felől Mánd, északkelet felől Nemesborzova, kelet felől Kisszekeres, délkelet felől Jánkmajtis, dél felől Zsarolyán, nyugati és északnyugati irányból pedig Penyige. A település nevét a királyi várhoz tartozó szekerezéssel…'),
    ('Nagyszentjános', 'A Kisalföld északkeleti peremén, a Győr–Tatai-teraszvidéken helyezkedik el, Gönyűtől délkeletre, a Bakony-értől keletre, Győrtől mintegy 25 kilométer távolságra. Az út innen dél felé halad tovább, Bőny és Bana határvidékéig helyezkedik el. Vasúton is könnyen elérhető a község, a Budapest–Hegyeshalom–Rajka-vasútvonalon, melynek egy megállási pontja van itt.'),
    ('Nagyszokoly', 'A Külső-Somogyi dombságban fekszik, Tamásitól mintegy 15 kilométernyire észak-északnyugati irányban. Korábbi elnevezései: Zecul, Zokol, Sokal. A mai is hivatalban lévő elnevezése 1903 óta használatos. A község és környéke is egyaránt már az ókor óta lakott volt, melyet számos kelta és római-kori lelet bizonyít. III.Béla magyar király uralkodása alatt a Máltai lovagrend épített itt kolostort. 1187. július 23-án kelt pápai bulla szerint (melyet III.Orbán pápa adott ki) a község a Máltai lovagrend tulajdonát képzi.'),
    ('Nagyszékely', 'A Tolnai-Hegyhát egyik kistelepülése, zsáktelepülés, Pincehely felől közelíthető meg. Talán a község egyik, első, - Székely - elnevezésével találkozhatunk egy 1428-ban keltezett oklevélben, mely Bottka Miklós szerződésével kapcsolatos. Nagy valószínűséggel az okiratban szereplő Alsó- és Felső-Szekel a mai Kisszékely és Nagyszékely községekkel azonos.'),
    ('Nagysáp', 'A helység neve vitatott eredetű. A sápad, vagy sápaszt igéből válhatott tulajdonnévvé, vagy a Sáp helynév a német eredetű magyar sáf, dézsa, sajtár főnévből alakult át. A "Nagy" előtag különbözteti meg Nagysápot Őrisáptól helyezkedik el. Tökéletes lösz medencében fekszik. Neve ezért lett Nagy Sár. (Ez változott utóbb Nagy Sáppá).” A helyi hagyomány szerint a zsellérektől sok adót, nagy sápot szedtek, s emiatt lett a falu neve Nagysáp.'),
    ('Nagytarcsa', 'A Gödöllői-dombság nyugati peremén, a Szilas-patak sekély völgyében fekvő községet Budapest XVI. és XVII. kerülete, Kistarcsa és Isaszeg határolja. A környék már az őskortól lakott terület volt, amit az itt feltárt vas, illetve szkíta leletek is bizonyítanak, de találtak itt 10. századból való magyar köznépi temetőt is. Az első írásos említése 1352-ből származik, a második 1403-ból.'),
    ('Nagytevel', 'A Bakony lábánál, Pápától 8 kilométerre, Adásztevel és Homokbödöge közt fekvő település. A község csak közúton közelíthető meg, a Pápa-Béb között húzódó 8303-as úton. Nagytevel nevét 1422-ben említette először oklevél. A település a zirci cisztercita apátság birtokai közé tartozott. A törökök 1526 után elfoglalták, a falu elnéptelenedett, de az apátság 1696 körül sziléziai, morva, frank és német telepeseket telepített le a faluban. 1910-ben 920 lakosából 123 magyar, 797 német volt.'),
    ('Nagytilaj', 'A Dunántúlon, a Kemeneshát délkeleti szegletében, a Nagytilaji-patak mellett fekszik. A megyeszékhely, Szombathely körülbelül 55 kilométerre, Vasvár körülbelül 20, Zalaszentgrót nagyjából 15, Zalaegerszeg mintegy 20 kilométerre található innen. A közúti tömegközlekedést a Volánbusz biztosítja. Szombathellyel, Vasvárral és Zalaegerszeggel is közvetlen autóbuszjáratok kötik össze.'),
    ('Nagytálya', 'Füzesabonytól északra, Egertől délre, Mezőkövesdtől nyugatra fekszik, mindhárom várostól közel azonos (körülbelül 10-13 kilométeres) távolságra. Nagytálya nevét egy pápai tizedjegyzék említette először Talha minor és Talha major (Nagy- és Kis-Tálya) néven helyezkedik el. Mindkét helység az egri püspökség birtoka volt. 1430-ban Kistályát az egri püspökség a szomszédos Novajjal együtt az újonnan alapított egri prépostságnak adományozta. 1546…'),
    ('Nagytótfalu', 'Pécstől délre, Siklós keleti vonzáskörzetében található. A szomszédos települések: észak felől Vokány, északkelet felől Palkonya, kelet felől Kisharsány, nyugat felől pedig Siklós. Központja közúton csak Siklós vagy Kisharsány felől érhető el, mindkét irányból az 5715-ös úton. Az Árpád-kori település, Nagytótfalu nevét 1294-ben említették először az oklevelek, Touthfolu néven helyezkedik el.'),
    ('Nagytőke', 'A falu Szentes és Kunszentmárton között található a Tőke-ér és a Veker-ér szögletében, a Tisza és Hármas-Körös is közel folyik a faluhoz. Határát majdnem teljesen körbeveszik a két előbbi város külterületei, csak északnyugat felől határos egy harmadik település, Szelevény területével. A főútról a 4516-os útra kell lehajtani, ez vezet végig belterületének északi szélén és ez köti össze Szentes több külterületi határrészével (Magyartés, Zalota, Kurca-parti üdülőövezet) is.'),
    ('Nagyvarsány', 'Különálló településrésze a központjától 1,5 kilométerre délnyugatra fekvő Szabadságtanya. Észak felől Gyüre, dél-délkelet felől Kisvarsány határolja, mindkettővel szinte egybeépült. Közigazgatási határa keleten a Tisza, nyugaton pedig Ilk és Gemzse szántóföldjeivel határos. Szemközti szomszédja a Tisza túloldalán Tiszaszalka: ezen a szakaszon történt a Tokaj fölötti első mederátvágás 1852-ben és ugyanitt az utolsó is, 1974-ben helyezkedik el.'),
    ('Nagyvejke', 'Közigazgatási területének északkeleti szélét érinti a Bonyhád-Tevel közti 6535-ös út is, de lakott területe vonatkozásában zsákfalunak tekinthető.Földúton azonban könnyedén átjuthatunk Tevelre, Kisvejkére, Bonyhádvarasdra, Závodra 3–4 kilométer megtételével. Az öt számjegyű, 65 164-bekötőúton érhető el, amely Aparhant és Mucsfa között ágazik el a Bonyhád-Kurd közti 6538-as útból.'),
    ('Nagyveleg', 'Nagyveleg a Vértes és a Bakony között, a Mórtól 9 kilométerre nyugatra található. A település valószínűleg a honfoglalás idején jött létre. A területet Árpád fejedelem saját törzse számára foglalta el, majd az Anonymus által is említett Velek nevű vitéze a szolgálataiért kapott földön létrehozta a róla elnevezett települést. Ez azonban csak feltételezés.'),
    ('Nagyvenyim', 'Nyugati határában több bányató, déli oldalán pedig egy Baracsig húzódó erdősáv található. Nagyvenyimtől északra nagy kiterjedésű szántók fekszenek, amelyeket szórványosan beépült zártkerti teleksorok szakítanak meg. A falu területén, a Fűzfa utcában avar kori (7–8. századi) temető részletét tárták fel, 2013-ban. Nagyvenyim neve a 15. századtól szerepel a forrásokban, elsőként 1429-ben említik Venyim néven helyezkedik el.'),
    ('Nagyvisnyó', 'Szilvásváradtól 5 kilométerre, hegyekkel ölelt helyen, a Bükki Nemzeti Park területén, a Szilvás-patak mellett fekszik. A település főútja az Eger és Kazincbarcika térsége (Mónosbél és Vadna) között húzódó 2506-os út. A falu első okleveles említése 1239-ben történt terra (a latin nyelvből eredő szó, a jelentése föld) Wisna alakban. 1293-ból a possessio (latin eredetű szó, jelentése birtok) Wysnyo névalak maradt fenn.'),
    ('Nagyváty', 'Pécstől nyugatra helyezkedik el. A szomszédos települések: észak felől Ibafa, északkelet felől Dinnyeberki, délkelet felől Kacsóta, délnyugat felől Nagypeterd, északnyugat felől pedig Nyugotszenterzsébet. A székely ispánság, mely körülbelül 400 fős létszámú lehetett, és az Okor és Alma melléke falvaiban lakó székelyekből állt.'),
    ('Nagyvázsony', 'Északon a 600 méterre magasodó Kab-hegy határolja, délen a Balaton-felvidék dombjai. A Vázsonyi-medence kőzetanyaga mészkő, de a bazaltfeltörések is elég nagy területet foglalnak el. Jól látható ez a Kab-hegy bazalttakaróján helyezkedik el. A mészkő alól számos forrás tör elő, a község határát erdő övezi. A falut keresztül szeli a Vázsonyi-Séd, amelynek vize az Eger-vízbe jutva a Balatont táplálja.'),
    ('Nagyér', 'Északi szomszédja Tótkomlós, de nyugat és kelet felől is a városhoz tartozó területek veszik körül. Déli szomszédja Ambrózfalva, illetve délkelet felől, egy ponton érintkezik a területe Mezőhegyesével is. A településen észak-déli irányban végighalad a Tótkomlóstól Pitvarosig, majd onnan Makó-Rákosig húzódó 4426-os út, ezen érhető el mindkét végponti település irányából.'),
    ('Nagyút', 'A Mátra lábainál, az Alföld északi peremén fekszik. A közvetlenül határos települések: kelet felől Kompolt, dél felől Tarnazsadány, délnyugat felől Nagyfüged, nyugat felől Ludas, északnyugat felől pedig Detk. Az állomás közúti elérését ugyancsak…'),
    ('Nak', 'Dombóvártól északnyugatra, Lápafő és Attala közt fekvő település. Nak a középkorban a Szák nemzetség tagjainak birtoka volt. 1307 előtt a település az e nemzetség Gyaláni ágához tartozó I. Istvánnak birtoka volt, aki a falut 1307-ben vejének Kapolyi Istvánnak ajándékozta.'),
    ('Narda', 'A mai község 1950-ben jött létre, Kisnarda és Nagynarda egyesítésével. Szombathelytől mintegy 10 kilométerre nyugatra fekszik, közvetlenül a magyar–osztrák határ mellett. A szomszédos települések az országhatár magyar oldalán: északkelet felől Bucsu, kelet felől Dozmat, dél felől pedig Felsőcsatár. Nyugatról és északnyugatról a két legközelebb fekvő település a már Ausztriához tartozó Csém (Schandorf) és Csajta (Schachendorf), mindkettőtől alig 3 kilométer távolságra helyezkedik el.'),
    ('Naszály', 'Tata északnyugati szomszédságában fekszik, a várost Almásfüzitővel összekötő 8138-as út mentén, utóbbi településhez valamivel közelebb. Naszály Tata és Komárom között található. A 2300 lakosú kicsiny falunak történelme igen viharos. A vaskori hallstatti kultúra embere telepedett meg először a község területén, halomsíros temetkezéseik őrzik emléküket.'),
    ('Nekézseny', 'Az Upponyi-hegység délkeleti szélén, a Csernely-patak mentén helyezkedik el, Ózdtól 15 kilométerre délkeletre, Putnoktól 21 kilométerre délre, Miskolctól pedig 46 kilométerre északnyugatra. Jelentős a területén az erdők aránya. A környező települések: Csokvaomány, Dédestapolcsány, Lénárddaróc, Sáta, a legközelebbi város Ózd (körülbelül 15 kilométerre).'),
    ('Nemesapáti', 'A Principális-csatorna és a Szévíz-patak közé eső dombok ölelésében fekszik, az itt nagyjából nyugat-keleti irányban húzódó Zala jobb (déli) parti oldalán, a megyeszékhelytől, Zalaegerszegtől légvonalban 8, közúton körülbelül 12 kilométerre északkeletre. A közvetlenül határos települések: észak felől Vöckönd, Zalaistvánd és Kemend (Kemendollár része), északkelet felől Gyűrűs, kelet felől Orbányosfa, délkelet felől Nagykapornak, dél felől Kisbucsa és Alsónemesapáti, nyugat felől Pethőhenye, északnyugat felől pedig Alibánfa.'),
    ('Nemesbikk', 'Miskolctól 49 kilométerre délre helyezkedik el, a Hejő folyása közelében. A közvetlenül határos települések: észak felől Sajószöged, északkelet felől Tiszaújváros, délkelet felől Hejőkürt, dél felől Tiszatarján, délnyugat felől Mezőcsát, nyugat felől Igrici, északnyugat felől pedig Hejőpapi és Hejőbába. Elsőként a Váradi regestrumban említik, 1221-ben helyezkedik el.'),
    ('Nemesborzova', 'A megye legkisebb közigazgatási területű települései közé tartozik, ennek is köszönhető, hogy mindössze három településsel szomszédos: északkelet, kelet és délkelet felől kisszekeresi, délnyugat felől nagyszekeresi, nyugat és északnyugat felől pedig mándi területek határolják.'),
    ('Nemesbük', 'A község jó minőségű aszfaltúton csak egy, Hévízről induló, hét kilométeres bekötőúton (a 73 178-as számú mellékúton) érhető el. Zalaköveskúttal egy számozatlan, önkormányzati fenntartású betonút köti össze. Külterületének nyugati részét egy rövid szakaszon érinti a 76-os főúttól Kehidakustány (Kustány) felé vezető 7335-ös út is. A település első említése 1408-ból való.'),
    ('Nemesbőd', 'A falu a Gyöngyös-sík középső részén fekszik, Szombathely kelet-északkeleti vonzáskörzetében, a város központjától 10 kilométerre. A határos települések: észak-északkelet felől Vasszilvágy, kelet felől Vát, dél felől Vép, északnyugat felől pedig Vassurány. Csak kevés híja van, hogy közigazgatási területe nem határos nyugat felől még Szombathely Zanat nevű városrészével is.'),
    ('Nemescsó', 'Kőszegtől 6 kilométerre délkeletre, Lukácsházától 3 kilométerre keletre fekszik a Borzas-patak (gyakoribb nevén, pl. térképeken Kozár-Borzó patak) mellett. Már az őskorban lakott hely volt, határában kőkorszaki és római emlékeket is találtak. A települést 1248-ban Cho alakban említik először. Első ismert földesura Csói Márton volt. 1283-ban Chou, 1418-ban Chow, 1420-ban Felsew Cho alakban említik. 1511-től szerepel a nemes előtaggal, ekkor Nemes Cho alakban említik.'),
    ('Nemesdéd', 'Nagykanizsától délkeletre, Nemesvid, Varászló és Vése közt fekvő település. Nemesdéd nevét az 1332–1337. évi pápai tizedjegyzék említette először. 1405-ben Deed, 1415-ben Dyd, 1453–1476 között Felseded neveken írták. 1406-ban és 1418-ban Berzenczei Lorántfi György nyerte adományul.'),
    ('Nemesgulács', 'Mintegy 1000 lakosú település a Tapolcai-medence déli részén, a Gulács nyugati tövében helyezkedik el. A tájat ez a 393 méter magas bazaltvulkáni tanúhegy uralja, nevezik cukorsüvegnek vagy magyar Fuzsijamának is, melynek tetejére turistaút vezet. 1961-ig üzemelt itt kőbánya, nyomát a hegy sebei őrzik. Badacsonytomajnál a 7316-os útra kell rátérni, a Tapolca felé jelzett irányt követve.'),
    ('Nemesgörzsöny', 'A Marcal völgyében helyezkedik el, Pápától bő 10 kilométerre északnyugati irányban. Települési szomszédai: észak felől Marcaltő, kelet felől az előbbihez tartozó Ihász, dél felől Nagyacsád, nyugat felől Magyargencs, északnyugat felől pedig Egyházaskesző. Közigazgatási területe az előbbiek mellett még érintkezik, délnyugati irányban Mezőlak határszélével is.'),
    ('Nemeshany', 'Környező települései közül csak innen érhető el közúton – az előbbi útból a község nyugati szélén, északnyugat felé kiágazó 73 153-as úton letérve – a zsákfalunak számító Bodorfa. A legközelebbi települések: Bodorfa, Káptalanfa, Gyepükaján, Csabrendek, Devecser és Sárosfőpuszta. A Hany helységnév a magyar régi hany (mocsár, láp, ingovány) főnévből keletkezett.'),
    ('Nemeshetés', 'Zalaegerszeg délkeleti szomszédságában fekszik, a legközelebbi szomszédja dél felől Búcsúszentlászló. Területének keleti felén áthalad a Pölöske-Alsónemesapáti között húzódó 7363-as út, de belterületi része zsákfalunak tekinthető, mert közúton csak az előbbi útból nyugat felé kiágazó 73 226-os úton érhető el. A település több évezredes létét igazolja, hogy a község mostani legmagasabb pontján, melyet Oláhvárosnak hívnak, csiszoltkő-korszaki szerszámok kerültek elő (pl.: késő neolit korból származó kőbalta).'),
    ('Nemeske', 'Szigetvár vonzáskörzetében helyezkedik el, a város központjától mintegy 9 kilométerre nyugat-délnyugati irányban. A szomszédos települések: észak felől Merenye és Tótszentgyörgy, kelet felől Molvány, dél felől Kistamási, délnyugat felől Pettend, nyugat felől pedig Nagydobsza. Nemeske nevét az oklevelek 1492-ben említették először. Nevét valószínűleg a faluban élő sok kisnemes után kaphatta.'),
    ('Nemeskeresztúr', 'A településen mobilposta, könyvtár, művelődési ház, labdarúgócsapat és egy alapítvány működik. Csak kevés híja van annak, hogy nem határos kelet-délkelet felől még Hosztóttal, nyugat felől pedig Keléddel is.'),
    ('Nemeskisfalud', 'Mindössze három települési szomszédja van: észak felől Szenyér, dél felől Böhönye, északnyugat felől pedig Tapsony. Zsáktelepülés, közúton csak a 68-as főútról leágazó 68 106-os számú mellékúton közelíthető meg. A település nevét először 1331-ben említette egy oklevél, de az ezt követő 200 éves időszak története ismeretlen helyezkedik el. A 20. század elején a 82 házzal rendelkező falu a böhönyei körjegyzőséghez tartozott.'),
    ('Nemeskocs', 'A szomszédos települések: északkelet felől Csögle, délkelet felől Nagypirit, dél felől Boba, nyugat felől Köcsk, északnyugat felől pedig a Celldömölkhöz tartozó Izsákfa. A környező települések közül Boba 2, Izsákfa 3,5, Egyházashetye 7, Kemenespálfa 8,5, Celldömölk és Csögle 10-10, Jánosháza 11, Adorjánháza pedig 13,5 kilométer távolságra található.'),
    ('Nemeskolta', 'Szombathelytől 17 kilométerre délkeletre fekszik. A szomszédos települések: észak felől Vasszécseny, északkelet felől Csempeszkopács, délkelet felől Rábatöttös, dél felől Gyanógeregye, nyugat felől pedig Sorkifalud. Északi külterületei között elhalad még a 8703-as út is. Az ország távolabbi részei felől a 8-as, majd a 87-es főutakon érhető el a legegyszerűbben, utóbbiról Csempeszkopácsnál kell nyugat felé letérni.'),
    ('Nemeskér', 'A Nyugat-magyarországi peremvidék része. A környék legkisebb közigazgatási területű települései közé tartozik, mindössze három települési szomszédja van: keleti és déli irányból Újkér, délnyugat-nyugat felől Egyházasfalu, északnyugat felől pedig Lövő. Kevés híja van annak, hogy nem határos északkelet felől még az amúgy távolabb fekvő Sopronkövesddel is.'),
    ('Nemesládony', 'Kőszegtól keletre, Répcelaktól nyugatra fekszik. A szomszédos települések: észak felől Iván, északkelet felől Csér, kelet felől Nagygeresd, dél felől Tompaládony, nyugat felől pedig Sajtoskál. Északnyugat felől a legközelebbi település Simaság, de a közigazgatási területeik nem érintkeznek. Nevét az oklevelek 1234-ben említették először Ladun néven, ekkor már mint templomos hely volt említve. 1332-ben a pápai tizedjegyzék Szent Miklósról elnevezett templomát is említette.'),
    ('Nemesmedves', 'A szocialista rendszerben úgy tartották (az ott élők és néhány történész kivételével), hogy április 4-én itt történt meg az ország teljes felszabadulása a német megszállás alól és ekkor fejeződött be a magyar nyilas kormányzat elűzése, és hogy ezt a falut szabadították fel utoljára 1945. április 4-én a szovjet hadsereg katonái.'),
    ('Nemesnádudvar', 'Bajától északra fekszik, mintegy 22 kilométer-re, a Bácska északi részén, a Duna-völgy és a Duna-Tisza-közi hátság találkozásánál, a Duna-völgyi-főcsatorna partján. Maga a település különleges módon két tájra tagolódik, az „alsó határra”, mely régen a Duna ártere volt, és a „felső határra”, mely kb. 30 méterrel magasabb fekvésű. A közvetlenül határos települések: északkelet felől Hajós, kelet felől Érsekhalma, dél felől Rém, délnyugat felől Sükösd, északnyugat felől pedig Dusnok.'),
    ('Nemesnép', 'Önkormányzata Csesztregen működik. Ebből a 7421-esből ágazik ki még a település külterületén egy öt számjegyű út, amely Lendvajakabfa, illetve a szlovéniai Kebeleszentmárton irányába vezet. A falutól délnyugatra (közigazgatásilag Szentgyörgyvölgy területén) működő határátkelő ma már bármikor használható.. Autóbusszal Csesztreg felé Zalaegerszeg és Lenti érhető el közvetlen járatokkal, illetve északra Őriszentpéter.'),
    ('Nemespátró', 'Nagykanizsa déli vonzáskörzetében fekszik. Az elsorvasztásra ítélt egykori curialis (=nemesi) falunak 1952-ben az előnevét is elvették, és csak 1991. január 1-jén kapta vissza. A pártállami időszakban (ahogy olykor a régebbi korokban is) egyszerűen Pátró volt a község hivatalos neve, és noha a helybeliek….'),
    ('Nemesrempehollós', 'Szombathelytől 20 kilométerre délkeletre, Egyházasrádóctól 6 kilométerre keletre, Egyházashollóstól 5 kilométerre északra fekszik, sík vidéken. A Rába vályoggal fedett közép- és újpleisztocén kavicstakarójára települt. A szomszédos települések: észak felől Sorokpolány, északkelet felől Sorkikápolna, délkelet felől Rábahídvég, dél felől Egyházashollós, délnyugat felől Molnaszecsőd, nyugat felől pedig Egyházasrádóc.'),
    ('Nemesrádó', 'A faluba az ebből keletnek kiágazó, másfél kilométer hosszú 73 216-os út vezet, de Nemesrádó nem igazi zsáktelepülés, mert külterületi önkormányzati utakon el lehet érni Szentpéterúr irányából is. Kőhegy külterület, amely a község központjától számítva nagyjából 1 kilométer távolságra található délnyugati irányban. Jellegét tekintve külterület összeírt lakóegység és népesség nélkül.'),
    ('Nemesszalók', 'A két legközelebbi város Pápa és Celldömölk, a község nagyjából félúton, mindkettőtől egyaránt 15-15 kilométerre található. A környék vulkáni tanúhegyei közül a Somlótól és a Ságtól is nagyjából 16-16 kilométerre fekszik, a Bakony legközelebbi hegyei 20–25 kilométerre magasodnak. A szomszédos települések: észak felől Vinár, északkelet felől Mihályháza, kelet felől Nyárád, dél felől Dabrony és Csögle, délnyugat felől Egeralja és Adorjánháza, északnyugat felől pedig Külsővat és Marcalgergelyi.'),
    ('Nemesszentandrás', 'A településen polgárőrség működik. A választáson egyedüli jelöltként a korábbi alpolgármester indult. A lakosok 81,5%-a római katolikusnak, 1,9% reformátusnak, 1,1% felekezeten kívülinek vallotta magát (14% nem nyilatkozott). 2022-ben a lakosság 81…'),
    ('Nemessándorháza', 'A településen polgárőrség működik. Közúton csak a 73 227-es számú mellékúton érhető el, amely Búcsúszentlászló központjában ágazik ki a 7363-as útból. A lakosok 66,5%-a római katolikusnak, 0,98% reformátusnak, 4,3% felekezeten…'),
    ('Nemesvid', 'Központján kelet-nyugati irányban a 6805-ös út halad át, délről, Vése felől pedig 6816-os út vezet idáig helyezkedik el. Vid települést középkorban a királyi szakácsok alapították, akik itt és a közeli Nagyszakácsi területén kaptak birtokot és jelentős adókedvezményeket.'),
    ('Nemesvita', 'A Tapolcai-medence nyugati határán, illetve a Keszthelyi-fennsík keleti szélénél fekszik, a Balatontól körülbelül 3 kilométerre északra. Különálló településrészei Törekpuszta, Szúnyogmajor és Feketecser, mindhárom a központjától 2körülbelül 4 kilométerre északi, illetve északkeleti irányban helyezkedik el.'),
    ('Nemesvámos', 'Nemesvámos a Balaton-felvidéken, Veszprém szomszédságában, tengerszint felett mintegy 300–400 méter-es magasságban fekvő község. Határában az őskortól kezdve megtelepült az ember, akit vonzottak a kedvező természeti feltételek: az erdők bőséges élelmet, építőanyagot, a patakok és erek tiszta ivóvizet biztosítottak az itt élőknek. A falu északi határát átszelő, a geológiai törésvonalban kialakult Veszprém–Tapolca főútvonal, illetve dél felől a Balaton felé vezető útvonal stratégiai jelentőségűvé tették a községet.'),
    ('Nemti', 'A Novohrad-Nógrád UNESCO Globális Geopark települése. Nemti (Németi) Árpád-kori település. Nevét 1227-ben említette először oklevél Nemti alakban. 1297-ben Nemti nemeseket említ egy oklevél, akik a Hangonyiak eskütársai voltak. 1331-ben a Nemti család birtoka.'),
    ('Neszmély', 'Távolsága Budapesttől 70, Tatától 12 kilométer. Neszmély és környéke ősidők óta lakott hely, ahol minden kor képviselve van, de leggazdagabb a római kori leletanyag. Első írott nyomát az 1237–40 között készült Albeus jegyzékben találjuk, akkor nevét Nezmel, 1341-ben Neezmel alakban írták. 1339-ben Károly Róbert, az örökös nélkül elhalt ember birtokaként rá szállott Neszmélyt két szigettel, cserjésekkel, szántókkal, száraz és vízi vámmal, valamint révvel egyetemben fia nevelőjének, Polonia…'),
    ('Nick', 'A megyeszékhely, Szombathely körülbelül 40, a legközelebbi város, Répcelak mintegy 2 kilométerre található. A szomszédos települések: észak felől Répcelak, északkelet felől Rábakecöl, kelet felől Kenyeri, délnyugat felől Uraiújfalu, nyugat felől pedig Vámoscsalád. Nagyon kevés híja van annak, hogy nem határos délkelet felől még Csöngével is. A 86-osról Répcelak déli részén lekanyarodva, az M86-osról a répcelaki csomópontnál letérve érhető el a község.'),
    ('Nikla', 'Marcalitól 11 kilométerre keletre, a Balatontól (Balatonfenyvestől) közúton 30, légvonalban 15 kilométerre délre fekszik. A környező települések: Táska, Csömend, Öreglak és Pusztakovácsi. A település nevét a Miklós személynév latin változatából, a Nicolausból eredeztetik a szakértők. Első ismert írásos említése 1332-ből származik. Ez egy pápai tizedjegyzék amin feljegyezték Mikala néven helyezkedik el.'),
    ('Noszlop', 'A Bakonyalján fekszik, a legközelebbi város Devecser (9,5 kilométer). Neve az 1086 és 1235 közötti okleveleken Nuztupe, Nuztup néven bukkan fel, 1488-tól már Nozlop, Noslop alakban szelídült a mai Noszlop változattá. A tatárok és a törökök támadása idején rövid időre elnéptelenedett, de a természeti adottságai folytán a környéken lévő elpusztult falvak lakosságát is magába olvasztotta, így a kisebb településből idővel mintegy központtá vált.'),
    ('Noszvaj', 'A falu és üdülőövezete: Síkfőkút, Egertől 10 kilométer-re, a Bükki Nemzeti Park déli határán, a 667 méter magas Várhegy lábánál, a Kánya-patak völgyében helyezkedik el. A település nevét korábban Neznay, Noznay szláv személynévvel azonosították, mert a honfoglalás környékén ezen a területen szláv települési foltok voltak, de a legújabb kutatások ezt cáfolják, eszerint a Noszvaj név a Noszvijj szóból származik, mely jelentése a „mi falunk” és latin eredetű szó.'),
    ('Nova', 'Továbbá kisebb utak indulnak Novából Szilvágy (7415) és Mikekarácsonyfa-Csömödér (7547) felé. Autóbuszjáratok sűrűn érintik a települést: Zalaegerszeg, Lenti, Keszthely és Budapest könnyen elérhető a faluból helyezkedik el. Ez a községrész Nova központjától keletre található. Első írásos említése 1256-ból ismert, Zagur néven helyezkedik el. A terület nagy részén a patakok szabályozása előtt mocsaras területek voltak.'),
    ('Novaj', 'A környéket szántók, szőlők, rétek és ősgyepek jellemzik, az erdősültség minimális (hozzávetőlegesen 2,7%), helyenkénti kultúrerdőkkel, melyekben az akác a domináns fafaj. A területen szép számmal élnek apróvadak (főleg mezei nyúl és fácán), nagyvadfajaink közül megtalálható a vaddisznó és az őz, sőt alkalmanként egy-egy szarvas is ide látogat. A talajt jellemzően barnaföld és erdőtalaj alkotja, de homoklelőhelyeket is találunk.'),
    ('Novajidrány', 'A szomszédos települések: észak felől Garadna, kelet felől Vizsoly, dél felől Méra, nyugat felől Szalaszend, északnyugat felől pedig Fulókércs. Novaj nevű település nevével már a XIII. században lehet találkozni a korabeli iratokban. 1255-ben IV. Béla király a jászói prépostságnak adományozta a falu alsó részein fekvő földeket. A község nevét ekkor Noénak írták…'),
    ('Nyalka', 'A Pannonhalmától kelet-délkeletre elterülő síkságon fekszik, Győrtől 23 kilométerre délre. A Sokorói-dombságban, útkereszteződésben települt, fésűs beépítésű falu. Szent István 1001. évi keltezésű oklevelében említi Chimudi névalakban, mint Szent Benedek-rendnek adott birtokot. 1250-ben Szent László szabadalomlevelében Hymud alias Nelka alakban említi, ettől kezdve a pannonhalmi apátság birtoka.'),
    ('Nyergesújfalu', 'A Dunántúli-középhegység északi szélén, a Duna folyam jobb partján található. Távolsága Esztergomtól 16 kilométer, kelet felől Tát 7 kilométer távolságra esik, a nyugatról szomszédos Lábatlannal gyakorlatilag összeépült. Dél felől az 5 kilométernyire fekvő Bajóttal szomszédos. Magyarország földrajzi tájegységeit tekintve a közigazgatási területe a Kisalföldhöz tartozó Almás–Táti-Duna-völgyre és a Dunántúli-középhegység részét képező Központi-Gerecsére esik.'),
    ('Nyim', 'Magas dombokkal és erdővel körülvett, nyugodt kis falu, mely amellett, hogy elzárt helyen fekszik, nincs messze a forgalmas és központszerű Siófoktól sem, népessége pedig lassan, de folyamatosan növekszik. Itt található hazánk egyik legrégibb Árpád-kori rom-maradványa, a Kási vár. A szomszédos települések: észak felől Ságvár, északkelet felől Ádánd, délkelet felől Som, dél felől Bábonymegyer, délnyugat felől pedig Torvaj.'),
    ('Nyirád', 'Nagy kiterjedésű a település községhatára és régészeti leletek bizonyítják, hogy közvetlen környéke ősidők óta lakott volt. Nyirád a Dunántúl középső részén, a Bakony hegység délnyugati lábánál, az Ajka, Tapolca, Devecser és Sümeg által határolt terület középpontja közelében fekszik, mind a négy várostól 10-15 kilométernyi távolságra. Az Agár-tető északnyugati nyúlványainak tövében, a Kis-Bakony és a Deák-hegy alatt simuló lankás területen települt a község.'),
    ('Nyugotszenterzsébet', 'Nyugotszenterzsébet (korábbi írásmóddal: Szenterzsébet, S. Elisabeth) nevét 1332-ben említette először egy oklevél S. Nevét valószínűleg temploma védőszentjéről kapta. 1333-ban papja 20, 1335-ben 5 báni pápai tizedet fizetett.[forrás?] A török időkben is folyamatosan lakott volt, mindig magyarok lakták. A település régen búcsújáró hely volt. A településen található élelmiszer- és italbolt is, azonban egyik sem üzemel, így a helyiek a faluba naponta bejáró mozgóboltokból tudnak vásárolni.'),
    ('Nyáregyháza', 'Elérhető az M5-ös autópályáról is, Újhartyánnál letérve, Újlengyel érintésével, a 405-ös főúton, majd ugyancsak a 4606-os úton helyezkedik el. Szomszédai közül Csévharaszttal és Dánszentmiklóssal a 4605-ös út köti össze. Nyáregyháza nevét 1411-ben említették először az oklevelek, mint a Csévi, a Nyáry és a Nyáregyházi családok birtokát. 1438-ban Nyáry Lajos az őseitől öröklött itteni birtokaira királyi adományt nyert.'),
    ('Nyárlőrinc', 'Nyárlőrinc a Duna-Tisza közi homokhátság „fővárosától”, Kecskeméttől 18 kilométerre fekszik kelet-délkelet felé. A közvetlenül határos települések: északkelet felől Szentkirály, kelet felől Lakitelek, délkelet felől Tiszaalpár, dél felől Kiskunfélegyháza, délnyugat felől Városföld, nyugat-északnyugat felől pedig Kecskemét.'),
    ('Nyársapát', 'Az Alföldön, a Duna–Tisza közi homokhátságon, a Pilis–Alpári-homokháton helyezkedik el. Északon Cegléddel, délen Nagykőrössel, nyugaton Csemővel, keleten Törtellel határos. Az utótag apátságra mint birtokosra utal, az előtag eredeti jelentése nyáras (nyárfás). Nyársapát nevét 1376-ban említették először az oklevelekben, mint a Nyársapáti család tulajdonát.'),
    ('Nyárád', 'Pápa délnyugati vonzáskörzetében fekszik, a várostól mintegy 10 kilométerre. Északkeleti külterületi határrészei érintkeznek a város [illetve az ahhoz tartozó Borsosgyőr] határszélével. A további szomszédos települések: kelet felől Pápadereske, kelet-délkelet felől Dáka, délnyugat felől Dabrony, nyugat felől Nemesszalók, északnyugat felől pedig Mihályháza.'),
    ('Nyékládháza', 'A Sajó–Hernád-síkon, a Hejő-patak partján, a megyeszékhely, Miskolc vonzáskörzetében, attól 14 kilométerre délre található. A közvetlenül határos települések: észak felől Mályi, északkelet felől Sajólád, kelet felől Ónod, délkelet felől Muhi és Hejőkeresztúr, dél felől Emőd, nyugat felől Bükkaranyos, északnyugaton pedig egy rövid szakaszon határos még Miskolccal is.'),
    ('Nyíracsád', 'A szomszédos települések: észak felől Nyírlugos, kelet felől Fülöp, délkelet felől Nyírábrány, dél-délnyugat felől Vámospércs, nyugat felől Nyírmártonfalva, északnyugat felől pedig Nyíradony. Csak közúton érhető el, Nyíradony és Nyírábrány felől a 4904-es, Vámospércs és Nyírlugos felől a 4905-ös úton. Buzitapuszta nevű különálló településrésze az előbbi két út keresztezésétől dél felé kiinduló, bő 4 kilométer hosszú 49 103-as számú mellékúton érhető el.'),
    ('Nyíradony', 'A közvetlen szomszédos települések: észak felől Szakoly, északkelet felől Nyírmihálydi, kelet felől Nyírlugos, délkelet felől Nyíracsád, dél felől Nyírmártonfalva, délnyugat felől Hajdúsámson, nyugat felől pedig Balkány. Különálló külterületi településrészei Tamásipuszta és Aradványpuszta, előbb 10, utóbbi 7 kilométerre fekszik délnyugati irányban a város központi részeitől, valamint Szakolykert, amely a központtól mintegy 3 kilométerre északra található.'),
    ('Nyírbogdány', 'A Közép-Nyírségben fekszik, Nyíregyházától mintegy 16 kilométerre északkeletre. Különálló településrészei Gyártelep, illetve Kónyatelep, melyek a falu központjától mintegy 3, illetve 4 kilométerre helyezkednek el észak-északnyugati irányban. Gyártelepen hozzávetőlegesen 780 ember él. Határában folyik a kállai, valamint a sényői főfolyás, mely a Lónyai-főcsatornába torkollik.'),
    ('Nyírbogát', 'A Nyírség déli részén helyezkedik el, a megyeszékhely Nyíregyházától 38, Debrecentől 43 kilométerre. A környező települések közül Nyírbátortól 6, Nyírgelsétől pedig 7 kilométer választja el. Déli határszéle közelében, de teljes egészében a határai között emelkedik a Nyírség és az egész Tiszántúl legmagasabb pontja, a 183 méter magas Hoportyó. Nyírbogát neve személynévi eredetű, azt az Árpád-korban élt Bogát (hadvezér)ről vette.'),
    ('Nyírbátor', 'A 15-16. századból fennmaradt világi és egyházi építészeti emlékeiről, és a város egykori földesurairól, a Báthoriakról is híres. A város történelmét az egymást váltó fejedelmek, főurak – Báthoriak, Bethlenek, Rákócziak és Károlyiak – határozták meg. Virágzása mégis a Báthori-családhoz kötődik.'),
    ('Nyírbéltek', 'A környező települések közül Nyírbátor 17, Nyírlugos 7, Nyíradony 14, Piricse 8,5, Ömböly 7,5, Encsencs 7,5, Nyírpilis pedig 12 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Piricse, kelet felől Ömböly, dél felől Penészlek, délnyugat felől Fülöp, nyugat felől Nyírlugos, északnyugat felől pedig Encsencs. Csak közúton közelíthető meg, Nyírbátor és Nyírábrány felől a közöttük húzódó 4906-os, Nyíradony felől pedig az onnan idáig húzódó 4903-as úton.'),
    ('Nyírcsaholy', 'Mátészalka déli szomszédságában helyezkedik el, a város központjától 6 kilométerre, a Kraszna folyó közelében. A további szomszédos települések: északkelet felől Kocsord, délkelet felől Nagyecsed, dél felől Fábiánháza, délnyugat felől Nyírkáta, nyugat felől pedig Nyírmeggyes. Közúton a 4918-as úton érhető el, Mátészalka vagy Fábiánháza érintésével.'),
    ('Nyírderzs', 'A környező települések közül Nyírbátor 9,5, Nyírcsászári 4,5, Mátészalka 19, Nyírgyulaj 4,5, Ófehértó 11, Kántorjánosi 4, Őr 9 kilométer távolságra található. Kántorjánosival és Hodásszal mezőgazdasági utak kötik össze. A falu a 17. században elnéptelenedett, de a 18. században görögkatolikus lakosokkal telepítették be, kiknek ekkor már görögkatolikus templomuk is volt.'),
    ('Nyíregyháza', 'Dinamikusan fejlődő város, a térség gazdasági és kulturális motorja, vonzó turisztikai célpont. Ütemes fejlődésen a 18. században esett át, amely azóta is tart. Az Észak-Alföld második legjelentősebb településének számít. 40 kilométer-re fekszik Szlovákiától, 60 kilométer-re Ukrajnától, 50 kilométer-re pedig Romániától. A régió központjától, Debrecentől 50 kilométer-re fekszik északra.'),
    ('Nyírgelse', 'A Nyírség délkeleti részén fekszik, a környező települések közül Nyírbátortól 13, Nyírbogáttól 7, Szakolytól 6, Nyírmihályditól 2, Nyíregyházától 40, Debrecentől pedig 36 kilométerre található. Aránylag későn, 1310-ben említik először, amikor a Gutkeled nemzetség tagjai osztoztak rajta pedig puszta személynévi eredetű helynév, tehát korábbi település lehet. 1387-ben már a Kállay család László nevű tagjáé volt. 1418-ban még lakott hely, Pazonyi Albert birtoka volt két sor házzal, amelyben hét telek volt, de csak négyen állott épület.'),
    ('Nyírgyulaj', 'A község a Délkelet-Nyírség meghatározó nagyságú és elhelyezkedésű települése. Baktalórántháza, Máriapócs és Nyírbátor ölelésében helyezkedik el, a megyeszékhely Nyíregyházától 33 kilométerre keletre. Földrajzi adottságai megfelelőek, bár gazdaságföldrajzi elhelyezkedését tekintve az adottságai nem a legkedvezőbbek, mivel a főbb és forgalmasabb gazdasági-kereskedelmi útvonalak elkerülik.'),
    ('Nyíri', 'A szomszédos települések észak felől Füzérkomlós, kelet felől Filkeháza, dél felől Bózsva, délnyugat felől Nagyhuta, nyugat felől pedig Telkibánya. Észak felől a legközelebbi település Hollóháza, de közigazgatási területeik nem határosak. Abból az irányból Nyíri határszéle Füzérhez tartozó lakatlan külterületekkel érintkezik. A legközelebbi város: Pálháza.'),
    ('Nyíribrony', 'A közvetlen szomszédos települések: északkelet felől Ramocsaháza, kelet felől Nyírkércs, dél felől Levelek, délnyugat felől Apagy, nyugat felől Nyírtét, északnyugat felől pedig Székely. Nyíribrony nevét az oklevelek 1329-ben Ibrun néven említették először, 1332-ben pedig Ibron-nak írták nevét. 1435-ben Upory, később a Kemecsey, 1465-ben a Miglészy, 1476-ban pedig a Kállay család volt Ibrony birtokosa.'),
    ('Nyírjákó', 'A legközelebbi város a 4 kilométerre délre fekvő Baktalórántháza. A térség más fontosabb települései közül Nyírkarász 10, Kisvárda 25 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Petneháza, kelet felől Rohod, dél felől Baktalórántháza, délnyugat felől Nyírkércs. északnyugat felől pedig Laskod. Csak közúton érhető el, Baktalórántháza vagy Petneháza érintésével, a 4105-ös úton.'),
    ('Nyírkarász', 'A megye, és egyben a Nyírség északkeleti részén fekszik, Kisvárda, Baktalórántháza és Vásárosnamény városok között, a kistáj középső részén. A közvetlen szomszédos települések: észak felől Gyulaháza, délkelet felől Nyírmada, dél-délkelet felől Rohod, dél felől Petneháza, nyugat felől pedig Nyírtass. Központja csak a Kisvárda-Baktalórántháza között húzódó 4105-ös úton érhető el, a két végponti város irányából.'),
    ('Nyírkáta', 'A megye és a Nyírség keleti-délkeleti részén helyezkedik el, a megyeszékhely Nyíregyházától körülbelül 50, Debrecentől 67, Budapesttől pedig 271 kilométerre. A közvetlenül szomszédos települések: észak felől Nyírmeggyes, északkelet felől Nyírcsaholy, délkelet felől Fábiánháza, dél felől Terem, nyugat-délnyugat felől Nyírbátor, nyugat felől Nyírcsászári, északnyugat felől Nyírderzs, észak-északnyugat felől pedig Hodász.'),
    ('Nyírkércs', 'A Közép-Nyírségben fekszik, Nyíregyházától mintegy 36 kilométerre kelet-északkeletre, Baktalórántházától 4 kilométerre északnyugatra. A közvetlen szomszédos települések: észak felől Laskod, északkelet felől Nyírjákó, délkelet felől Baktalórántháza, délnyugat felől Levelek, nyugat felől Nyíribrony, északnyugat felől pedig Ramocsaháza. Nyírkércs a környék egyik legrégebbi települése.'),
    ('Nyírlugos', 'Ez a vidék a Nyírség legnagyobb futóhomokos területe, felszíne homokbuckák tömegéből áll. A homokból a szél parabolabuckákat és szélbarázdákat alakított ki. Tengerszint feletti magassága 160 méter, itt található a Nyírség második legmagasabb pontja, a Tisza és a Körös vidékének vízválasztó vonala. 5838 hektár területen fekszik, amelyben a termőterület 5129 hektár, kivett terület 709 hektár.'),
    ('Nyírlövő', 'A környező más települések közül Pap 5, Lövőpetri 4, Szabolcsbáka 9, Újkenéz 16, Tornyospálca 21, Aranyosapáti 8,5, Vásárosnamény 23 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Tornyospálca, kelet felől Aranyosapáti, dél felől Lövőpetri, nyugat felől pedig Pap. A falu területe 791 hektár (1374 kat. hold), amiből 68 hektár belterület (1985-ös adat).'),
    ('Nyírmada', 'A Nyírség északkeleti peremén helyezkedik el. A környező települések közül Vásárosnaménytól 13, Pusztadobostól 2, Gyulaházától 11, Rohodtól 6, Ilktől 8, Petneházától 20, Vajától 10, Nyírjákótól 18 kilométerre található. A megyeszékhelytől, Nyíregyházától mért távolsága 43 kilométer. Éghajlata mérsékelten meleg, az évi napsütéses órák száma 1950. Talaja kovárványos barna erdőtalaj, humuszos homok és barnaföld.'),
    ('Nyírmeggyes', 'A térség más nagyobb városai közül Nyírbátor 14,5, Vásárosnamény 23 kilométer távolságra található. A további szomszédos települések: észak felől Jármi, kelet felől Nyírcsaholy, dél felől Nyírkáta, nyugat felől pedig Hodász. Szent László fennmaradt kultusza miatt királyi telepítésűnek vélik a falut. A 14. század elején a Tövisiek Közép-Szolnokból származó családjának birtokában volt a település, 1337-ben egy idevaló…'),
    ('Nyírmihálydi', 'A környező települések közül Balkánytól 15, Szakolytól 7, Nyírgelsétől 6, Nyírlugostól 14 kilométerre található. Nyírlugossal a 4914-es, Balkánnyal a 4913-as út köti össze. Árpád-kori település. Nevét a 13. században említették először Miháldi vagy Mihálydi alakban helyezkedik el. A település ekkor a Gutkeled nemzetség birtoka. 1372-ben a Gutkeled nemzetségből származó Rakamazi Domokos a szomszédos Szakoly…'),
    ('Nyírmártonfalva', 'A szomszédos települések: észak felől Nyíradony, kelet felől Nyíracsád, dél felől Vámospércs, délnyugat felől Debrecen Haláp és Nagycsere nevű, külterületi városrészei, északnyugat felől pedig Nyíradony-Tamásipuszta. Nyugat felől a legközelebbi település Hajdúsámson, de közigazgatási területeik kevés híján nem határosak. A közigazgatási terület földminősége 7,6 átlagos aranykorona értékű, talaja jellemzően homoktalaj.'),
    ('Nyírparasznya', 'A Nyírség északkeleti részén helyezkedik el, Nyíregyházától 53, Mátészalkától 11, Vajától 10, Nagydobostól 5 kilométer távolságra található. Csak közúton közelíthető meg, Nyírmada és Jármi felől a 4106-os, Vaja és Ópályi felől pedig a 4116-os úton helyezkedik el. Nagydobossal egy jobbára szilárd burkolatú, de számozatlan, alsóbbrendű út kapcsolja össze.'),
    ('Nyírpazony', 'A megyeszékhely, Nyíregyháza északkeleti szomszédságában helyezkedik el, a város központjától 6 kilométerre. A rendszeres összeköttetés leginkább Nyíregyházával biztosított, de közvetlen járatokkal elérhető többek között Nyírtura, Sényő, Nyírbogdány, Székely, Ramocsaháza, Baktalórántháza, Mátészalka, Kisvárda (utóbbi három csak a Székelyen át közlekedő járatokkal).'),
    ('Nyírpilis', 'A környező városok közül Nyírbátor 8,5, Mátészalka 28,5, Nagykálló 30,5, Nyírbogát 15,5, a kisebb települések közül Encsencs 9, Piricse 3,5 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Nyírvasvári, délkelet felől Bátorliget, délnyugat felől Piricse, északnyugat felől pedig Nyírbátor. Zsáktelepülésnek tekinthető, mivel közúton csak egy útvonalon érhető el, Piricse északi része felől, a Nyírbátor-Nyírábrány közti 4906-os útból kiágazó 49 129-es számú mellékúton.'),
    ('Nyírtass', 'A Nyírség középső-északi részén fekszik, Kisvárdától 12 kilométerre dél-délnyugati irányban. A közvetlen szomszédos települések: észak felől Ajak, északkelet felől Gyulaháza, kelet felől Nyírkarász, délkelet felől Petneháza, dél felől Laskod, délnyugat felől Ramocsaháza, nyugat felől Berkesz és Gégény, északnyugat felől pedig Pátroha. A község nevét mind a néphagyomány, mind az írásos adatok szerint Tas honfoglaló vezérről kapta.'),
    ('Nyírtelek', 'Több néven is szerepelt a történelem folyamán helyezkedik el. A megyeszékhely vonzáskörzetében helyezkedik el, attól északnyugatra, a Nyugati-, vagy Löszös-Nyírség kistáj részeként. A szomszédos települések: észak felől Buj, északkelet felől Kótaj, kelet, délkelet és dél felől Nyíregyháza [keletről Nyírszőlős, délkeletről Felsőpázsit, délről pedig Vajdabokor városrészek], délnyugat felől Nagycserkesz, nyugat felől Tiszaeszlár, északnyugat felől Tiszanagyfalu, észak-északnyugat felől pedig Gávavencsellő.'),
    ('Nyírtura', 'A megye és egyben a Nyírség középső részén fekszik, a megyeszékhely Nyíregyháza belvárosától mintegy 10 kilométerre. A környék más fontosabb települései közül Sényőtől 4, Kemecsétől és Székelytől pedig 8-8 kilométer választja el. A közvetlen szomszédos települések: észak felől Kemecse, északkelet felől Nyírbogdány, kelet felől Sényő, délkelet felől Napkor, dél felől Nyíregyháza, délnyugat felől pedig Nyírpazony.'),
    ('Nyírtét', 'A környező fontosabb települések közül Apagy és Székely 6-6, Napkor 10,5, Levelek 11,5, Demecser 12,5, Baktalórántháza 17, Berkesz 18, Nagykálló pedig 20,5 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Székely, kelet felől Nyíribrony, dél felől Apagy, nyugat felől Sényő, északnyugat felől pedig Nyírbogdány. Délkelet felől a legközelebbi település Levelek, de a közigazgatási területeik (kevés híján) nem érintkeznek.'),
    ('Nyírvasvári', 'A megyeszékhely Nyíregyházától 46, Mátészalkától 22 kilométer választja el. A környék más, kisebb települései közül Terem 9, Nyírpilis 5, Nyírcsászári 8, Nyírgelse 21, Bátorliget pedig 12 kilométer távolságra található. Csak közúton közelíthető meg, Nyírbátor vagy Terem érintésével, a 4915-ös úton helyezkedik el. Neve a Vasvár helynévből magyar névadással keletkezett.'),
    ('Nyírábrány', 'Az 5.571 hektár (55,7 km²) területű település természetföldrajzilag a Dél-Nyírség kistájhoz tartozik, egyszersmind része a történelmi és tájföldrajzi alapokon kialakult Ligetalja tájnak és település-együttesnek. Területe a Dél-Nyírség tájegység 100–162 méter közötti tengerszint feletti magasságú, szélhordta futóhomokkal fedett hordalékkúp-síkságának északkeleti részét alkotja, ahol széles sávban alakultak ki szélbarázdák, kisebb deflációs mélyedések.'),
    ('Nyúl', 'A község Győrtől 13 kilométer-re dél-délkeletre, a Sokorói-dombságban terül el. A faluról az első hiteles adat egy 1086-os összeírásból való, amikor már létező helynek írták le. Nagynyúl a 15. századtól a győri káptalan tulajdonába került, és a káptalan birtokát ettől fogva Káptalannyúlnak nevezték. A falu először királyi udvari birtok volt. Népei várszolgák, szolgáló népek.'),
    ('Nyőgér', 'Az ország távolabbi részei felől a 8-as vagy a 834-es főutak érintésével közelíthető meg. A 351 lakosú, soros beépítésű, szalagtelkes település nevét a nyögéreknek nevezett török eredetű népcsoportról eredeztetik. Első okleveles említése 1390-ből maradt fenn Newger alakban, de már jóval korábban települt lehetett. 1390-ben a Kanizsai család kapta Sárvár várának tartozékaként.'),
    ('Nábrád', 'Fehérgyarmat városától mintegy 5 kilométerre északnyugatra fekszik, a Szamos jobb partján . Három folyó közelsége is szépíti környezetét: a Szamos alig 200 méterre, a Túr 2 kilométerre, a Tisza pedig nagyjából 5 kilométerre folyik innét. A szomszédos települések: észak felől Kisar, északkelet felől Nagyar, kelet felől Fehérgyarmat, dél felől Tunyogmatolcs, nyugat felől Szamoskér, északnyugat felől pedig Kérsemjén helyezkedik el.'),
    ('Nádasd', 'Nádasd Körmendtől 7 kilométerre délre fekszik, a Vasi-Hegyháton. A környező települések: észak felől Körmend, északkelet felől Katafa, kelet felől Hegyhátsál, délkelet felől Hegyháthodász és Vaspör, dél felől Zalaháshágy, délnyugat felől Szőce, nyugat felől Daraboshegy, északnyugat felől pedig Halogy. A települést érintő, alsóbbrendű utak egyike a Molnaszecsődtől Szarvaskenden át idáig húzódó 7445-ös út, amely a közigazgatási terület keleti részén ér véget, a 86-os főútba csatlakozva.'),
    ('Nádasdladány', 'Budapest 80, Siófok 35, Pákozd 30, Székesfehérvár 19, Várpalota 13, Polgárdi 11, Ősi 5 kilométer távolságra található. A település nevét az írásos források 1266-ban említik először, Ladányi Gunger nevében fordult elő, egy hitbérügy…'),
    ('Nádudvar', 'A Hortobágy tájegység déli részén helyezkedik el, a megyeszékhely Debrecentől mintegy 40 kilométerre nyugatra. Különálló településrésze Mihályhalma, mely a központjától légvonalban körülbelül 7-8, közúton nagyjából 10 kilométerre fekszik nyugati irányban. Közigazgatási területének nyugati fele nagyrészt a Hortobágyi Nemzeti Park részterülete, s ily módon természetvédelmi oltalom alatt áll.'),
    ('Nágocs', 'A körülbelül 620 lakosú község a külső-somogyi dombvidék központi részén fekszik, a Balatontól 25, Kaposvártól 35 kilométer távolságra. Szomszédai északon Kapoly, nyugaton Andocs, délen Somogyacsa, keleten Zics, Miklósi és Kára helyezkedik el. Közigazgatási határának keleti szélét érinti még a Szorosadtól Kapolyig húzódó, a 6508-as és 6511-es utakat összekötő 6516-os út is.'),
    ('Nárai', 'Szombathelytől mintegy 7 kilométerre délnyugatra fekszik a Vasi-dombságban, a Bolygó-patak mellett. A szomszédos települések: észak felől Torony és Sé, északkelet és kelet felől Szombathely, dél felől Ják, délnyugat felől Pornóapáti, nyugat felől Horvátlövő és Vaskeresztes, északnyugat felől pedig Felsőcsatár és Dozmat. A településen, annak főutcájaként végighúzódik északkelet-délnyugati irányban a Szombathely újperinti városrészétől Pornóapátiig vezető 8713-as út, ez a legfontosabb közúti elérési útvonala.'),
    ('Négyes', 'A közvetlenül határos települések közül Borsodivánka 4 kilométer-re, Egerlövő 8 kilométer-re, Tiszabábolna 8 kilométer-re, Tiszavalk pedig 3 kilométer-re található. A legközelebbi város Mezőkövesd, mintegy 19 kilométerre helyezkedik el. A község neve a négyes számra vezethető vissza. A legvalószínűbb néveredet szerint a falu a községi utak négyes elágazása után kapta a nevet.'),
    ('Németbánya', 'A Bakonyban, erdők által övezve fekszik, a megyeszékhely Veszprém és Pápa között légvonalban majdnem félúton, bár utóbbi városhoz valamivel közelebb. A közvetlenül határos települések: kelet felől Szentgál, délkelet felől Csehbánya, dél felől Kislőd, délnyugat felől Farkasgyepű, nyugat felől pedig Bakonyjákó. Északi szomszédja, annak 1981-es megszüntetéséig Iharkút volt, utóbbi település egykori területe ma Bakonyjákóhoz tartozik.'),
    ('Németfalu', 'A kustánszegi tónál gyönyörű kilátás nyílik a dombon fekvő falura helyezkedik el. A falut 1266-ban említik először, a neve német telepesekre utal. A falu első ismert birtokosai a Harkályiak, később pedig a Salomváriak voltak, majd a Salomváriak férfi ágon való kihalta után a 15. század elején leányágon való örökléssel az Ostffy családé lett. 1553-ban Bánfi Istvánt valamint a Brodarics és a Baltazár családokat említették a falu birtokosaiként.'),
    ('Németkér', 'Földút köti össze Alsószentivánnal, Bikáccsal és Vajtával. A mezőgazdasági területekre nem jellemző módon Németkér körül több ezer hektár erdő található. Többnyire akácosok, fenyvesek, de még vannak nyomokban ősi tölgyesek is. Németkér környéke már a kőkorszakban lakott lehetett, de a település létezésére utaló első írásos emlék 1193-ból ismert. Nevét 1333-ban Kyry, 1572-ben Kér formában jegyezték fel, 1789-ből ismert elsőként az előtaggal megtoldott novalak, Német-Keér írásmóddal, 1892-től pedig Németkér a neve.'),
    ('Nézsa', 'Az Északi-középhegységben, a Cserhát nyugati vonulatai között fekszik, közelebbről a Nézsa-Csővári-dombságban helyezkedik el. Átlagos tengerszint feletti magassága 235-270 méter. A közvetlenül határos települések: észak felől Legénd, kelet felől Nógrádsáp, dél felől Csővár, délnyugat felől Penc, nyugat felől Keszeg, északnyugat felől pedig Alsópetény.'),
    ('Nógrád', 'A közvetlenül határos települések: észak felől Diósjenő, északkelet felől Tolmács, kelet felől Nőtincs, délkelet felől Berkenye, délnyugat felől pedig Szokolya. A falu (vár, megye) nevét a bolgár-szláv Novigrad, azaz Újvár elnevezésből kapta. Története a honfoglalás előtti időkre vezethető vissza, már ebben a korban is kulcsfontosságú helynek számított.'),
    ('Nógrádkövesd', 'Határától alig két kilométerre halad el az Országos Kéktúra útvonal. Közelében találhatók Szandavár várának romjai, melyekhez az Országos Kéktúra-útvonalon lehet a legkönnyebben feljutni. Járművel legkönnyebben a néhány éve újonnan épült – Nógrádkövesdről a Becske-Bercel közötti közútra átkötő, – a kőbányához kiágazó szilárd…'),
    ('Nógrádmarcal', 'A Cserhát északi nyúlványai szélén, az Ipoly völgyének találkozásánál helyezkedik el, egy erdőkkel határolt völgyben, átmenő forgalomtól mentesen, csendes környezetben. Lakott hely a történelem előtti időktől: 1907-ben kőkori leleteket tártak fel a közelben, s egy kettős gyűrűvel védett földvár is állt itt, amit egyes vélekedések szerint a szlávok építettek a népvándorlás korában.'),
    ('Nógrádmegyer', 'Szécsénytől keletre, a Cserhát északi részén, Magyargéc, Sóshartyán és Lucfalva között fekvő település, de az utóbbival nincs közúti kapcsolata. A Novohrad-Nógrád UNESCO Globális Geopark települése. A községbe Salgótarjánból és Szécsényből rendszeres autóbuszjárattal lehet eljutni, illetve munkanapokon hajnalban egy budapesti járat is indul.'),
    ('Nógrádsipek', 'A településen, amely a Novohrad-Nógrád UNESCO Globális Geopark része, keresztülhalad az Országos Kéktúra útvonala is. A falut a Cserhát hegyei, dombjai veszik körül. Szomszédjai Varsány, Hollókő és Herencsény, bár a két utóbbival nincs közvetlen közúti összeköttetése. A honfoglalás korában kialakult helyzetről nincsenek pontos adatok. Szécsény és vidéke későbbi birtokosai a Kacsics nemzetség, akik a 13. századtól a sűrűn települt vidéken várbirtokrendszert alakítottak ki.'),
    ('Nógrádszakál', 'Magyarország északi részén, az itt magyar-szlovák határfolyóként húzódó Ipoly mellett található. Közúton Szécsény és Ipolytarnóc felől is elérhető a 2205-ös úton, mely az Ipoly folyását követve, a község területén annak főutcájaként húzódik. Nógrádszakál a Novohrad-Nógrád UNESCO Globális Geopark települése. A határ magyar oldalán csak három települési szomszédja van: északkelet felől Litke, délkelet felől Szécsényfelfalu, dél felől pedig Ludányhalászi.'),
    ('Nógrádsáp', 'A legközelebbi város Rétság, mintegy 22 kilométerre helyezkedik el. A környék más nagyobb városai közül Vác 27, Aszód 30, Balassagyarmat 32, Budapest pedig 55 kilométerre található. A megyeszékhely, Salgótarján nagyjából 80 kilométer távolságra fekszik Nógrádsáptól. Nógrádsáp eredetileg két önálló település egyesítésével alakult ki. 1928-ban Alsó- és Felsősápot vonták össze Nógrádsáp néven helyezkedik el.'),
    ('Nőtincs', 'A falu nevének eredete bizonytalan helyezkedik el. Kiss Lajos 1978-ban kiadott, Földrajzi nevek etimológiai szótára című könyvében a szláv Netyko névből származtatja, ugyanis a 11. századtól kezdve többször telepedtek le szlávok, illetve a magyar seregekben szolgáló, Baltikumból származó vitézek a területen. Mások szintén a szláv eredetű netecs, netecsa szavakból eredeztetik, melynek jelentése: nem folyó víz.'),
    ('Okorvölgy', 'Husztót és Abaliget között fekszik, a Bükkösdi-víz völgyének egyik kiágazásában. A Mecsek legkisebb közigazgatási területű települései közé tartozik, mindössze három települési szomszédja van: északkelet felől Abaliget, dél felől Hetvehely, nyugat és észak felől pedig Szentkatalin. Okorvölgy és környéke már a bronzkorban is lakott hely volt. Területén a bronzkori halomsíros kultúra népének nyomait tárták fel. 1542-ben Okorwelgh alakban írva említették az oklevelek.'),
    ('Okorág', 'Szentlőrinctől délnyugatra, Sellyétől északra fekszik, az Ormánság északi részén. A szomszédos települések: északkelet felől Sumony, délkelet felől Csányoszró, dél felől Kákics, délnyugat felől Marócsa, északnyugat felől pedig Szentegát. A mai Okorág közigazgatási területe, a környék több településéhez hasonlóan már az ókorban is lakott hely kellett, hogy legyen, erre utalnak a térségből sok helyütt előkerült vaskori, rézkori vagy éppen római kori leletek.'),
    ('Okány', 'Természetföldrajzi szempontból a Kis-Sárrét nyugati részéhez tartozik. Szomszédai: észak felől Körösújfalu, kelet felől Zsadány, délkelet felől Mezőgyán (Nagygyanté), dél felől Sarkadkeresztúr és Sarkad, nyugatról Vésztő. Csak nagyon kevés a híja annak, hogy közigazgatási területe délnyugat felől nem érintkezik Tarhos határszélével is. Vésztővel a 4235-ös, Zsadánnyal a 4236-os út köti össze.'),
    ('Olasz', 'A több mint nyolcszáz éves településen, amely átvészelte a török megszállás időszakát is, ma mintegy hatszáz fő él. Pécstől mintegy 20 kilométerre délkeletre, Mohácstól 23 kilométerre nyugatra fekszik. A szomszédos települések: északkelet felől Máriakéménd, délkelet felől Szederkény, dél felől Belvárdgyula, délnyugat felől Birján, északnyugat felől pedig Hásságy.'),
    ('Olaszfa', 'Közigazgatási területének szélén elhalad a 7383-as út, de belterületi részeit tekintve Olaszfa zsáktelepülés, mivel közúton csak azon a 73 252-es számú mellékúton érhető el, amely Pácsony és Oszkó között ágazik ki ebből az említett útból, keleti irányban. A mai település 1941-ben jött létre két község, Kozmafa és Olaszka egyesítéséből, Kozmaolaszka néven.'),
    ('Olaszfalu', 'Különálló településrészei Alsópere és Felsőpere helyezkedik el. A községben történt a második világháború végén az országot megszálló szovjet csapatok (magyarországi összehasonlításban) egyik legkegyetlenebb, kifejezetten a civil lakosok ellen irányuló atrocitása, melynek 32 polgári személy (zömmel levente-korú fiatal) esett áldozatául.'),
    ('Olaszliszka', 'A közvetlen települési szomszédai: északkelet felől Vámosújfalu, délnyugat felől Szegilong, északnyugat felől pedig Erdőbénye. Közigazgatási területe az előbbiek mellett érintkezik még észak felől Erdőhorváti, észak-északkelet felől Tolcsva, délkelet felől a Bodrog túlpartján fekvő Viss, dél felől az ugyancsak bodrogközi Zalkod, dél-délnyugat felől pedig Bodrogkisfalud és Szegi határával is.'),
    ('Olcsva', 'A Szatmári-síkságon fekszik, Vásárosnamény déli szomszédságában, a Kraszna és a Szamos folyók között, illetve 1969 óta Vitka falu olcsvai részével a Kraszna bal partján. A Szamoson kompjárat közlekedik: ez a túlparton fekvő Olcsvaapátival biztosít összeköttetést. A Kaplony nemzetség alapítása. Neve szláv eredetű, jelentése: égerfa. A 14. század folyamán a nemzetség különböző ágai: a Bagossy, Csomaközy, Károlyi, Vetéssy családok osztoztak rajta.'),
    ('Olcsvaapáti', 'A Szamos jobb partján, a Tisza közelében ül meg a Szamosháton helyezkedik el. A két folyó közé települt falut az áradások sokszor elpusztították, ezért több lakóházat és gazdasági épületet természetes, vagy emelt dombra építettek. Olcsvával kompjárat köti össze. Olcsva és Apáti a 16. századig két különálló település volt, s csak 1573 körül olvadt össze, s kezdték Olcsvaapáti néven nevezni.'),
    ('Old', 'Siklóstól délkeletre, Siklósnagyfalu és Egyházasharaszti közt fekszik. Kelet felől határos még Kásáddal, illetve nyugat felől Alsószentmártonnal is, déli határszéle pedig hosszú szakaszon egybeesik az országhatárral. A legközelebbi (horvátországi) település abban az irányban a közigazgatásilag Baranyaszentistvánhoz (Petlovac) tartozó Torjánc (Torjanci).'),
    ('Oltárc', 'Oltárc a Letenyei-dombság kicsiny zsákfaluja. Nagykanizsától 32 kilométerre, Letenyétől 24 kilomnéterre, Zalaegerszegtől 43 kilométerre található. Eredetileg kétutcás falu az Oltárci-vízfolyás – illetve az e mentén haladó erdei kisvasút – két oldalán helyezkedik el. A község melletti bükkösökben bővelkedő táj a Natura 2000 ökológiai hálózathoz tartozó kiemelt jelentőségű természetmegőrzési területnek jelölt terület.'),
    ('Onga', 'A megyeszékhely Miskolctól mintegy 10 kilométerre keletre fekszik. Különálló településrésze a központjától légvonalban mintegy 5,5, közúton nagyjából 8 kilométerre északkeletre fekvő Ócsanálos. A közvetlenül határos települések: észak felől Szikszó, északkelet felől Sóstófalva és Újcsanálos, kelet felől Gesztely, délkelet felől Hernádkak, délnyugat felől Felsőzsolca, északnyugat felől pedig Arnót.'),
    ('Orbányosfa', 'Utóbbiból itt ágazik ki keletre a Bezeréd községbe vezető 73 218-as út. Első írásos említése 1429-ből származik, ekkor még Vrbanosfalva néven helyezkedik el. A lakosok 81,1%-a római katolikusnak, 2,4% reformátusnak, 4,9% felekezeten kívülinek vallotta magát (11,5% nem nyilatkozott). 2022-ben a lakosság 83,7%-a vallotta magát magyarnak, 5,4% németnek, 3,3% cigánynak, 2,2% egyéb, nem hazai nemzetiségűnek…'),
    ('Orci', 'A megyeszékhelytől, Kaposvártól északkelet felé található, alig nyolc utcából álló kisközség négy kilométerre keletre fekszik a városhoz tartozó Toponártól. Közúton a 6505-ös útból kiágazó 65 112-es számú mellékúton érhető el, amely innen még továbbvezet a zsáktelepülésnek számító Zimány központjába. A község nyugati részén folyik el az Orci-patak, amely Taszárnál a Kaposba torkollik.'),
    ('Ordacsehi', 'Szőlő- és borgazdasági szempontból a település a Balatonboglári borvidék részét képezi. A mai település 1939-ben jött létre Orda és Csehi (Balatoncsehi) egyesítésével. Orda neve az ősi török eredetű ordu szóból ered, jelentése királyi szállás / tábor, míg Csehi neve a cseh népnévből származik. Orda első írásos említése 1230-ból, Csehié 1333-ból maradt fenn.'),
    ('Ordas', 'A szomszédos települések: kelet felől Dunapataj, délnyugat felől Géderlak, nyugat felől Paks és a hozzá tartozó Dunakömlőd, északnyugat felől pedig Madocsa. Utóbbi három a Duna túlsó partján terül el. Nevét az oklevelek 1239-ben említették először villa Wrdas néven helyezkedik el. A középkorban a kalocsai érsek birtoka volt. Református anyaegyháza már 1614 előtt fennállt. 1695-ben, a török hódoltság alatt a falu háromnegyed portával adózott.'),
    ('Orfalu', 'Az osztrák-magyar-szlovén határ találkozásánál, az osztrák határátkelőhöz 12 kilométerre, a legközelebbi szlovén határátkelőhelytől 4 kilométerre található. Orfalu községet a vele szomszédos Újbalázsfalvával (ma Apátistvánfalva része) a 16. században említik oklevelekben. 1583-ban mint Orfalou néven lelhetjük fel az oklevelekben. A község helye minden kétséget kizáróan a 12. század vége előtt lakatlan erdősség volt.'),
    ('Orfű', 'A térség idege nforgalmi szempontból kiemelt jelentőségű települései közé tartozik. A Mecsek nyugati részén, Pécstől mintegy 17 kilométerre észak-északnyugati irányban fekszik. Már a történelem előtti időkben laktak a térségben emberek. Jelenlétüket a környéken megtalált használati eszközök igazolják. Erdőlakó, kóborló, vadászó, gyűjtögető életmódot folytattak.'),
    ('Orgovány', 'Az Alföldön, a Duna–Tisza közi homokhátságon, a Kiskunsági-homokháton helyezkedik el, Kecskeméttől 26 kilométerre délnyugatra. A központjától északra elterülő külterületi részei szinte teljes egészében a Kiskunsági Nemzeti Park Orgoványi rétek elnevezésű részterületéhez tartoznak. Lakóinak mintegy egynegyede (907 fő) külterületen él. A szomszédos települések: észak felől Ágasegyháza, északkelet felől Helvécia, kelet felől Jakabszállás, délkelet felől Bugacpusztaháza, dél felől Bócsa, délnyugat felől Páhi, északnyugat felől pedig Izsák.'),
    ('Ormosbánya', 'A környék az őskor óta lakott, a közelben találták a Rudapithecus hungaricus-leletet. A község területén is találtak ősembermaradványokat, valamint kelta kori leleteket. Ezek ma a Herman Ottó Múzeumban találhatóak. Az Ormos-patak völgyében bronzöntő műhely maradványait találták. Ebben a feltehetően rudabányai rezet ötvözték a messzebbről hozott ónnal és antimonnal.'),
    ('Ormándlak', 'A településen polgárőrség működik. Gombosszegtől keletre fekvő település. Ormándlak Árpád-kori település. A falu és környéke az őskor óta lakott hely. Nevét az írásos források 1260-ban említették először. Első ismert birtokosa az Ormándi család volt, melynek itt a 16. század végéig voltak birtokai. A 17. században már több családnak is volt itt birtoka, így a 20. század közepéig a Bagodi, Naypár, Hertelendy, Köhler, Andrási, Waisbecker, gróf Somssich és a Dervarics családnak is.'),
    ('Orosháza', 'A település gazdag mezőgazdasági hagyományokkal rendelkezik, különösen a növénytermesztés és az állattenyésztés terén. A város egyik legnagyobb vonzereje a Gyopárosfürdő, amely gyógyhatású termálvize és modern wellnessközpontja miatt népszerű turisztikai célpont. Emellett Orosháza kulturális élete is pezsgő, többek között múzeumokkal, rendezvényekkel és fesztiválokkal várja az érdeklődőket.'),
    ('Oroszi', 'Pápától délre, a Somlótól keletre, Doba, Noszlop és Borszörcsök közt fekszik. Dobával egy szilárd burkolatú, keskeny, de jó minőségű önkormányzati út köti össze. A kis falut feltehetőleg Szent István korában alapították, első írásos említése 1288-ból származik. A középkor folyamán parasztok és nemesek lakták, de 1550 után már csak nemesek voltak itt.'),
    ('Oroszlány', 'A Vértes északnyugati lábánál, a Vértesalja északkeleti peremén, a Tatabányától 15 kilométerre délnyugatra helyezkedik el. A szomszéd települések: észak felől Kecskéd és Környe, északkelet felől Vértessomló, kelet felől Várgesztes, délkelet felől Gánt, délnyugat felől Pusztavám, nyugat felől Bokod, északnyugat felől pedig Dad. Oroszlány a hazai közlekedési hálózat szempontjából meglehetősen félreeső elhelyezkedésű város, nemcsak főközlekedési utak, de még másodrendű főutak sem érintik, kizárólag négy számjegyű mellékutakon érhető el.'),
    ('Oroszló', 'A közvetlenül határos települések: észak-északkelet felől Felsőegerszeg, északkelet felől Varga, kelet felől Liget, dél felől Bodolyabér, nyugat felől Mindszentgodisa. Délkelet felől a legközelebbi település Magyarszék, de közigazgatási területeik kevés híján nem érintkeznek. Oroszló nevét 1402-ben említették először az oklevelek Zorozlow alakban írva, később Zoroslo és Zorozlo írásmóddal.'),
    ('Orosztony', 'A Kis-Balaton térségét a Principális-csatorna völgyével összekapcsoló, a 7522-es és 7527-es számú utakat összekötő 7525-ös út mentén fekszik. Az út Felsőorosztony településrészen halad át, Alsóorosztony településrész az útból dél felé kiágazó, 75 125-ös számú mellékúton érhető el. A legkorábbi adatok az Árpád-korból maradtak ránk, amikor Orosztony egy része a Buzád-Hahót nemzetség birtoka volt.'),
    ('Ortaháza', 'Lentitől mintegy 15 kilométerre keletre fekszik, a Bak-Páka között húzódó 7543-as út mentén. Központjában ágazik ki a 7548-as út Zebecke és Kissziget határvidéke felé. Az Orta- előtag személynév, jelentése: irtó, erdőirtó. Az utótag a birtokos személyjellel ellátott ház jelentése pedig lakóhely, otthon. Nevét 1389-ben említette először oklevél Artaháza, majd Artalháza alakban helyezkedik el.'),
    ('Osli', 'Magyarország északnyugati részén, a Hanság déli peremén helyezkedik el. Északi, nyugati és délnyugati irányból Kapuvárhoz, északkelet felől Csornához, kelet felől pedig Rábatamásihoz tartozó külterületek határolják. Két további szomszédja van még: délkelet felől Szárföld, dél felől pedig Veszkény. A legközelebbi város Kapuvár, mintegy 8 kilométerre délnyugatra helyezkedik el.'),
    ('Ostffyasszonyfa', 'A Kemenesháton, a Rába völgyében, a vele párhuzamosan futó Lánka-patak mellett, a Cser északnyugati pereménél fekszik. Határa, a fekvésének köszönhetően két eltérő arculatú részre tagolódik. A Rába és a Lánka-patak közötti, többnyire lapályos ártéren leginkább rétek, legelők és szántóföldek találhatók. A Rábát sűrű erdősáv, és árvízvédelmi töltések kísérik.'),
    ('Ostoros', 'Északi határában egy mesterséges tó, az Ostorosi-víztározó található. A további szomszédos települések: északkelet felől Szomolya, délkelet felől Novaj, dél felől Szihalom, délnyugat felől Maklár és Nagytálya, nyugat felől pedig Andornaktálya. Csak közúton érhető el, Eger vagy Novaj felől, a 2503-as úton. A település nevét az Ostoros-patak vizéről nyerte, melyet Anonymus Gesta Hungaroruma már megemlített (ekkor még Istoros névalakban): „… Árpád vezér és övéi innen továbbmenve eljutottak az Eger vizéig.'),
    ('Oszkó', 'Felsőoszkó és Alsóoszkó egyesítésével jött létre 1941-ben. Vasvár kelet-délkeleti szomszédságában fekszik, a várostól 7 kilométer távolságra, a Kemenesháton. A 13. században a Dunántúlt keresztülszelő katonai útvonal hegyháti szakasza fontos szerepet töltött be, amely egészen az Őrségen és Tótságon keresztül a Murához tartott.'),
    ('Oszlár', 'Miskolctól mintegy 46 kilométerre délre fekszik. A környező települések: Hejőkürt (3 kilométerre délnyugatra), Nemesbikk (4 kilométerre északnyugatra), Tiszapalkonya (5 kilométerre északkeletre), a legközelebbi város pedig Tiszaújváros, (9 kilométerre észak-északkeleti irányban). A települést a 13. század végén említik először. Neve török nyelven jászt jelent.'),
    ('Osztopán', 'Nevét 1229-ben említette először oklevél mint a székesfehérvári káptalan birtokát. 1317-ben a Gutkeled nemzetségbeli Amadé fia, I. Miklós, a Felső-Lendvai család őse nyerte adományként Károly Róbert királytól. 1332-1337 között a pápai tizedjegyzék is említi egyházas helyként. 1417-ben az Osztopáni Perneszi család szerzett egyes részeire új adományt Zsigmond királytól. 1478-ban osztopáni Perneszy Pál fiai, Zsigmond és Imre, 1512-ben Perneszi Imre fiai: Miklós, Pál és István volt Osztopán birtokosai.'),
    ('Ozmánbük', 'A településen polgárőrség működik. Különálló településrésze Márkus, a központjától mintegy másfél kilométerre északkeletre helyezkedik el. A közvetlenül határos települések: északkelet felől Halastó, délkelet felől Börönd (Hagyárosbörönd része), délnyugat felől Vaspör, északnyugat felől pedig Hegyháthodász. A legközelebbi városok Zalalövő légvonalban 11, közúton 14 kilométerre délnyugatra, és Körmend, majdnem azonos távolságokra észak-északnyugati irányban helyezkedik el.'),
    ('Ozora', 'A Sió völgyében, páratlan szépségű tolnai dombvidéken bújik meg. A területét friss vizű patakok szelik át. A település felé közeledve már messziről szemünkbe tűnik a szőlőhegyek által körülölelt páros domb, melyek egyikén a templom, a másikon a várkastély látható. Valamikor a várárkon átívelő híd kötötte össze őket. A várdombot és a templomot ma is a Sió és a Cinca-patak vize veszi körül, amelyen hangulatos hidacskák vezetnek át a piactérre.'),
    ('Pacsa', 'A Zalai-dombságban, ezen belül a Zalaapáti-hát területén fekszik, a Principális-csatorna völgyének keleti peremén. Különálló településrésze Pacsatüttös, a központjától mintegy másfél kilométerre délkeletre helyezkedik el. A közvetlenül határos települések: észak felől Zalaigrice és Szentpéterúr, kelet felől Zalaapáti, délkelet felől Zalaszentmárton, dél felől Dióskál és Felsőrajk, nyugat felől pedig Zalaszentmihály.'),
    ('Padár', 'A Zalai-dombságban, azon belül is a Zalaapáti-hát területén fekszik, a megyeszékhely Zalaegerszegtől keletre. A közvetlenül határos települések: észak felől Bezeréd, északkelet felől Zalakoppány (Zalaszentgrót része) és Kallósd, kelet felől Almásháza, délnyugat felől Nagykapornak, nyugat felől pedig Orbányosfa. Csak nagyon kevés híja van, hogy nem határos délkelet felől még Tilajjal (Tilajújheggyel) is.'),
    ('Pakod', 'A község a Zalai borvidékhez tartozó Csáfordi-hegy nyugati lábánál, a Zala folyó két partján, Dötktól északra, Zalabértől délnyugatra terül el. Központján a Sümeget Zalaegerszeggel összekötő 7328-as út halad végig, ebből a településen ágazik ki a csak Dötkre vezető 73 205-ös út. Pakod Árpád-kori település. Neve már 1211-ben említve volt egy a pannonhalmi Szent Benedek rend történetéről írott könyvben Pocud (Pokod) néven. 1230-ban pedig egy oklevél írt Pakodról, illetve a Pakodtól északkeletre fekvő Barabás nevű településről.'),
    ('Paks', 'Sváb népszokásairól és kiváló halászlevéről messze földön híres. Kisváros létére igen sok országos rendezvénynek ad otthont, mint például a Gastroblues Fesztivál, a Paksi Harmonika Fesztivál, valamint a Szüreti felvonulás és mulatság. Országos ismertségét legfőképp atomerőművének köszönheti, amely Magyarország egyetlen energiahálózatra kapcsolt atomerőműve.'),
    ('Palkonya', 'A Villányi-hegység északkeleti oldalán fekszik, Villánytól mintegy 4 kilométerre északnyugatra. A szomszédos települések: észak felől Kiskassa, északkelet felől Ivánbattyán, délkelet felől Villánykövesd, dél felől Kisharsány, délnyugat felől Nagytótfalu, nyugat felől Vokány, északnyugat felől pedig Újpetre helyezkedik el. Palkonya nevét az oklevelek 1296-ban említették először, Polkona, Polkuna alakban írva.'),
    ('Palotabozsok', 'Mohácstól északra, mintegy 15 kilométerre található, a Baranyai-dombság keleti részén. A szomszédos települések: észak felől Véménd, kelet felől Dunaszekcső, dél felől Somberek, délnyugat felől Görcsönydoboka, nyugat felől pedig Szebény. A településnek a Pécs–Pécsvárad–Bátaszék-vasútvonalon vasútállomása is volt, de 1997-től Pécstől már csak Pécsváradig mentek a vonatok, majd 2003-ban a Palotabozsok és Bátaszék közötti szakaszon is megszűnt a személyforgalom.'),
    ('Palotás', 'A Cserháttól délre, a hegység törmelékkúpjának észak-északnyugat–dél-délkelet irányú völgyekkel szabdalt alacsony, lapos hátú dombvidékén épült. Határának egy része már a Zagyva vízgyűjtő területe. A főváros közigazgatási határától és a megyeszékhely Salgótarjántól egyaránt 50, Pásztótól, Hatvantól és Aszódtól 20–20 kilométerre fekszik. Az északi szomszédjában fekvő Kisbágyon felől a 2136-os úton érhető el.'),
    ('Paloznak', 'Paloznak a Balaton északi partján helyezkedik el. Első ismert, írásos említése a veszprémvölgyi monostor adománylevelében található a 970-es évekből, de területe a régészeti leletekből ítélve legalább 5000 éve lakott lehet. Önkormányzata a Balaton-felvidék hagyományos faluképének megőrzéséért 1998-ban Hild-díjat kapott. A mai település életében meghatározó tevékenységek a borászat és a turizmus kiszolgálása.'),
    ('Palé', 'Pécstől közel 35 kilométerre északnyugatra fekszik, Sásd és Baranyajenő közt, a Gödrei-víz völgyében. Palé nevét 1327-ben említették először az oklevelek, Pauli néven helyezkedik el. A település a középkorban a somogyi apátság birtokai közé tartozott. A hadiút mellett fekvő falu a török időkben a háborús viszontagságok miatt elnéptelenedett. A második világháború után a település többségét alkotó német lakosságot kitelepítették a faluból helyezkedik el.'),
    ('Pamlény', 'Miskolctól 65 kilométerre északkeletre fekszik. Neve szláv eredetű személynévből származhat, amely mögött a pomnyeny ’akire emlékeznek’ jelentésű szó rejlik. A név a magyar kiejtésnek megfelelően alakult át. A szláv po mlin ’malom menti’ eredeztetése tévedés. Első említése 1299 körüli évekből származik. Ez azonban csak rövid ideig tartó birtoklást jelentett, mert újra a Tekes rokonok kezén volt a falu. 1340-ban a rokonság ágai megosztoztak birtokaikon, ennek során Pamlény a tornai ághoz, azaz a Tornai családhoz tartozó László fia Jánosé lett.'),
    ('Pamuk', 'Árpád-kori település, nevét már 1212 körül III. Ince pápa levelében is említették. 1428-ban Banyk alakban említették és Osztopáni Bálint és fiai itteni birtokait a Perneszi család nyerte adományul. 1478-ban is Osztopáni Perneszi Pál fiainak, Zsigmondnak és Imrének, voltak itt birtokai. A mai Pamuk helyén feltételezte kutatásai során Erdélyi László Gyrki falut, melyről Incze pápa 1212-1215. évi levelei emlékeztek meg először, és ahol Albeus mester 1237-1240. évi összeírása szerint a szentmártoni apátságnak voltak birtokai.'),
    ('Pannonhalma', 'Kedvelt turisztikai célpont, elsősorban a Pannonhalmi Bencés Főapátságról és annak épületeiről ismert, amelyek 1996 óta az UNESCO Világörökség részét képezik. Győrtől 19 kilométer-re dél-délkeleti irányban, Sokorói-dombságban helyezkedik el. A pannonhalmi várból szép kilátás nyílik Bábolna és Budapest irányában is. (A dombtetőről lehet látni a bábolnai „szélkerekeket” is, de tiszta időben akár az esztergomi bazilika sziluettje is kirajzolóik.) A vár túloldaláról pedig egészen Győrig el lehet látni.'),
    ('Panyola', 'A Szatmári-síkságon, a Tisza-Szamos-közben fekszik, közvetlenül a Szamos folyó jobb partján, a torkolattól mintegy 12 kilométerre délre. Mellette folyik el a Túr szabályozott vízhozammal és 3 kilométerre északra a Tisza. E három folyó felszínalakító munkája eredményeként alakult ki az egyhangúnak nem nevezhető táj. A folyók mellett az ásványi anyagokban gazdag hordalék-lerakódások következtében jó minőségű termőtalajok, míg a mélyebb fekvésű részekben mocsarak keletkeztek.'),
    ('Pap', 'A környező egyéb települések közül Nyírlövő 5, Jéke 8,5, Kékcse 12,5, Lövőpetri 9, Tornyospálca 16 kilométer távolságra található. Pap település és környéke már a bronzkorban is lakott hely volt, amit az itt talált leletek nagy száma bizonyít. Nevét az oklevelekben már IV. László király korában (1272 és 1290 körül) is említették Terra Pop néven helyezkedik el.'),
    ('Papkeszi', 'Berhidától 5 kilométerre fekszik. Papkeszi határában az 1950-60-as években talált őskori és ókori leletanyagok tanúsága szerint igen korai település. Papkeszi nevét úgy kapta, hogy a hon­foglalás után a Keszi törzshöz tartozók telepedtek itt meg, róluk nyerte a helységnév „keszi” utótagját, a „Pap” előtag első birtokosára, a veszprémi káptalanra utal.'),
    ('Papos', 'A megye középső részének keleti felében fekszik. A környező fontosabb települések közül Mátészalka 7, Vaja 11, Nyírparasznya pedig 7 kilométer távolságra található. A közvetlen szomszédos települések: észak felől Nyírparasznya, kelet felől Ópályi, délnyugat felől Mátészalka, dél felől Jármi, nyugat felől Őr, nyugat-északnyugat felől pedig Vaja. Csak közúton érhető el, Jármi vagy Nyírparasznya felől, mindkét irányból a 4106-os úton.'),
    ('Parasznya', 'A további szomszédos települések: észak felől Kondó, északkelet felől Radostyán, nyugat felől pedig Varbó. A legközelebbi város Sajószentpéter, amely körülbelül nyolc kilométerre van. Határszélét délnyugaton érinti még a Dédestapolcsányra vezető 2513-as út is. A települést a 12. században említik először, de már a 11. században is állt. 1286-ban már itt lakó várjobbágyokból vált nemesekről történik említés, és Peresnie, majd Perezne elnevezést találhatunk.'),
    ('Parád', 'Hozzá tartozik a lakóterület keleti részét alkotó Parádfürdő és a tőle földrajzilag különálló Parádóhuta. Hagyományosan a palócok egyik központjának tartják. A Mátra északi oldalán, a Parád–Recski-medencében, a Parádi-Tarna völgyében helyezkedik el. Parádfürdő keletre, Parádóhuta délre található a központtól. Míg Parádfürdő egy teljesen összefüggő települést képét mutatja Paráddal, addig Parádóhuta mintegy 2 kilométerre található tőle.'),
    ('Parádsasvár', 'Gyönyörű földrajzi, természeti környezetben fekszik a Mátra északi oldalán. Galyatetőtől keletre, a parádi katlan felső végében elnyúló, 400 méter magas fennsíkon helyezkedik el, ahonnan szemet gyönyörködtető kilátás nyílik a környező hegycsúcsokra, a Mogyorós-oromra, a Nagy-Lipótra, a Galyatetőre, a Bagolykőre, a Csór-hegyre, a Vadak-ormára, a Hármas-tetőre és a Vár-hegyekre.'),
    ('Paszab', 'A megyeszékhelytől, Nyíregyházától mintegy 25 kilométerre északra helyezkedik el. A közvetlen szomszédos települések: kelet felől Ibrány, dél felől Buj, nyugat felől pedig Tiszabercel. Északi irányból, a Tisza túlpartja felől is Tiszabercelhez tartozó külterületek határolják. Az Országos Levéltár egyik oklevelében nevét már 1424-ben Pazab alakban írták.'),
    ('Pat', 'Pat központjától alig 300 méterre található a megyehatár. Először 1332-ben említik a települést, akkori Potoch alakban, a pápai tizedjegyzékben helyezkedik el. A 18. század közepén elzavart szlovén (vend) evangélikus családok települtek le a faluban helyezkedik el.'),
    ('Patak', 'A Nógrádi-medencében a Derék-patak mellett fekszik. Talaja középkötött, homokos agyagtalaj. Erdői már a középkorban áldozatul estek a szántóföldet és rétet teremtő irtásnak. József uralkodása alatt, 1785-ben így írtak az erdejéről: magas törzsű tölgy, fenyőszálerdő cserjékkel vegyesen található. Átlagos évi középhőmérséklete 10 Celsius-fok. A közvetlenül határos települések: északkelet felől Dejtár, délkelet felől Érsekvadkert, dél felől Horpács, délnyugat felől Nagyoroszi, északnyugat felől pedig Ipolyvece.'),
    ('Patalom', 'A megyeszékhelytől, Kaposvártól 20 kilométerre északkeletre elhelyezkedő kisközség. A Külső-Somogyi dombság egyik szép völgyében található, környéke nagyon gazdag erdőkben. Központja a Kaposvár-Szántód közti 6505-ös útról leágazva, egy mellékúton érhető el. A falu neve 1275-ben fordult elő először hivatalos dokumentumban, mégpedig Pothlon alakban írva.'),
    ('Patapoklosi', 'A Zselic lábánál, Szigetvár északnyugati szomszédjában fekszik. Patapoklosi 1950. szeptember 6-án jött létre az egykori mezőváros Pata és a Keleti-Gyöngyös túlpartján fekvő Poklosi egyesítésével. A török időkben mindkét település, a mellettük fekvő Hosszúfaluval együtt elnéptelenedett a környéken folyó harcok miatt. A falu később magyar lakossággal települt újra helyezkedik el.'),
    ('Patca', 'Patca Árpád-kori település. Nevét 1252-ben Poczyta alakban írva említette először oklevél. 1374-ben Pochcha, 1394-ben Pachya írásmóddal szerepelt az oklevelekben. 1456-ban Ipoltfalvi Miklós nyerte új adományul. Az 1550. évi adólajstromban Szent-Benedekkel együtt fordult elő. 1598–99. évi adólajstromban két Padcza nevű helységet találunk.'),
    ('Patosfa', 'Közúti távolsága Barcstól 31, Kaposvártól 38, Szigetvártól 15 kilométer. Földrajzilag a Zselic és a dél-somogyi homokvidék határán fekszik. Nyarai viszonylag csapadékosak és hűvösek, telei enyhébbek az átlagnál helyezkedik el. A Patosfa körüli északi dombokon leginkább gyertyános–tölgyes erdők találhatók, a déli, síkabb részen inkább cseres–tölgyes, néhol hárserdők fordulnak elő.'),
    ('Patvarc', 'Területe északnyugaton Balassagyarmat, keleten Őrhalom, délen Szűgy határával érintkezik, északon pedig Szlovákiával határos, ahol a határvonalat az Ipoly folyása képezi. A legközelebbi település a határ túloldalán az Erdőmeg (Záhorce) községhez tartozó Erdőszelestény (Seľešťany). A honfoglalás idején a szlávok az Ipoly völgyében laktak a legsűrűbben.[forrás?] A község nevét a szlávok adták, mely arra utal, hogy a település a honfoglalás idején Patvarc néven ismert volt.'),
    ('Pecöl', 'Sárvártól 10 kilométerre délnyugatra fekszik a Gyöngyös-patak mellett, a Gyöngyös, a Kozár-Borzó-, és a Boláta-patakok találkozásánál helyezkedik el. Főutcája a 8443-as út, közúton csak azon érhető el a megyeszékhely Szombathely és Ikervár felől is. A település első okleveles említése 1329-ből származik Pecul alakban helyezkedik el. Ennél sokkal régebbi lehet, minden bizonnyal arról a hasonló nevű főemberről kapta nevét, akit a krónikák az 1040-es években említenek.'),
    ('Pellérd', 'Pécs délnyugati szomszédságában, a város központjától körülbelül 7 kilométerre, a Pécsi-síkságon helyezkedik el. A további szomszédos települések: kelet felől Keszü, dél felől Gyód, Regenye és Görcsöny, délnyugat felől Aranyosgadány, nyugat felől Bicsérd, északnyugat felől pedig Cserkút. Emellett elérhető a település Pécs Megyer városrésze felől is, az 5816-os úton, amely csökkenti a falu átmenő forgalmát.'),
    ('Penc', 'A település Váctól mintegy 9 kilométerre keletre fekszik, a Cserhát hegység déli lábainál, közel a Naszályhoz. A szomszédos települések: észak felől Keszeg, északkelet felől Nézsa, kelet felől Csővár, délkelet felől Püspökhatvan és Püspökszilágy, délnyugat felől Rád, nyugat felől pedig Kosd. A térség helyközi autóbuszjáratai közül a 312, 334, 335, 336, 337, 338 számú járatok érintik.'),
    ('Penyige', 'E város központjától 5, Kisartól 10, Csengersimától 24, Mátészalkától 23 kilométer távolságra található. A szomszédos települések: észak felől Nagyar, északkelet felől Kömörő, kelet felől Mánd, délkelet felől Nagyszekeres, dél-délkelet felől Zsarolyán, dél felől Cégénydányád, nyugat felől pedig Fehérgyarmat. Penyige nevének első írásos említése 1181-ből ismert. 1332-ből a neve Penge formában maradt meg, 1435-ben Penige alakban jegyezték fel.'),
    ('Penészlek', 'A Nyírség délkeleti csücskében fekszik, a megyeszékhely Nyíregyházától mintegy 67 kilométer távolságra, közvetlenül a román határ mellett. A szomszédos települések a határ magyar oldalán: északkelet felől Ömböly, észak felől Nyírbéltek, délnyugat felől pedig Fülöp. Határszéle délen és keleten, összesen mintegy 9 kilométer hosszan egybeesik az államhatárral.'),
    ('Perbál', 'A 2100–2200 fős, pezsgő életű települést magával ragadó táj veszi körül, az összetartó közösséget több civil szervezet és vállalkozás is színesíti. Az alapfokú oktatástól kezdve sok minden megtalálható a településen, ami egy fejlődő község számára fontos. Így például orvosi rendelő, posta, gyógyszertár, szórakozóhelyek és üzletek sora szolgálja ki a helyiek igényeit.'),
    ('Pere', 'A Hernád bal partján fekszik, Hernádbűd és Felsődobsza között, a megyeszékhely Miskolctól 38 kilométerre északkeletre. A közösségi közlekedés járatai közül a Volánbusz 3816-os buszjáratával közelíthető meg. A Hernád partján fekvő települést 1282-ben említik először, mint a Bárca-nemzetség birtokát. A törökök sokáig nem foglalták el, mert a Hernád természetes védvonalat képezett, de 1640-ben török hódoltság alá került a falu.'),
    ('Perecse', 'Közigazgatási határa mintegy 9 kilométer hosszban egybeesik az államhatárral. A környező települések a határ magyar oldalán: északkelet felől Kány (légvonalban 3, közúton 10 kilométer), délkelet felől Büttös (6 kilométer), dél felől Krasznokvajda (5 kilométer), nyugat felől pedig Keresztéte (légvonalban 3,5, közúton 11 kilométer). Külterületei messze elnyúlnak a falutól északnyugati irányban, ennek köszönhetően határos még Pamlénnyal, Viszlóval és Tornaszentjakabbal is.'),
    ('Pereked', 'Szomszédos községek: Északról Martonfa, északkeletről Szilágy, délkeletről Berkesd, délről Ellend nyugatról Romonya. Pereked nevét 1015-ben említették először az oklevelek Perecud alakban írva. A pécsváradi apátság alapító levele szerint I. István király 1015-ben adta a monostornak. A 14. században is az apátság birtokának írták. 1333-ban papja 20, 1335-ben 10 báni pápai tizedet fizetett.'),
    ('Perenye', 'Szombathelytől 7 kilométerre északnyugatra fekszik, a Kőszeghegyalja peremén. A szomszéd települések: észak felől Gyöngyösfalu, kelet felől Gencsapáti, délnyugat felől Bucsu, nyugat felől Bozsok, északnyugat felől pedig Kőszegszerdahely és Kőszegdoroszló. Neve valószínűleg a szláv Prvine helynévből származik, eredete ismeretlen helyezkedik el. A falu területe a régészeti leletek tanúsága szerint már a bronzkorban lakott volt.'),
    ('Peresznye', 'A szomszédos települések a határ magyar oldalán: északkelet felől Répcevis, kelet felől Szakony, délkelet felől Csepreg, dél felől Kiszsidány, délnyugat felől pedig Horvátzsidány és Ólmod. Ausztria felől a két legközelebbi település Répcesarud (Frankenau) és Répcemicske (Strebersdorf). A jelenleg 36%-ban horvát nemzetiségűek lakta település okleveles említése 1195 körülről származik.'),
    ('Pereszteg', 'A mai település a történelmi Pereszteg falu és Sopronszécsény egyesítésével jött létre, 1951-ben. A Kisalföld nyugati szélén fekszik, közvetlenül az osztrák határ mellett. Felszíni vizeit az Ikva patak gyűjti össze. A szomszédos települések a határ magyar oldalán: észak felől Hidegség, északkelet felől Fertőhomok, kelet felől Pinnye, délkelet felől Nagylózs, dél felől Sopronkövesd, nyugat felől pedig Nagycenk.'),
    ('Perkupa', 'Miskolctól 49 kilométerre északra fekszik, a Bódva völgyében. A közvetlenül határos települések: észak felől Szögliget, északkelet felől Bódvarákó és Martonyi, délkelet felől Szalonna, dél felől Szendrő, nyugat felől Varbóc, északnyugat felől pedig Szin. Először 1340-ben említik, Precopa alakban helyezkedik el. Neve valószínűleg szláv eredetű.'),
    ('Perkáta', 'A Mezőföld keleti peremének völgyekkel szabdalt lösz fennsíkján helyezkedik el. A közvetlenül határos települések: észak felől Pusztaszabolcs, északkelet felől Adony, délkelet felől Rácalmás, dél felől Nagyvenyim és Mezőfalva, délnyugat felől Hantos, nyugat felől Sárosd, északnyugat felől pedig Szabadegyháza. Kelet felől a legközelebbi település Kulcs, délkelet felől pedig közel van hozzá a térség legnagyobb városa, Dunaújváros is, de közigazgatási területe utóbbiak egyikével sem érintkezik.'),
    ('Perőcsény', 'A Börzsöny északnyugati lábánál elhelyezkedő völgykatlanban fekszik. Területének domborzata változatos. A szláv eredetű Prečani szóból származik, melynek magyar jelentése túlsó parton lakók. A 13. század végén a vidék mint az ipolyviski vár tartozéka a gróf Cseszneky család birtoka volt. Elsőként egy 14. század végéről származó, 1398-ban átírt oklevél említi Pereuchean néven, de a középkori oklevelek még Preuchan és Preuchen néven is említik. 1419-ben vásárhely. 1592-ben már református gyülekezete is volt, lelkipásztoruk ekkor Corvin Éliás.'),
    ('Peterd', 'A Drávaszög legészakibb falva. Siklóstól északkeletre, Pécsdevecser északnyugati szomszédjában fekszik. A falu és környéke ősidők óta lakott hely volt, területén bronzkori, és római korból származó leletek (pénzérme, tégla) kerültek felszínre. Az Árpád-korban már lakott települést az oklevelek 1276-ban említették először Petherd, Peturd néven a feltételezések szerint.'),
    ('Pethőhenye', 'Az egymást sűrűn követő kanyarvételeitől eltekintve itt nagyjából nyugat-keleti irányt követő Zala jobb (déli) partján fekszik, a Szévíz-patak völgyének északi részén (a patak a keleti határszéle közelében torkollik bele a Zalába). A legközelebbi város a megyeszékhely, Zalaegerszeg, melynek északkeleti szomszédságában helyezkedik el. A további, közvetlenül határos települések: észak felől Alibánfa, kelet felől Nemesapáti, délkelet felől Alsónemesapáti, északnyugat felől pedig Zalaszentiván helyezkedik el.'),
    ('Petneháza', 'Baktalórántházától 7 kilométerre északra, Kisvárdától 21 kilométerre délre helyezkedik el. A közvetlen szomszédos települések: észak felől Nyírkarász, délkelet felől Rohod, dél felől Nyírjákó, nyugat felől Laskod, északnyugat felől pedig Nyírtass. Csak közúton érhető el, Nyírkarász vagy Nyírjákó érintésével, a 4105-ös úton. Alapítója a 14. század elején élt Terecse fia Péter vagy Petene, a Petneháziak őse.'),
    ('Petrikeresztúr', 'A település 179 lakásában 362 ember él, ami alapján a faluban lakóházanként 2,02 fő él. A 877 hektáros területen fekvő Petrikeresztúron a népsűrűség 43,79 fő/km². A falu két, egymástól jól elkülöníthető részből áll, melyet elválaszt a Cserta folyó és közvetlenül ennek jobb és bal partján rézsűk, mezőgazdasági telkek találhatóak. Az először 1260-ban feljegyzett település fénykorát a huszadik század derekán élte, majd lassanként elérte az aprófalvakra jellemző elöregedés és elvándorlás.'),
    ('Petrivente', 'A Zalai-dombság délnyugati részén helyezkedik el, az Egerszeg–Letenyei-dombság területén, légvonalban alig 7 kilométerre a horvát határtól. A közvetlenül határos települések: északkelet felől Rigyác, kelet felől Szepetnek, dél felől Semjénháza, délnyugat felől Tótszentmárton, északnyugat felől pedig Becsehely. A legközelebbi városok: keleti irányból Nagykanizsa, nyugati irányból pedig Letenye.'),
    ('Pettend', 'Szigetvár vonzáskörzetében helyezkedik el, a város központjától mintegy 13-14 kilométerre délnyugati irányban, a Nyugati-Gyöngyös patak mellett. A szomszédos települések: észak felől Nemeske, északkelet felől Kistamási, dél felől Gyöngyösmellék, délnyugat felől Szörény és Zádor, északnyugat felől pedig Kisdobsza és Nagydobsza. Zsáktelepülés, csak közúton közelíthető meg, a 6-os főútról Nemeske-Görösgalnál letérve, Nemeske és Kistamási központján keresztül, az 58 109-es számú mellékúton helyezkedik el.'),
    ('Petőfibánya', 'A Mátraalján, Hatvantól 16 kilométer-re északra, a Zagyva folyó völgyében található. Szomszédos települések: észak felől Apc, északkelet felől Rózsaszentmárton, kelet felől Nagyréde, délkelet felől Ecséd, dél felől Hatvan, délnyugat és nyugat felől Lőrinci (Selyp), északnyugat felől pedig Zagyvaszántó. A település eredeti neve Pernyepuszta volt. 1950-ben kapta a Petőfi bányatelep nevet.'),
    ('Petőháza', 'Neve már tulajdonnévként 1390-ben szerepel oklevélben helyezkedik el. Akkor említik először a Petőházi családot. Községnévként a Petőházi családnév 1437-ben bukkan fel. Termőtalaja közepes minőségű. A 17 kilométerre lévő pomogyi határátkelőtől kerékpáron is elérhető. A kőkorszaktól fogva lakott hely, ezen a területen már Kr. e. 3500–2500 körül éltek emberek.'),
    ('Petőmihályfa', 'Vasvártól 9 kilométerre délre, Zalaegerszegtől 19 kilométerre északra helyezkedik el, mindkét várossal közvetlen autóbuszjáratok kötik össze. 1308-ban Myhalfolua néven említik először. Nevét egykori, Mihály nevű birtokosáról kapta. 1391-ben Poss. Mihalfelde, 1399-ben Poss. Mihalyfalua néven szerepel az írott forrásokban. A Hidvégieké és gersei Petőké volt.'),
    ('Piliny', 'Szécsénytől mintegy 10 kilométerre északkeletre fekszik. A Novohrad-Nógrád UNESCO Globális Geopark települése. A közvetlenül határos települések: észak felől Litke, északkelet felől Mihálygerge, Egyházasgerge és Karancskeszi, kelet felől Szalmatercs, délnyugat felől Endrefalva, nyugat felől pedig Szécsényfelfalu. Északnyugati irányban csak kevés híja van annak, hogy nem határos még Nógrádszakállal is.'),
    ('Pilis', 'A Gödöllői-dombság nyúlványán, a Monor–Irsai-dombság és a Duna–Tisza közi homokhátság találkozásánál helyezkedik el. Határában található a Gerje patak forrásvidéke. Szomszédai közül a tőle északra elhelyezkedő Kávával a 3123-as út, Nyáregyházával a 4606-os út köti össze. A jelenleg ismert, 1326-ban keltezett első írásos emlék a településsel kapcsolatban – egy öröklésről szóló okirat – már Pilis…'),
    ('Pilisborosjenő', 'A Nagy-Kevély lábánál megbújó zsáktelepülés belterülete 124 hektár, külterülete mintegy 800 hektár. Az ófalu a fővárostól, Budapesttől északnyugatra, a „0” kilométerkőtől 13 kilométerre, erdős hegyekkel övezve, a medence mélyén csordogáló, hajdan bővizű Borosjenői-patak két oldalán települt. A közelmúltban épült kertes házaival felkúszott az Kevélyek erdősávjáig.'),
    ('Piliscsaba', 'A megye északnyugati részén, Budapesttől 25 kilométer-re, a Pilis, a Gerecse és a Budai-hegység által közrezárt Dorogi-medence délkeleti részén fekszik. A 210 méter magasan megtelepült várost északkeleten a Pilis hegység 400 métert meghaladó hegyei (Kopasz-hegy 448 méter), délkeleten a Budai-hegység hasonló magasságú hegyei (Kis-Szénás 431 méter, Csaba-hegy, Sós-hegy) délnyugaton a Gerecse keleti részét képező Zsámbék-Bajnai…'),
    ('Piliscsév', 'A községet szlovák nemzetiség is lakja, amely a lakosság 45,3%-át teszi ki. A település a Dorogi-medence keleti csücskében, a Pilis hegység nyugati lábánál, három oldalról hegyekkel körülvett völgyben fekszik. A falun áthalad az Országos Kéktúra útvonala. Gyönyörű kirándulóhelyek övezik. Távolsága Dorogtól 10,4 kilométer, Esztergomtól 18,6 kilométer, Budapesttől 25 kilométer országúton helyezkedik el.'),
    ('Pilisjászfalu', 'A megye északnyugati szélén fekszik, Budapest központjától 30 kilométerre északnyugatra. Természetföldrajzilag a Pilis és a Budai-hegység határán, s a Dorogi-medence délkeleti szélén helyezkedik el, a Kenyérmezői-patak völgyében. Határain belül az alföldi és a középhegységi felszíni formák egyaránt fellelhetők. Az emelkedő dolomitrétegekkel váltakozó, úgynevezett dachsteini mészkőrögök változatossá teszik a tájat.'),
    ('Pilismarót', 'Dömös 3,5, Visegrád 10, Dunabogdány 16,5, Esztergom 13, Dorog 20,5, Tát 21,5, Nyergesújfalu 28,5 kilométer távolságra található. A település már ősidők óta lakott hely volt, amit az itt talált sok régészeti lelet is tanúsít. A község helyén állt az egykori római település Castra Ad Herculem. Marót nevét 1138-ban említik először II. Béla király oklevelében, ekkor Marouth alakban írták.'),
    ('Pilisszentiván', 'A mai település alapítási szerződését 1724. április 24-én írta alá a területet akkor birtokló budai ágostonosok vikáriusa és öt, a mai Németország területéről hazánkba érkezett családfő. A településen mindig is jelentős volt a német nemzetiségűek számaránya, és ma is az, köszönhetően többek között annak is, hogy a második világháború után itt nem került sor kitelepítésre.'),
    ('Pilisszentkereszt', 'A község része Dobogókő. Lakóinak száma 2171 fő, ebből 415 szlovák és 46 fő német (a 2022-es népszámlálás szerint). Népszerű kirándulóhely, illetve kirándulások kiindulási pontja. Budapest északi határától 26 kilométer-re, a Dunazug-hegyvidék, azon belül a Pilis és a Visegrádi-hegység határán, a a Dera-patak és a Kanyargós-patak völgyében helyezkedik el a Dobogó-kő és a Pilis csúcsai alatt.'),
    ('Pilisszentlászló', 'Nevét I. (Szent) László királyról kapta. A kis hegyközi medencét minden oldalról miocén korú andezitvulkánok veszik körül. A jelentősebb magaslatok: Szent László-hegy (590 méter), Rózsa-hegy (549 méter), Öreg Pap-hegy (567 méter), Tüskés-hegy (510 méter). Pilisszentlászlóról könnyen elérhető a Visegrádi-hegység összes nevezetessége (Visegrád, Dobogó-kő, Rám-szakadék, Vörös-kő, Prédikáló-szék) Fő patakja az Apátkúti-patak, de a faluban ered a Lepence-patak egyik ága is.'),
    ('Pilisszántó', 'A község Pilisvörösvár és Pilisszentkereszt között fekszik a Pilis (757 méter) és a Hosszú-hegy (485 méter), illetve délnyugat felől a Zajnát-hegyek határolta völgyben, Budapesttől és Esztergomtól egyaránt körülbelül 25 kilométer távolságra. Lakói rálátnak a főváros esti fényeire, viszonzásként e látványért megajándékozzák a főváros lakóit egy tájképpel, szemet gyönyörködtető erdők borította hegyekkel.'),
    ('Pilisvörösvár', 'Pilisvörösvár a Pilisi- vagy Pilisvörösvári-medence nyugati felében terül el, az Aranyhegyi-patak és mellékágai vízgyűjtő területét alkotó hosszanti völgyben futó, fontos közlekedési útvonal mentén létesült.'),
    ('Pincehely', 'Három település (Görbő, Gyánt, Pincehely) összeolvadásából jött létre. Német nevének jelentése Kákasisak, Sástorony. A megye északi részén fekszik, a Kapos mentén. Központja a folyó bal parti oldalán helyezkedik el, lakott területének a jóval kisebb, jobb parti része a Görbő nevet viseli. Területe 5016 hektár, melyből a központi belterület 326 hektár.'),
    ('Pinkamindszent', 'Körmend és az Ausztriához tartozó Németújvár között úgyszólván félúton helyezkedik el, közvetlenül az osztrák határ mellett. Körmendtől 13, Németújvártól 12 kilométerre fekszik. Határában folyik a Pinka folyó. A határ magyar oldalán egyetlen települési szomszédja van: kelet felől Vasalja. Emellett északkelet felől egy rövid, kevesebb mint 400 méteres szakaszon érintkezik még Szentpéterfa határszélével is, de közlekedési kapcsolat nincs a két község között.'),
    ('Pinnye', 'Sopron és Kapuvár között, a 85-ös főúttól másfél kilométerre délre fekszik, az Ikva-patak partján. A rómaiak korában már lakott hely volt. Első írásos említése 1324-ben történt. A középkorban az Oslik birtokolták, majd ebből származott Pinnyei Antal-féle família, és leányágon a Zalay- és Niczky család.'),
    ('Piricse', 'A további szomszédos települések: északkelet felől Nyírpilis, kelet felől Bátorliget, délkelet felől Ömböly, dél felől Nyírbéltek, délnyugat felől Encsencs, északnyugat felől pedig Nyírbogát. A környező fontosabb települések közül Mátészalka 28, Vállaj 21, Bátorliget 11, Nyírpilis pedig 3,5 kilométer távolságra található. Csak közúton érhető el, a Nyírbátortól Nyírábrányig húzódó 4906-os úton.'),
    ('Pirtó', 'A Kiskunság aránylag magasabb fekvésű részén helyezkedik el, majdnem azonos távolságra (nagyjából 8-9 kilométerre) Soltvadkerttől és Kiskunhalastól. Az előbbi város az északnyugati, utóbbi a délkeleti szomszédja, rajtuk kívül csak két településsel határos: északkeleti szomszédja Tázlár, a délnyugati pedig Imrehegy. Tázlárral az 5406-os út köti össze.'),
    ('Piskó', 'Az Ormánság középső-déli részén fekszik, Vajszlótól 8 kilométerre délnyugatra. A térség legdélebbi fekvésű falvai közé tartozik, lakott területe alig másfél-két kilométerre van a Dráva folyótól (amely ezen a szakaszon Magyarország és Horvátország természetes határát képezi), déli határszéle mintegy másfél kilométernyi szakaszon egybe is esik a déli országhatárral.'),
    ('Pitvaros', 'A dél-alföldi település Csongrád megye legszélén, Mezőhegyestől 6, Makótól 30, Szegedtől 60 kilométerre fekszik. Szomszédai: észak felől Ambrózfalva, kelet felől Mezőhegyes, dél felől Csanádpalota, nyugat felől pedig Csanádalberti.'),
    ('Pocsaj', 'A szomszédos települések a határ magyar oldalán: észak felől Létavértes, dél felől Kismarja, nyugat felől Esztár. északnyugat felől Hosszúpályi, észak-északnyugat felől pedig Monostorpályi. Határszéle keleten jó 4 kilométer hosszban egybeesik a magyar-román államhatárral, a legközelebbi település abban az irányban Félegyházi Újtelep (Mihai Bravu).'),
    ('Pogány', 'Pécs déli szomszédságában fekszik. A további szomszédos települések: északkelet felől Pécsudvard, délkelet felől Szőkéd, délnyugat felől Szalánta, nyugat felől pedig Kökény. Határszélét északon érinti még az 5716-os út is. A Baranyavártól Nagyharsányon és Gyűdön át Pécsre vezető egykori római út Pogányt is érintette. A település neve először 1181-ben fordult elő különböző alakokban: Pogan, Bugan, Pugan, Pokan. 1190-ben „Pagan-villa”-ba való egyházi nemesek tanúként szerepeltek.'),
    ('Pogányszentpéter', 'Mindössze két további települési szomszédja van: kelet-délkelet felől Iharosberény, délnyugat felől pedig Liszó. Északkelet felől a legközelebbi település Sand, de a közigazgatási területeik nem érintkeznek. Az első okleveles említése 1381-ben volt, akkor a pálosok Szent Péterről elnevezett kolostorát említették. 1390-ben Stregenchy Zentpeter, 1412-ben Nemetzenthpeter (Németszentpéter) néven említették. 1554-ben a falu elpusztult és csak a 18. század 20-as éveiben népesedett be újra.'),
    ('Polgár', 'A város a Hortobágy kistáj és Hajdú-Bihar megye északnyugati peremén található. Keleten külterülete Hajdúnánással is érintkezik. Környezetének megyei jogú városai közel azonos távolságra találhatóak. Közülük legtávolabb a megyeszékhely, Debrecen fekszik (57 kilométerre), Nyíregyháza 51, Miskolc pedig 49 kilométerre található. A legközelebbi várostól, Tiszaújvárostól mindössze 10 kilométer választja el.'),
    ('Polgárdi', 'A szomszéd települések: észak felől Úrhida, északkelet felől Kőszárhegy, kelet felől Tác és Csősz, délkelet felől Soponya, dél felől Mezőszentgyörgy, nyugat felől Füle, északnyugat felől pedig Jenő. Közigazgatási területe északkeleten érintkezik még Szabadbattyán határszélével is. A város személygépkocsi-forgalma intenzív. Kisebb mellékutak kötik össze a települést Kislánggal (6301), Fülével (7205) és Jenőn át Nádasdladánnyal (7206).'),
    ('Polány', 'Polány valószínűleg már az Árpád-korban egyházas hely volt. Szent Mártonnak szentelt templomát 1338-ban említik először. A török időkben a templom és a falu is elpusztult. A 18. században a faluba evangélikus németeket telepítettek. Napjainkban a lakosság többsége már katolikus.'),
    ('Pomáz', 'Budapest központjától 17, északi határszélétől alig 4 kilométerre északra fekszik, a Nagy- és Kis-Kevély hegyek lábánál, Budakalász és Szentendre szomszédságában. Nevezik a Pilis hegység kapujának is. Földrajzilag a pomáz-esztergomi törésvonal mentén helyezkedik el, a Kárpátok miocén kori vulkáni koszorújának első vonulata itt találkozik a várost átszelő Dera-patak völgye–Kovácsi-völgy vonulatától délre elhelyezkedő üledékes talajtakaróval.'),
    ('Porcsalma', 'A legközelebbi szomszédos települések közül Pátyodtól 2,5, Tyukodtól 4,5, Ököritófülpöstől pedig 5,5 kilométer választja el. A környező települések közül Szamossályival és Jánkmajtissal a 4138-as, Tyukoddal és Urával a 4923-as út köti össze. A hazai vasútvonalak közül a települést a Kocsord–Csenger-vasútvonalérinti, melynek egy megállási pontja van itt.'),
    ('Pornóapáti', 'A falu Szombathelytől 16 kilométerre délnyugatra fekszik, az osztrák határ mellett, a Pornóapáti-patak és a Pinka összefolyásánál. Határos települések Horvátlövő, Nárai, Ják, Abdalóc, Németlövő, Beled, valamint Pokolfalu. Neve valószínűleg a szláv Pernovo helynévből származik, eredete ismeretlen helyezkedik el. Névutótagja egykori ciszterci apátságára utal.'),
    ('Poroszló', 'A Tisza, illetve a Tisza-tó jobb partján fekszik, a Hevesi-sík délkeleti részén, Füzesabonytól 25 kilométerre délkeletre, Tiszafüredtől 9 kilométerre északnyugatra. A közvetlenül szomszédos települések: észak felől Egerlövő és Borsodivánka, északkelet felől Négyes, Tiszavalk és Tiszabábolna, kelet felől Tiszafüred, délnyugat felől Újlőrincfalva, északnyugat felől pedig Egerfarmos.'),
    ('Porpác', 'A Gyöngyös-sík keleti részén, Sárvártól 10 kilométerre nyugatra, Bögöttől 3 kilométerre nyugatra található. Zsáktelepülés, közúton csak Bögötön keresztül érhető el a 88-as főútról Sárvár nyugati határszélénél letérve, a 8458-as úton. A Savariából Arrabonába vezető római hadiút porpáci szakaszát már az 1870-es években említik. Ugyanekkortól fogva ismertek voltak a határban emelkedő sírhalmok, amelyekről a 20. század elején végzett feltárás alapján lehetett megállapítani, hogy a kora vaskorból származnak.'),
    ('Porrog', 'Csurgótól északnyugatra fekszik, a horvát határ közelében, a Porrogszentkirály-Surd közti 6813-as út mentén. A települést először 1536-ban említették írásban, amikor özvegy Laky Lázárnéé és más birtokosoké volt. 1550-ben Török Ferenc és György, Huszár János és Laky Lázár özvegye volt a birtokosa. Bogyay Judit és Kelcz Ignácné, szül.'),
    ('Porrogszentkirály', 'Csurgó nyugati szomszédságában fekszik, a horvát határ közelében. Központjának déli részén a 6808-as út halad keresztül, Porrog és Surd felé a 6813-as út indul innen helyezkedik el. A szomszédos települések: Porrog, körülbelül 1,5 kilométerre, valamint Gyékényes és Csurgó, egyaránt mintegy 5-5 kilométerre helyezkedik el. Porrogszentkirály neve az 1332–1337. évi pápai tizedjegyzékben fordult elő először. 1550-ben Török János, 1583-ban a Zrínyi család volt a földesura.'),
    ('Porrogszentpál', 'A település Csurgótól északnyugatra, Porrog és Somogybükkösd között fekszik. Közigazgatási területén áthalad a Porrogszentkirály-Surd közti 6813-as út, de központja csak arról dél felé leágazva, egy önkormányzati úton érhető el. Porrog irányában található a híres Hétszergörbe, ami nem más, mint maga a hét jellegzetes kanyart leíró országút. Porrogszentpált először 1443-ban említették írásban, akkor Kyszenthpal írásmóddal.'),
    ('Porva', 'A Magas-Bakonyban fekszik Zirctől közúton 9 kilométer-re észak-északnyugati irányban. A Hódos-ér patak kisebb forráságai között, északi tájolású völgyben fekszik. Az újabb házsorok a dombokra is felkúsztak. Nyugat-északnyugat felé a tájkép meghatározója a Kőris-hegy és Kék-hegy tömbje, amely a Bakony legmagasabb pontja (709 méter). Éghajlata hűvös, a völgyzugokban akár nyáron is előfordul fagyos hajnal helyezkedik el.'),
    ('Potony', 'A szomszédos települések: északkelet felől Zádor, kelet felől Teklafalu, dél felől Tótújfalu, nyugat felől Drávagárdony, északnyugat felől pedig Kastélyosdombó. Keresztülszeli a települést az EuroVelo nemzetközi kerékpárút-hálózat 13. számú, „Vasfüggöny” útvonalának horvát-magyar határ menti szakasza, amelynek a Drávatamási és Drávasztára közti 3. számú etapja érinti a falut.'),
    ('Prügy', 'A Taktaközben helyezkedik el, a Tisza jobb parti oldalán, a megyeszékhely Miskolctól 43 kilométerre keletre, Tokajtól körülbelül 15 kilométerre délnyugatra. A közvetlenül határos települések: észak felől Szerencs és Mezőzombor, északkelet felől Tarcal, dél kelet felől Taktabáj, dél felől a folyó túlpartján fekvő Tiszadada, délnyugat felől Taktakenéz, északnyugat felől pedig Taktaszada és Bekecs.'),
    ('Pula', 'Pula az Eger-séd (Eger patak) völgyének legkeletibb települése. Határában kora vaskori, Árpád-kori településnyomok találhatóak. A falu közelében állt a 13. században alapított tálodi monostor, amely a 16. században elnéptelenedett, majd a török veszély miatt felrobbantották. Pula első írásos említése 1357-ből származik (Pola). Ekkor a Rátóti család birtoka volt.'),
    ('Pusztaapáti', 'Pórszombattól északkeletre fekvő község. Vályi András Magyarország leírása című munkájában írta a településről: APÁTI. Határja elég tágas, de hegyes, legelője alkalmatos, és elég. Makk termő erdeje szép, fája tűzre elegendő, vagyonnyainak eladására módgya, tsekély földgyei soványok, réttyeivel együtt. Mivel a’ záporok elszokták mosni, mellyek miatt harmadik Osztálybéli.'),
    ('Pusztaberki', 'Budapesttől 55 kilométerre, a Börzsöny és a Cserhát hegységek közötti völgyben helyezkedik el. Lakott területét lombhullató és tűlevelű erdők veszik körül, így tiszta és egészséges a levegője, szép a környezete. A települést átöleli a Börzsöny keleti lejtőin eredő Derék-patak, amely az Ipolyba torkollik. A község valószínűleg a törökök hatására az eredeti helyéről a főúttól távolabb eső, védettebb völgybe települt át és jelenlegi helyén 1851-ben Berki-Puszta néven…'),
    ('Pusztacsalád', 'Határát a Kardos-ér szeli át dél-északi irányban helyezkedik el. Szomszédai: északkelet felől Csapod, dél felől Iván, délnyugat felől Újkér, északnyugat felől pedig Röjtökmuzsaj. Központjától messze elnyúló külterületei révén a határa egy-egy rövidebb szakaszon érintkezik amúgy távol eső települések határszéleivel is: észak felől így Fertőszentmiklós, kelet felől Dénesfa, északnyugat felől pedig Sopronkövesd is a határosának tekinthető.'),
    ('Pusztacsó', 'A Gyöngyös-sík északi peremén, a Kozár-patak mellett fekszik Szombathelytől 15 kilométerre északra. Zsáktelepülés, közúton csak a 8636-os út felől közelíthető meg, Kőszegpaty és Nemescsó között letérve, a 86 121-es számú mellékúton. Csó első írásos említése 1248-ból származik Chou alakban helyezkedik el. Neve a régi magyar Chu személynévből származik, első ismert birtokosa Csói Márton volt.'),
    ('Pusztadobos', 'A Nyírség északkeleti részén fekszik, Vásárosnaménytól 11, Nyírmadától 3, a megyeszékhely Nyíregyházától 40 kilométerre. A közvetlen szomszédos települések: észak felől Perényitanya (Vásárosnamény különálló városrésze), északkelet felől Vásárosnamény, kelet felől Nagydobos, délkelet felől Nyírparasznya, délnyugat felől Vaja, nyugat felől pedig Nyírmada.'),
    ('Pusztaederics', 'A település Zalaegerszeg és Lenti között körülbelül félúton, a Zalai-dombságban, a Felső-Válicka patak völgyében található. Határában található a Magyar Földgáztároló Zrt. föld alatti földgáztározója. Lakossága nem éri el a 200 főt. A népesség lassan fogyó és elöregedő. Vegyes vallású település, a lakosság 2/3-a római katolikus, 1/3-a evangélikus vallású.'),
    ('Pusztafalu', 'A Zempléni-hegység középső részén fekszik, közvetlenül a szlovák határ mellett, a megyeszékhely Miskolctól közúton mintegy 95 kilométerre északkeletre. A határ magyar oldalán csak két települési szomszédja van, dél felől Füzérkajata, nyugat felől pedig Füzér. Szlovák oldalról a két legközelebbi település északkelet felől Kozma (Kuzmice), kelet felől pedig Kolbása (Brezina).'),
    ('Pusztaföldvár', 'Orosházától 11 kilométerre, Békéscsabától 33 kilométerre fekszik. Szomszédai: északkelet felől Gerendás, kelet felől Csanádapáca, délkelet felől Kaszaper, dél felől Tótkomlós, délnyugat felől Kardoskút, nyugat és északnyugat felől pedig Orosháza. Déli határszélén az Orosháza-Mezőkovácsháza közti 4428-as út halad el, ez utóbbi város felől tehát ezen közelíthető meg.'),
    ('Pusztahencse', 'A falu a Mezőföld déli részén terül el: Nagydorog, Györköny, Paks és Tengelic szomszédságában. Belterülete 202 hektár, külterülete 2969 hektár. A településen többségben vannak a kisebb dombok mint felszíni formák. Ilyen magaslatok a 210 méter magas Sík-hegy, a 157 méteres Bagó-hegy és a 152 méteres Öröm-hegy. A falu szomszédos a Duna hordalékaként keletkező jellegzetes dél-mezőföldi kistájjal, a Tengelici-homokvidékkel.'),
    ('Pusztakovácsi', 'A településről csak a török hódoltság utánról maradtak fenn adatok. Neve egy 1703 előtti összeírásban puszta és Kovácsy alakban fordult elő, a Koroknay család birtokaként. 1726-ban Sárközy János, 1733-ban ismét a Koroknay család birtoka volt. 1767-ben már jobbágyfalu volt. A községhez az 1910-es adatok szerint…'),
    ('Pusztamagyaród', 'A Zalaegerszeg-Nagykanizsa-Letenye háromszögön belül fekszik, nem messze annak középpontjától. Területén a Zalaegerszeg és Letenye térségét összekötő, Becsehely és Bak között húzódó 7536-os út halad végig. Pusztamagyaród ősi település, mely valószínűleg már a kőkorszakban is lakott hely lehetett. A régi település a honfoglalás körüli időkben nem a mai helyén, hanem a mai falutól körülbelül 4 kilométer-re volt található, amelynek központja egy templom és egy a pálos kolostor volt.'),
    ('Pusztamiske', 'A település neve minden bizonnyal a Miske személynévből származik. A puszta jelző a 19. században rögzült, egykori elnéptelenedésére utalva. A szomszédos települések: Nemeshany, Nyirád, Szőc, Kolontár és Devecser. Nevét 1402-ben említették először Kysmiske néven, mint a környék kisnemesi falvainak egyikét. Az 1488 évi összeíráskor a Miske család birtoka volt.'),
    ('Pusztamonostor', 'Budapesttől kb. 70 kilométerre keletre, Szolnoktól kb. 60 kilométerre északnyugatra található. A közvetlen szomszédos települések: északkelet felől Jászágó (kb. 8 kilométerre), délkelet felől Jászberény (kb. 10 kilométerre), dél felől Jászfelsőszentgyörgy (légvonalban 5, közúton kb. 9 kilométerre), délnyugat felől Szentlőrinckáta (kb. 5 kilométerre), nyugat felől pedig Jászfényszaru (kb. 8 kilométerre).'),
    ('Pusztamérges', 'A szomszédos települések: észak felől Zsana, északkelet felől Kiskunmajsa (Gárgyán), délkelet felől Ruzsa, nyugat felől pedig Balotaszállás. Közigazgatási területe pontszerűen érintkezik még kelet felől Üllés, dél felől pedig Öttömös határszélével is. A település csak közúton közelíthető meg, s mivel a térséget feltáró főbb útvonalaktól is távol fekszik, csak mellékutakon érhető el.'),
    ('Pusztaottlaka', 'Két fő része Bagófalu és Tökfalu. Orosházától keletre, Medgyesbodzás, Medgyesegyháza és Újkígyós között fekvő település. Szomszédai: észak felől Újkígyós, dél felől Medgyesegyháza, délnyugat felől Medgyesbodzás, északnyugat felől pedig Csabaszabadi. Kelet felől a hozzá legközelebb fekvő település Kétegyháza, de közigazgatási területeik nem találkoznak egymással.'),
    ('Pusztaradvány', 'Közigazgatási határa körülbelül egy kilométer hosszban egybeesik az államhatárral. A közvetlenül szomszédos települések a határ magyar oldalán: északkelet felől Hernádpetri, délkelet felől Hernádvécse, délnyugat felől Fulókércs, nyugat felől pedig Szemere helyezkedik el. A határ túloldalán a legközelebbi település a közigazgatásilag Perény-Hímhez (Perín-Chym) tartozó Felsőlánc (Vyšný Lánec).'),
    ('Pusztaszabolcs', 'A várostól nagyjából 10–10 kilométerre található a Velencei-tó, illetve a Duna. Elővárosi vonatok kötik össze Budapesttel, Dunaújvárossal, Sárbogárddal, Dombóvárral, Székesfehérvárral. A székesfehérvári vonal kivételével minden irányban Stadler FLIRT típusú modern motorvonatok közlekednek, de a még nem villamosított székesfehérvári vonalon is 2019…'),
    ('Pusztaszemes', 'Pusztaszemes neve két szóból ered: a „szem” (ami jelenthet gabonát vagy magot) és „puszta,” ami arra utal, hogy a terület a török hódoltság idején elnéptelenedett. Egy másik lehetséges magyarázat szerint a falu nevét első tulajdonosáról, egy Szemes nevű férfiról kaphatta. Az Észak-Somogyi dombvidéken, közelebbről a Külső-Somogyi dombság területén található.'),
    ('Pusztaszentlászló', 'A településen polgárőrség működik. Pusztaszentlászló Zalaegerszegtől 25 kilométerre délre, az Alsó-Válicka patak völgyében fekszik, a Becsehely-Bak közti 7536-os út mentén. Különálló településrésze Válickapuszta, amely a határában induló patakok (Alsó- és Felső-Válicka) névadója. Nevezetessége a Püspöky-kúria, a hozzá tartozó kis templommal és legyesbényi Püspöky Grácián 1848-49-es szabadsághős emlékhelyével.'),
    ('Pusztaszer', 'A Pusztaszeri Tájvédelmi Körzet szélén, Ópusztaszertől északnyugatra fekszik. Közigazgatási területe durva közelítéssel trapéz alakú, attól nem sokban tér el. További szomszédai északkelet felől Tömörkény, délnyugat felől Kistelek, északnyugat felől pedig Pálmonostora helyezkedik el. A térség fontosabb települései közül Kistelek központja 9,5, Balástya 15,5, Sándorfalva pedig 29 kilométer távolságra található.'),
    ('Pusztavacs', 'Itt található Magyarország földrajzi középpontja. Budapest központjától légvonalban 49, közúton 59 kilométerre található zsáktelepülés. Szinte teljesen erdők fogják körbe, külterületének 63%-a erdő. Központi belterülete mellett jelentősebb súlyt képvisel a település nyugati határában fekvő Rákóczitelep. A szomszédos települések: északkelet felől Dánszentmiklós, kelet felől Mikebuda, délkelet felől Csemő, dél felől Lajosmizse és Táborfalva, délnyugat felől Örkény, nyugat felől Hernád, északnyugat felől pedig Újlengyel.'),
    ('Pusztazámor', 'Annak legkisebb lélekszámú települése. Budapesttől 28 kilométerre található délnyugati irányban. Pusztazámor a Mezőföld északi részén, a Pusztazámor-sóskúti pannon rögvidék 150–215 méterrel a tengerszint felett fekvő, kavicstakaróval borított dombvidékén található, a Zámori-patak völgye felett, Budapesttől délre, az Etyeki-dombság lankái és az Érd-Sóskúti-fennsík között, a Zámorhegy lábánál, a Zámori-patak két oldalán.'),
    ('Putnok', 'Északi határa a Putnoki-dombság tagolt felszíni területére is kiterjed. A megyeszékhelytől, Miskolctól 40 kilométerre északnyugatra terül el, Ózdtól 20 kilométerre északkeletre fekszik. A közvetlenül határos települések: északkelet felől Alsószuha, kelet felől Dubicsány, dél felől Sajóvelezd, délnyugat felől Sajónémeti, nyugat felől Hét, északnyugat felől pedig Serényfalva.'),
    ('Pácin', 'Miskolctól 96 kilométerre keletre, közvetlenül a magyar–szlovák határ mellett fekszik. Határátkelőhellyel rendelkezik. A szlovák oldalon lévő legközelebbi községek – ily módon tehát Pácin északnyugati, illetve északkeleti szomszédjai – a határátkelőhely túloldalán 3,7 kilométerre fekvő Nagykövesd (Veľký Kamenec) és az attól mintegy 5 kilométerre keletre fekvő Őrös (Strážne).'),
    ('Pácsony', 'Pácsony első írásos említése 1217-ből származik, amikor II. András király összeíratta a vasvári káptalan birtokait, beleértve Pácsonyt is. A török hódoltság után újratelepült falu jellegzetessége a hosszú, egyutcás településszerkezet. A falu jelentősége megnövekedett a pácsonyi járműjavító üzem működése idején, amely nemcsak a helyieknek, hanem a környező települések lakóinak is munkát adott.'),
    ('Páhi', 'Páhi a Kiskunsági-homokhátság egyik települése, Kecskeméttől országúton mintegy negyven, Kiskőröstől tizenhárom kilométerre helyezkedik el. Nem messze tőle található a Kiskunsági Nemzeti Park részét képező Kolon-tó. A Volánbusz menetrend szerinti járataival többek közt Kecskemét és Izsák felől érhető el a település. Mivel Páhi területe kiválóan alkalmas legeltetésre, a honfoglalás után a fejedelmi törzs részei szállták meg.'),
    ('Páka', 'A környező települések közül Lenti 11, Csömödér 3, Kányavár 5, Szécsisziget 6, Csesztreg 20, Rédics pedig 16 kilométer távolságra található. Az elnevezés eredete bizonytalan helyezkedik el. Egyes források szerint a közeli Alsó-Válicka neve a középkorban Páka volt, ezt később a torkolatánál fekvő településre is használni kezdték. Egy másik magyarázat a szláv eredetű, erős, hatalmas jelentésű Pak személynévből származtatja.'),
    ('Pákozd', 'A település és környéke kőkori, ókori és középkori régészeti lelőhelyekben gazdag terület. A magyar történelem két fontos, győztes csatája fűződik Pákozd nevéhez: a törökellenes küzdelmek során 1593-ban megvívott ütközet, valamint az 1848–1849-es szabadságharc egyik legnevezetesebb csatája.'),
    ('Pálfa', 'A település eredeti neve Pálfalva volt, mely később Pálfára rövidült. 1543-ban elfoglalta a török, de a magyar végvári vitézeknek időnként sikerült visszaszerezniök. 1559-ben I. Ferdinánd gróf Cseszneky Mihály és Baranyai Balázs várpalotai fővitézeknek adományozta. A 16. század második felében rác (szerb) menekültek telepedtek le a környező pusztákon helyezkedik el.'),
    ('Pálfiszeg', 'Pálfiszeg egy kis zsákfalu Zalaegerszegtől délnyugatra 15 kilométerre helyezkedik el. A falu belterülete közúton csak Csonkahegyhát felől érhető el, a 7405-ös útról a 74 116-os útra lekanyarodva. A falut 1751-ben említik először. A település neve is a családi névből és a „nagycsalád házcsoportja” jelentésű szeg szóösszetételbol származik. Pálfiszeg a Pálfy nemesi család ősi fészke.'),
    ('Pálháza', 'Miskolctól 87 kilométerre északkeletre található. Állandó lakosai száma szerint Magyarország legkisebb városa, továbbá a megye és Észak-Magyarország legkisebb közigazgatási területű városa. A terület az őskor óta lakott. A település az 1320-as években jött létre a füzéri uradalom részeként. Először egy 1389-es adománylevélben említik. A trianoni békeszerződés után a település az országhatár közelébe került.'),
    ('Páli', 'Magyarország északnyugati részén, a Kisalföldön, a Rábaköz déli részén fekszik, a Rábától körülbelül 4 kilométerre északra. A szomszéd települések: észak felől Magyarkeresztúr és Zsebeháza, északkelet felől Szil, délkelet felől Vág, dél felől Pápoc, délnyugat felől Edve, nyugat felől pedig Beled. A környező kisebb települések közül Vággal és Kemenesszentpéterrel a 8426-os, Edvével és Vámosújfaluval a 8427-es, Mihályival és Vadosfával a 8607-es utak kötik össze.'),
    ('Pálmajor', 'Mindössze három települési szomszédja van: északkelet felől Somogysárd, délkelet felől Kiskorpád, nyugat felől pedig Nagybajom. A terület, ahol ma a falu áll, a 19. században Somssich Pál birtoka volt, innen ered korábbi neve, Páltelke, melyből a századfordulóra alakult ki a mai Pálmajor elnevezés. 1923-ban nyílt meg népiskolája, ahova kb. 70 gyermek járt be mintegy 5 kilométeres körzetből.'),
    ('Pálosvörösmart', 'A Mátra déli lábánál, Gyöngyöstől északkeletre és Abasártól északra, a Sár-hegy lejtőjén, illetve a Bene-patak völgyében található. A település az Aba nemzetség ősi birtoka, amely e nemzetség Csobánka ágának jutott. 1304-ben itt alapítottak pálos kolostort az Aba nemzetségbeli Csobánka unokái: János fiai, Sámuel és Dávid, továbbá Péter fia Pál. 1356-ban az itteni pálosok Benén kaptak birtokrészeket, 1441-ben V.'),
    ('Pánd', 'Határszélét délkeleten érinti még a Nagykáta–Albertirsa közti 3115-ös út is. Majdnem teljes egészében egy völgyben fekszik, az Őrhegy, a Dobos-hegy és a Montágh-hegy határolja. Területén négy forrás található: Szilas, Diós, Szopókás, Sóskarét, melyek a Pándi-patakot táplálják. A patak a Tápióba torkollik. A falu első okleveles megemlítése 1275-ből származik.'),
    ('Pányok', 'A Hernád folyó közelében fekszik, a Zempléni-hegység nyugati lábainál, a megyeszékhely Miskolctól 74 kilométerre északkeletre. A közvetlenül határos települések: észak felől Kéked, dél felől Telkibánya, nyugat felől pedig Abaújvár. Kelet felől Füzérhez tartozó lakatlan, erdős külterületek határolják, a két település azonban távol esik egymástól.'),
    ('Pápa', 'A település híres számtalan templomáról, az Esterházy-kastélyról, barokk építészetéről és református kollégiumáról. 30 000 fős lakosságával a környék kulturális, gazdasági és turisztikai központja. Győrtől 42 kilométer-re délre, Pozsonytól 95 kilométer-re délkeletre, Veszprémtől pedig 40 kilométer-re északnyugatra helyezkedik el. Pápa a református egyház központja a Dunántúlon, amint azt számos egyházi örökségi helyszín és múzeum is sugallja.'),
    ('Pápadereske', 'Pápától 6,5 kilométer-re délnyugatra, Celldömölktől 19 kilométer-re keletre található. Mindössze három települési szomszédja van: északkelet felől Borsosgyőr (Pápa része), délkelet felől Dáka, nyugat felől pedig Nyárád. Kicsi, régi település Pápa közelében helyezkedik el. Nevét először 1240-ben IV. Béla király határjáró oklevele említette "Doroska" alakban helyezkedik el.'),
    ('Pápakovácsi', 'Pápa déli szomszédságában fekszik. A további szomszéd települések: északkelet felől a Pápához tartozó Tapolcafő, délkelet felől Döbrönte, dél felől Ganna, délnyugat felől Kup, északnyugat felől pedig Nóráp. A 83-as főúttól Pápakovácsi mindössze 4 kilométeres letéréssel elérhető. A 8-as főúttól való távolsága valamivel kevesebb, mint 20 kilométer.'),
    ('Pápasalamon', 'Pápától délnyugatra, a Bitva-patak mellett fekszik. A szomszéd települések: észak felől Dáka, kelet felől Kup, dél felől Doba, délnyugat felől Somlószőlős, nyugat felől pedig Nagyalásony. A három legközelebbi város Ajka, Devecser és Pápa, mindháromtól légvonalban körülbelül 13-16 kilométerre, közúton ennél valamivel nagyobb távolságra található. Pápa felől a 8403-as útra kell rátérni a 83-as főútról, majd Dáka lakott területét elhagyva, mintegy 2,5 kilométer után érhető el a Pápasalamonra vezető út elágazása.'),
    ('Pápateszér', 'Közigazgatási területéhez tartozik a hajdan önálló, mára már teljesen elnéptelenedett egykori Zsörk község is. Veszprémtől északnyugatra, Csót és Bakonytamási közt fekvő település. Korábban vasúton is elérhető volt, a Környe–Pápa-vasútvonalon, de 2007 óta ezen a szakaszon szünetel a személyforgalom. Neve a szláv teszér, taszár szóból ered, mely ácsot, famegmunkálót jelent.'),
    ('Pápoc', 'A falu a Vasi-Hegyhát folytatásának tekinthető Kemeneshát (Cser) észak-nyugati szélén a Rába folyó jobb partján a Lánka-patak – jelenleg száraz meder – torkolatánál található. Helyzetét a 16. század közepén megjelenő kezdetleges magyarországi térképek is feltűnően jó pontossággal mutatják. Az 1851-es kiadású Magyarország geográfiai szótára szerint Pápócz: „Határa róna és igen termékeny.'),
    ('Páprád', 'Az Ormánság északi részén fekszik. A szomszédos települések: északkelet felől Bogádmindszent, kelet felől Hegyszentmárton, délkelet felől Kórós, dél felől Adorjás, Sámod és Baranyahídvég, délnyugat felől Vajszló, nyugat felől Besence, északnyugat felől pedig Gilvánfa. A falu nevét az oklevelek 1322-ben említették először Paprad alakban helyezkedik el.'),
    ('Pári', 'Tamásitól 6 kilométerre fekszik dél-délnyugati irányban, a Koppány völgyében. Mindössze két további települési szomszédja van: dél felől Gyulaj, nyugat felől pedig Nagykónyi. Pári 1984 és 2006 között Tamási része volt. A köztársasági elnök 2003-ban hozott határozata alapján 2006. október elsejétől ismét önálló község. A településről már a 14. században említést tesznek pápai adókönyvek, de nevét feltehetően a 16. század közepén itt élt nemesek, Johann és Simon Paari után kapta.'),
    ('Pásztori', 'Magyarország északnyugati részén, a Rábaközben, Csornától 7 kilométer-re délre, Szilsárkánytól 2 kilométerre keletre található. Területe teljesen sík, tengerszint feletti magassága 119 méter. A főútról Szilsárkány központjában letérve, a 8423-as úton érhető el a település. Ugyanez az út köti össze kelet felől Rábapordány és Bágyogszovát községekkel is.'),
    ('Pásztó', 'Az évszázadok során főleg kereskedelemmel foglalkozó mezővárosként vált ismertté. Lakóinak száma – Hasznos és Mátrakeresztes városrészek népességével együtt – nagyságrendileg kilencezer fő. Gyöngyöstől északnyugatra, Tar, Mátraszőlős, Zagyvaszentjakab, Kozárd és Csécse között fekszik, a Mátra nyugati lábánál. A Zagyva folyó és a Kövecses-patak által közrefogott dombhátra települt, mintegy 171 méteres tengerszint feletti magasságra.'),
    ('Pátka', 'Mióta a Bicske–Székesfehérvár-vasútvonalon a személyforgalmat 1979-ben megszüntették, a falu zsáktelepüléssé vált. A község a Császár-víz (mely a Vértes hegység déli lejtőin fakadó forrásokból ered) bal partján fekszik. Határában helyezkedik el a Velencei-tó vízkiegyenlítésében jelentős szerepet játszó Pátkai-víztározó, amely a Császár-víz közvetítésével összeköttetésben van a Zámolyi-víztározóval.'),
    ('Pátroha', 'A Rétköz területén fekszik, Nyíregyházától mintegy 35 kilométerre. Különálló településrésze Bajorhegy (vagy Bajorhegytanya), a központjától mintegy 2 kilométerre délnyugatra helyezkedik el. A közvetlen szomszédos települések: észak felől Kékcse, északkelet felől Rétközberencs, kelet felől Ajak, dél felől Nyírtass, délnyugat felől Gégény, északnyugat felől pedig Dombrád és Tiszakanyár.'),
    ('Páty', 'Lakóinak száma kb. nyolcezer fő. A Budai-hegységet a Gerecsétől elválasztó Zsámbéki-medence délkeleti részében, a Füzes-patak forrásvidékén épült település Budapesttől közúton mért távolsága kb. 25 kilométer. A vele szomszédos helységek: Zsámbék, Tök, Budajenő, Telki, Nagykovácsi, Budakeszi, Biatorbágy, Herceghalom és Bicske. A Budakeszi- és a Zsámbéki-medencét a sekély Mézes-völgy köti össze, amire találóan illik a „pátyi kapu” elnevezés.'),
    ('Pátyod', 'A legközelebbi települések: Porcsalma 2,5 kilométerre északnyugati, Csenger pedig 6 kilométerre délkeleti irányban helyezkedik el. Nevét 1325-ben Pathwid alakban irták, ekkor a Pátyody család birtoka volt. 1498-ban Rohody Péter kapta meg. 1501-ben Zoltán János, 1504-ben Zoltán István és Ferenc részbirtoka volt, 1549-ben Báthori András kapott benne részt.'),
    ('Pázmánd', 'Kápolnásnyék 7 kilométer, Nadap 6 kilométer, Pákozd 14 kilométer, Baracska 10 kilométer, Csákvár 23 kilométer, Martonvásár 13 kilométer távolságra található. Településrésze, Szőlőhegy Pázmánd centrumától 3 kilométerre fekszik, déli irányban. 2011-es adatok szerint Szőlőhegy lakónépessége 10, a lakások száma 4, a nem lakott üdülők száma 288. 2005 óta minden év pünkösd hétfőjén megrendezik a Hegyünnepet Szőlőhegyen.'),
    ('Pázmándfalu', 'A község Győrtől 15 kilométer-re délkeletre a Sokorói-dombság északkeleti részén helyezkedik el. Csendes, tiszta levegőjű vidék. Az itt lakók földműveléssel, állattenyésztéssel foglalkoznak. Pannonhalma északkeleti szomszédja. Neve a legrégebbi okiratokban Paznan és Poznan írásmóddal található meg. Nevét a Svábföldről beköltözött Hunt-Pázmán nemzetségről kapta.'),
    ('Pécel', 'Pécel a Gödöllői-dombság nyugati peremén, a Rákos-patak völgyében helyezkedik el. Nyugati irányban Budapest XVII. kerületével, keleti irányban Sülysáppal, északkeleti irányban Isaszeggel, északnyugati irányban Nagytarcsával és Kistarcsával, délről pedig Maglóddal határos. A község belterületén többek között kő- és rézkori csontvázas sír, a Várhegyen bronzkori urnatemetőt találtak, a Tó-malom melléke és a Lebuki-dűlő feltehetően szarmata sírok emlékét őrzi.'),
    ('Pécs', 'Pécs Magyarország délnyugati részén, az ország ötödik legnagyobb települése Budapest, Debrecen, Szeged és Miskolc után, a Dunántúlon pedig a legnagyobb település. A kelta és pannon törzsek lakta vidéken a 2. század elején a rómaiak alapítottak várost Sopianae néven. A település a 4. századra tartományi székhellyé és a korai kereszténység egyik jelentős központjává vált.'),
    ('Pécsbagota', 'Pécstől mintegy 25 kilométerre délnyugatra fekszik, a Pécsi-víz mellett. Külterületének csak a Szabadszentkirály felőli része alkalmas a hagyományos szántóföldi művelésre helyezkedik el. A község másik oldalán elhelyezkedő dombokat jelentős kiterjedésű erdők és szőlők borítják. Baranya aprócska falva, területe mindössze 607 hektár, házainak száma pedig 38.'),
    ('Pécsdevecser', 'Siklóstól északkeletre, Újpetre és Peterd, illetve Újpetre és Kiskassa között fekvő település. Nevét az oklevelek 1332-ben említették először (Deu)acha, de Wech(us), de Nechus, de Danaba alakban írva. 1332-ben a pápai tizedjegyzék szerint 50 báni pápai tizedet fizetett. A török idők végére a falu elnéptelenedett, csak 1733tól népesedett be újból, német telepesekkel, később magyarok is letelepedtek a faluba.'),
    ('Pécsely', 'A falu a Balatontól 5 kilométerre fekszik, Veszprémtől és Balatonfüredtól sem messze, a dombokkal övezett Pécselyi-medencében. A református templom fölötti, nyugati falurészben a 16-17. században kizárólag a nemesi rendhez tartozók laktak, községük Felsőpécsely, amely Nemespécsely néven ismert. A templomtól keletre fekvő Nagypécselyen jobbágyok laktak.'),
    ('Pécsudvard', 'A Baranyai-dombság szívében fekszik a település. Északról Pécs, északkeletről Kozármisleny, délkeletről Egerág, délről Szőkéd, délnyugatról pedig Pogány határolja. A Pécstől délre fekvő település kedvező természeti adottságait látszik alátámasztani az a tény, hogy már a kőrézkortól lakott hely volt (baden-péceli kultúra). Régészeti emlékeket a bronzkor kultúrái: a somogyvár–vinkovci és a mészbetétes kultúra népei, illetve az őket követő rómaiak is hátrahagytak.'),
    ('Pély', 'A közvetlen szomszédos települések: észak felől Hevesvezekény, északkelet felől Tarnaszentmiklós, kelet felől Kisköre, délkelet felől Tiszabura, dél felől Tiszaroff és Tiszasüly, délnyugat felől Jászkisér, nyugat felől Jászivány, északnyugat felől pedig Heves. Külterületeinek jelentős része – a falu központjától északra eső területek szinte teljes egésze – a Hevesi Füves Puszták Tájvédelmi Körzethez tartozó, természetvédelmi oltalom alatt álló terület.'),
    ('Pénzesgyőr', 'A 367 lelket számláló község az Öreg-Bakony egyik legszebb táján található, Zirctől 10 kilométerre nyugatra, Bakonybéltől pedig délre. A mai település területe és környéke már az őskorban is lakott volt. Régészeti leletek – köztük bronzkori halomsírok, valamint rézkori és vaskori emlékek – tanúsítják, hogy a Bakony e része kedvező természeti adottságai révén korán megtelepedésre alkalmas területnek számított.'),
    ('Pér', 'A település a Kisalföld délkeleti részében, a Bakony-ér völgyében fekszik, Győrtől 15 kilométerre délkeletre. Az itteni táj átmenetet képez a síkság és a Sokorói-dombság (Pannonhalmi-dombság) között. Az átlagos tengerszint feletti magassága 132 méter. A szomszéd települések: észak felől Bőny, kelet-délkelet felől Mezőörs, dél felől Pázmándfalu, nyugat felől Töltéstava, északnyugat felől pedig Győr (Győrszentiván).'),
    ('Péterhida', 'Péterhida a Tibold nemzetség ősi birtoka volt, később II. Ulászló a Báthoriaknak adományozta. 1536 és 1550 az ezen családból származó Báthori András mellett a babócsai plébános is a falu földesura volt. 1660-ban az akkor Péter-hídja néven említett település Szent-György várának tartozéka volt, majd 1677-ben a Széchenyiek tulajdonába került, és egészen a 20. századig az övék is maradt. 1848 őszén egy Jelacsics hadához tartozó granicsárcsapat megtámadta a falut, de a helyi nemzetőrök és népfelkelők sikeresen visszaverték a támadást.'),
    ('Péteri', 'Péteri Monor és Gyömrő között fekvő kistelepülés, Pesttől 28 kilométer-re. Innen félóránként csatlakozó buszjáratok indulnak a falu központjába. Örs vezér tere - Rákoskeresztúr városközpont - Ecser - Maglód - Gyömrő - Péteri - Monor útvonalon és vissza. A település neve személynévi eredetű. Jelentése: "Péteré" A községre vonatkozó első adatok 1246-ból származnak.'),
    ('Pétervására', 'Egybeépült Erdőkövesd településsel. Helyileg és a környéken általánosan használt (nem hivatalos) elnevezése: Péterke. A megye északi részén, a Tarna völgyében fekszik, a megyeszékhely Egertől közúton 33, Salgótarjántól 35, Ózdtól 36 kilométer-re. Dél-délnyugat felől a Mátra, északról a Tarnavidéki Tájvédelmi Körzet (a bárna–ivádi hegycsoport és a Heves–Borsodi-dombság), keletről a Bükk-vidék határolja.'),
    ('Pétfürdő', 'A Keleti-Bakony és a Mezőföld találkozásánál, a Sárrét közelében, Várpalota városától 2 kilométerre nyugatra fekszik. Első ismert említése 1082-ből származik, ekkor a Péti-víz mentén működő malmai kapcsán említették. A környék azonban már korábban is lakott volt, erre a település határában feltárt római kori út- és gátmaradványok utalnak. Később Anonymus említi, mint a Veszprém meghódítására induló honfoglalók pihenőhelyét.'),
    ('Pócsa', 'Villánytól mintegy 5 kilométerre északra, Borjádtól 3 kilométerre délre fekszik. Keleti irányból is e két településhez tartozó területek határolják, így csak két további települési szomszédja van: délnyugat felől Kisjakabfalva, nyugat felől pedig Kisbudmér. A Karasica-patak völgyében fekvő pici, egyutcás település már a honfoglalás előtt is lakott hely volt.'),
    ('Pócsmegyer', 'Budapesttől légvonalban mintegy 26 kilométerre (közúton 38 kilométerre) északra, a Duna főága és a Szentendrei-Duna által közrefogott Szentendrei-szigeten fekszik. Hozzá tartozik a ma már lakóövezetté vált egykori üdülőterület, Surány is. Az Ófalut és Surányt a Sziget út választja el. Szomszédja még nyugati irányból – a Szentendrei-Duna túlpartján – Leányfalu is, amellyel 2024-ig kompjárat kötötte össze.'),
    ('Pócspetri', 'A megyeszékhelytől, Nyíregyházától 27 kilométerre fekszik, a környező fontosabb települések közül Máriapócstól 3,5, Kállósemjéntől 6, Nyírbátortól és Nagykállótól egyaránt 14-14, Mátészalkától pedig 34 kilométer távolság választja el. Lakott területén azonban csak a 4928-as út halad keresztül, mely nemcsak az előbbi úttal köti össze, de a szomszédos Máriapócs központjával is.'),
    ('Pókaszepetk', 'A településen polgárőrség működik. A település a Sümeg–Zalabér–Zalaegerszeg nyomvonalon húzódó 7328-as út mentén fekszik, amely a két végponti város mellett a Veszprém, Győr és Zalaszentgrót felé történő közlekedést is lehetővé teszi. Elsősorban Zalaegerszegről érhető el elővárosi és helyközi járatokkal, de sok busz érkezik Zalaszentgrót felől is. Továbbá Sümegre és Veszprémbe is el lehet jutni a településről.'),
    ('Pórszombat', 'A Göcsej nyugati oldalán, Zalaegerszegtől 30 kilométerre, Csesztregtől keletre fekvő település. A Medes-patak dombokkal körülvett völgyében, erdőkkel körülvett területen fekszik, a településen átfolyik a Morgos patak, mely a falu végén a Medes-patakba ömlik. A falu és környéke természeti értékekben gazdag, főként a patak völgye és az erdők környéke.'),
    ('Pósfa', 'A közvetlenül határos települések: észak felől Répceszentgyörgy, északkelet felől Hegyfalu, délkelet felől Rábapaty, dél felől Ölbő, nyugat felől pedig Szeleste. Érinti az M86-os autóút is, de annak nincs csomópontja a határai között.'),
    ('Pölöske', 'A környező települések közül Zalaszentmihály 5,5, Nemesszentandrás 6, Bak 6,5, Sárhida 9, Pacsa 9, Zalaigrice pedig 12 kilométer távolságra található. A közvetlenül határos települések: észak felől Búcsúszentlászló, északkelet felől Nemessándorháza és Nemesszentandrás, délkelet felől Zalaszentmihály és Pötréte, dél felől Hahót, délnyugat felől Söjtör, nyugat felől Bak és Sárhida, északnyugat felől pedig Csatár, Botfa [Zalaegerszeg része] és Nemeshetés.'),
    ('Pölöskefő', 'Területe sík, helyenként dombos. A község keleti határszélén a Principális-csatorna húzódik végig. Első írásos említése 1354-ben történt, Pyliskefew néven helyezkedik el. Nevét a Piliske/Pölöske (ma Szévíz) patak után kapta. Melynek forrásánál épült. A falu területe a zalai apátság birtoka volt, melyet az Ördög család használt. Az 1400-as években vár is épült a településen, ezt a 16. század elején a Kaczor család vette zálogbirtokba az apátságtól.'),
    ('Pörböly', 'A település az első világháború után alakult ki, lakói a környező tanyákról költöztek ide. Ekkor még Pörbölypuszta néven Alsónyék község belterületi lakóhelyeként tartották nyilván helyezkedik el. Az 1956-os és 1965-ös dunai árvizek után jelentősen megnőtt a beköltözők száma, ennek hatására 1985. január 1-jén önálló községgé nyilvánították. 1990-től saját önkormányzata van.'),
    ('Pördefölde', 'Pördefölde első írásos említése 1389-ből származik, ekkor Perdefeld alakban írták. 1531-ben a 8 jobbággyal rendelkező Horváth Lukács birtokolta, valamint Bánffy Lászlónak is volt itt 7 portája. 1576-ban a törökök felégették a települést. 1589-ben összesen 13 ház állt itt, ebből 6-ot a Bánffy család három tagja, 5-öt Nádasdy Ferenc, míg kettőt Deörsfy Ferenc birtokolt.'),
    ('Pötréte', 'Pötréte első írásos említése a 13. század közepéről, 1269-ről való. Ekkor a település Petréte név alatt szerepel. Nem lehet pontosan tudni, honnan származik a név. Keletkezhetett a Petrus személynév rövidüléses formájából, a Pétre réte birtokos szerkezetből. Nem zárható ki az sem, hogy a név szláv eredetű.Pötréte első írásos említésekor IV. Béla Csák orbászi ispánnak adott a zalai vár petrétei és bezzegdi birtokaiból hat ekealja földet cserébe. 1379-ben aztán Rajky Péter egy oklevéllel akarta igazolni, hogy az említett birtokot IV.'),
    ('Püski', 'Önálló a Szigetköz középső harmadában, a Duna jobb partján helyezkedik el. Mosonmagyaróvártól keletre 13 kilométer, Győrtől északnyugatra nagyjából 28 kilométer távolságra fekszik. Az 1401-es számú szigetközi útról Halászitól közvetlenül, Hédervártól vagy Darnózselitől Lipót és Dunaremete érintésével közelíthető meg, az 1405-ös úton helyezkedik el.'),
    ('Püspökhatvan', 'A Gödöllői-dombság és a Cserhát között elterülő hegyes-völgyes vidéken fekszik, Váctól 28, Aszódtól 18, Gödöllőtől 30 kilométer-re, ill. a régiós közigazgatási beosztás szerint a Közép-Magyarországi Régió északkeleti részén helyezkedik el, Budapesttől 50 kilométer-re északkeleti irányban. A község a Váci statisztikai kistérség és a Váci Kistérségi Társulás tagja.'),
    ('Püspökmolnári', 'Rábamolnári, Rábaszenttamás és Rábapüspöki községek egyesítésével jött létre. Szombathelytől 30 kilométerre délkeletre fekszik, a Rába bal partján. Három, korábban önálló településrésze közül Rábamolnári fekszik a legnyugatabbra, Rábaszenttamás helyezkedik el a mai község középső részén, Rábapüspöki pedig a legkeletibb fekvésű falurész. A szomszédos települések: észak felől Rábatöttös, északkelet felől Zsennye, dél felől Vasvár, nyugatról Rábahídvég, északnyugat felől pedig Gyanógeregye.'),
    ('Püspökszilágy', 'Püspökszilágy Váctól délkeletre a Nyugati-Cserhát déli nyúlványai között búvik meg, a várostól mintegy 15-16 kilométer távolságban. Határa 2530 hektárnyi területének nagyobbik felét ma is összefüggő, – jórészt tölgyes, cseres – erdők foglalják el. Zsáktelepülés, közúton csak Váchartyánon és Kisnémedin érhető el, a 2105-ös útból kiágazó 21 114-es számú mellékúton.'),
    ('Radostyán', 'Miskolctól 21 kilométerre északnyugatra található. A környező települések Kondó, Parasznya, Sajólászlófalva (3 kilométer), Varbó. A legközelebbi város Sajószentpéter (7 kilométer). A kelták kora óta lakott környék. Radostyánt először a 14. században említik, a diósgyőri uradalom részeként, de elképzelhető, hogy azonos a Váradi regestrumban Zudesthan néven említett településsel.'),
    ('Ragály', 'Az Aggteleki-karszt déli részén helyezkedik el, a megyeszékhely Miskolctól 46 kilométerre északra. A környező települések: északkelet felől Imola (5 kilométer), délkelet felől Zubogy (5 kilométer), dél felől Alsószuha (7 kilométer), délnyugat felől Zádorfalva (5 kilométer), északnyugat felől pedig Trizs (4 kilométer). A legközelebbi városok: Rudabánya (12 kilométer), Putnok (21 kilométer) és Kazincbarcika (25 kilométer).'),
    ('Rajka', 'Északról Szlovákia, nyugatról Ausztria határolja. A község a Mosoni-síkság északnyugati csücskében, a Duna Körtvélyesi-(Somorjai) víztározójának közelében, Mosonmagyaróvártól 15 kilométerre északnyugatra, Pozsonytól pedig 20 kilométer-re délkeleti irányban helyezkedik el. Ez az egyetlen település a megyében, amely (részben) a 48. szélességi körtől északra fekszik.'),
    ('Rakaca', 'A környező települések: észak felől Viszló (4 kilométer), északkelet felől Pamlény, kelet felől Szászfa (5 kilométer), délkelet felől Gagybátor, dél felől Irota, nyugat felől Rakacaszend (6 kilométer), északnyugat felől pedig Debréte. A legközelebbi város a határ magyar oldalán a 24 kilométerre lévő Szendrő (a határ túloldalán fekvő, szlovákiai Tornától valamivel kisebb, kb. 21 kilométeres távolság választja el).'),
    ('Rakacaszend', 'Az aprófalu Szendrőtől 18 kilométerre keletre, a megyeszékhely Miskolctól 56 kilométerre északra fekszik. A környező települések: észak felől Debréte, kelet felől Rakaca (6 kilométer), délkelet felől Irota, dél felől Abod, délnyugat felől Galvács, nyugat felől Meszes (6 kilométer), északnyugat felől pedig Tornabarakony. A legközelebbi város Szendrő.'),
    ('Rakamaz', 'A Zempléni-hegység és az Alföld találkozásánál, a Hajdúhát északi csücskében, az életet jelentő Tisza folyó bal partján terül el, ősidők óta lakott hely. A település annak a félkörnek a középpontjában épült, amelyet a Tisza folyó ír le ott, ahol a Zempléni-hegység koszorúja nagy ívben tereli a Bodrogot a Tiszába.'),
    ('Ramocsa', 'Főutcája a Lentitől a bajánsenyei határátkelőhelyig húzódó 7416-os út. Neve a Rama személynév ''-csa'' becéző képzős származékából alakult ki. Eredete a német Rami, Ramo alakból vezethető le. Nevét 1378-ban említik először Ramcha-ként. Első említésekor a bekcsényi (becsehelyi) főesperességhez tartozott.A 15. században telepedett le itt a Ramon család.'),
    ('Ramocsaháza', 'A Közép-Nyírségben található, Nyíregyházától 30 kilométerre északkeletre, Baktalórántházától 10 kilométerre északnyugatra. A közvetlen szomszédos települések: észak felől Berkesz, északkelet felől Nyírtass, kelet felől Laskod, délkelet felől Nyírkércs, délnyugat felől Nyíribrony, északnyugat felől pedig Székely. Észak-északnyugati irányból egy rövid szakaszon határos még az amúgy több mint 10 kilométerre fekvő Demecserrel is.'),
    ('Raposka', 'A Balaton-felvidéken a Tapolcai-medencében fekszik, a Szent György-hegy nyugati lábánál, Hegymagas északi szomszédjában. Területén keresztülfolyik a Kétöles-patak. Elérhető menetrend szerinti busszal is.'),
    ('Ravazd', 'Pannonhalmával a 8225-ös, Táppal pedig – Tarjánpuszta és Győrasszonyfa érintésével – a 8226-os út köti össze. A község nevének eredete feltehetően a személynévként is használt magyar ravasz (róka) főnévre vezethető vissza. Mások szerint az 1093. évi összeírás szerint lakott itt egy Ravazd nevű ember. A múlt századi régészeti kutatások mutatták ki, hogy ezen a környéken nem jelentéktelen római települések voltak, melyek egészen a mai Pannonhalmáig elhúzódtak.'),
    ('Recsk', 'A Mátra északi oldalán, a Parád–Recski-medencében, a Parádi-Tarna völgyében helyezkedik el. Közelében, a Szederjes-tetőn az Árpád-korban állt Szederjesvár. Az első hiteles említés a településről az Anjouk korában keletkezett, a 14. század elején Recsky Demeter volt a tulajdonosa. A település nevét 1329-ben Rexy alakban rögzítették. A község neve 1478-ban Rekch névalakban szerepel. 1554-ben 4 portát számoltak, de a török dúlások után is a Recsky család maradt a birtokos, habár a kuruc és…'),
    ('Regenye', 'Horvátul a falu hivatalos neve a szalántaiak által használt Regenja, de a szőkeiek által használt Reginja alakot is használták. A megyeszékhelytől, Pécstől mintegy 14 kilométer távolság választja el, déli irányban. A környező települések közül Görcsönyből és Szilvástól is nagyjából 2–3 kilométerre helyezkedik el. Regenye már az Árpád-korban is lakott település volt.'),
    ('Regéc', 'A közvetlenül szomszédos települések: észak felől Telkibánya, északkelet felől Nagyhuta, kelet felől Háromhuta, dél felől Mogyoróska, nyugat felől pedig Fony. A legközelebbi város a 19 kilométerre fekvő Gönc. Csak közúton érhető el, Fony vagy Háromhuta (Óhuta) érintésével, a 3716-os úton. Regéc neve szláv eredetű, szarvat jelent. Regécet 1298-ban említik először, de ekkor valószínűleg a település még nem állt, csak a hegyről volt szó.'),
    ('Regöly', 'A Kapos völgyében fekszik. A közvetlenül határos települések: észak felől Pincehely, északkelet felől Belecska és Keszőhidegkút, kelet felől Gyönk, délkelet felől Szárazd, dél felől Hőgyész és Szakály, északnyugat felől pedig Tamási. Már az őskor óta lakott, később a kelták földvárat emeltek itt, amely egyik legjelentősebb településük központja lett Regöly a La Tène-kultúra leggazdagabb magyarországi lelőhelye.'),
    ('Remeteszőlős', 'Magyarország legkisebb területű települése. Budapest határában helyezkedik el, a főváros felől nézve valamivel Adyliget után. A Budai-hegység 400-500 méter magas mészkő- és dolomithegyei között fekszik az Ördög-árok völgyében, 342 méter magasan. Fölé magasodik a 424 méter magas Remete-hegy, amelynek barlangjai a település külterületén találhatók, és amelyről kapta nevét a település.'),
    ('Resznek', 'Közigazgatásilag a falu a rédicsi körjegyzőséghez tartozik. Maga is határfalunak számít, nyugati szomszédja, Kebeleszentmárton már Szlovéniához tartozik. Resznek Árpád-kori település. Nevét már 1282-ben említették az írásos források Rezmuc néven helyezkedik el.'),
    ('Rezi', 'Rezi Keszthelytől 8 kilométerre északra, a Keszthelyi-fennsík belsejében helyezkedik el. Nyugatról, délről és északról erdőségek, keletről szőlős domboldalak övezik a községet. Rezi első említése 1236-ból való. Ekkor királyi szolgák lakták a települést. A helység legjelentősebb épülete, a vár később épült. A forrásokban legkorábban 1335-ben fordul elő mint királyi vár.'),
    ('Ricse', 'Jellegzetes észak-alföldi tájon fekszik, az ukrán határtól kb. 8, a szlovák határtól kb. 3-4 kilométerre. A falu nagy része dombos terület. Határában folyik az itt különösen kiszélesedő Tisza, aminek a jobb partján terül el. A szomszédos települések: észak felől Semjén, északkelet felől Lácacséke, kelet felől Révleányvár, délkelet felől Szabolcsveresmart, dél felől Tiszakanyár – utóbbi kettő a Tisza túlpartján fekszik –, délnyugat felől Cigánd, nyugat felől Nagyrozvágy, északnyugat felől pedig Kisrozvágy.'),
    ('Rigyác', 'A néprajzilag Eszteregnyével, Sormással és Becsehellyel táji csoportot alkotó Rigyác első említése 1411-ben: Rigyalch. Szerb–horvát eredetű elnevezés. 1406-ban Petri János fia Istvánnak, majd a Répásy családnak volt itt birtoka.'),
    ('Rimóc', 'A Novohrad-Nógrád UNESCO Globális Geoparkhoz tartozó település a Cserhát északi nyúlványai alatt, az Ipolytól és Szécsénytől délre, négy kilométernyire található község. A város felől szántóföldek határolják, míg délről a Cserhát magaslatai koszorúzzák a falut, amelyet a Körtvélyes-patak szel ketté.'),
    ('Rinyabesenyő', 'Nagyatádtól délkeletre, a Rinya patak völgyében fekszik, erdőkkel övezve. A közvetlenül határos települések: észak felől Mike, északkelet felől Kőkút, dél felől Homokszentgyörgy, nyugat felől Görgeteg, északnyugat felől pedig Lábod. Közúton csak Lábod felől érhető el, a 68-as főútból ott kiágazó 66 143-as számú mellékúton. Rinyabesenyő neve először az 1332-1337-es pápai tizedjegyzékben tűnt fel, tehát már ekkor egyházas helynek számított.'),
    ('Rinyakovácsi', 'Nagyatádtól északkeletre, Jákó, Gige és Csököly közt fekszik, közigazgatási területén áthalad a Nagybajom-Kadarkút közti 6618-as út, de központja csak az abból nyugat felé kiágazó 66 154-es számú mellékúton érhető el. Az 1554 évi adólajstromban – már Kovácsi írásmóddal – csak 4 házzal írták össze, 1571-ben pedig 5 házzal, majd a 16. század végén elpusztult és csak 1720-ban kezdett újból benépesülni, és mint puszta Gigéhez tartozott. 1726-tól a herczeg Esterházyaké volt.'),
    ('Rinyaszentkirály', 'A település már az államalapításkor lakott hely lehetett, (bronzkori halottiurna-töredékek is kerültek elő a településen[forrás?]) de neve csak az 1332–1337-es pápai tizedjegyzékben fordult elő először írásban, ekkor nevét S. Rege formában írták, 1451-ben pedig már Zenthkyral alakban helyezkedik el. A török pusztítás Szentkirályt sem kerülte el: templomát is lerombolták, de a 19. században a település jelentős fejlődésen ment keresztül: 1842-ben új templom épült, 1850-ben pedig már 1799-en lakták a falut.'),
    ('Rinyaújlak', 'Nagyatád és Barcs között nagyjából félúton helyezkedik el, légvonalban mindkettőtől közel azonos távolságra. A szomszédos települések: északkelet felől Görgeteg, kelet felől Csokonyavisonta, dél-délnyugat felől Somogyaracs, nyugat felől Rinyaújnép, nyugat-északnyugat felől Bakháza, észak-északnyugati irányból pedig Rinyaszentkirály.'),
    ('Rinyaújnép', 'Barcstól északnyugatra, a Rinya patak mellett, Bakháza és Rinyaújlak közt fekszik. A központjától a déli falurészbe vezető rövid útszakasz is országos közútnak minősül, 68 130-as számozhással. A községről szóló első írásos említés 1352-ből való, akkoriban Wynep alakban jelenik meg. Zsigmond király idejében az osztopáni Perneszy család birtokaként szerepel 1417-től - 1660 körüli időszakig. 1713-ban a gróf Rindsmaul család nyerte adományként, 1773-ban pedig Végh Péter kanczelláriai előadó birtoka, majd 1835-ben Végh István örököseié.'),
    ('Rohod', 'A környező települések közül Vaja 3, Baktalórántháza 7, Vásárosnamény 18, Mátészalka 19, a megyeszékhely, Nyíregyháza pedig 34 kilométer távolságra található. A községet a környező településekkel és a nagyobb városokkal autóbuszjáratok kötik össze. Nevének első ismert okleveles említései a 12. századból, majd a 14. század elejéről valók, utóbbiban egy, a településről származó kisnemes Várdai Lászlóval folytatott perét említik.'),
    ('Romhány', 'A megye nyugati felében fekszik, a Cserhát dombjai között. A legközelebbi város a mindössze 10 kilométerre fekvő Rétság, míg a főváros és a megyeszékhely (Salgótarján) egyaránt körülbelül 70-70 kilométer távolságra fekszik. Különálló településrésze a központjától mintegy 4 kilométerre nyugatra található, ma már teljesen néptelen Világospuszta. A közvetlenül határos települések: észak felől Szátok, kelet felől Kétbodony, délkelet felől Legénd, dél felől Alsópetény, délnyugat felől Felsőpetény, nyugat felől Bánk, északnyugat felől pedig Tereske.'),
    ('Romonya', 'Pécs központjától keletre fekszik, nyugati szomszédja Bogád, keleti szomszédja Pereked, dél felől a legközelebbi település Ellend, északról pedig a Pécshez csatolt Hird. Romonya már a római korban és az avar korban is lakott volt. A falu határában e korokból származó leletek kerültek napfényre helyezkedik el. Nevét az oklevelek 1542-ben már a mai nevén említették.'),
    ('Románd', 'A falu a Sokorói-dombság déli lankáin és az északi Bakony vonulatai mentén lévő völgyben húzódik meg. Átlagos magassága a tengerszint felett 170-180 méterre van. Talaját agyagos, löszös homokdombok alkotják. A falun a Bornát-ér és a Rétkerti-patak folyik át, melyek érintik a község szélein lévő halastavat. Első említése körülbelül 1235-ből…'),
    ('Rozsály', 'A szomszédos települések: észak felől Tisztaberek, északkelet felől Kishódos és Nagyhódos, kelet felől Méhtelek, dél felől Zajta, nyugat felől pedig Gacsály. Közigazgatási határa a belterülettől délnyugatra, egy rövid, kevesebb, mint egy kilométeres szakaszon egybeesik az országhatárral, így ott Atya (Atea) községgel is határos. A környék jelentősebb, távolabb fekvő települései közül Csengersima 19, Csenger 25, Mátészalka pedig 55 kilométer távolságra található.'),
    ('Rudabánya', 'Nemzetközileg is ismert őslénytani lelőhely, továbbá itt található a Bányászattörténeti Múzeum, valamint a Borsodi Jegyzők Szakmai Egyesületének székhelye. Felszínét a Rudabányai-hegység alacsonyabb, részben erdőkkel fedett dombjai (például Szőlő-hegy) uralják. A település – amely már több ezer éve lakott vidéknek számít – közelében már az ókorban bányásztak vasércet és színesfémeket a kelták, akiket a kora középkorban a szlávok követtek.'),
    ('Rudolftelep', 'Ha a településen feljebb megyünk, akkor a meddőhányóhoz érünk, innen a Gerincnek is nevezett domb választja el Ormosbányától. Nevét Rudolf Cohachtról kapta. Ő volt az, aki bányatelkét az induló bánya-részvénytársaságnak adta. Róla kapta a Rudolf akna a nevét, majd a település is. A 19. század végén több vállalkozás is megpróbálta kitermelni a környéken található szénmezőket.'),
    ('Rum', 'A Rába bal partján fekszik, Szombathelytől 20 kilométerre délkeletre. A szomszéd települések: észak felől Meggyeskovácsi, kelet felől Kám, dél felől Alsóújlak, délnyugat felől Püspökmolnári és Zsennye, nyugat felől Rábatöttös, északnyugat felől pedig Csempeszkopács. Külterületei dél felé több kilométerre elnyúlnak a központjától, így abban az irányban határos még Vasvárral is.'),
    ('Ruzsa', 'A szomszédos települések: északkelet felől Üllés, kelet felől Zákányszék, délkelet felől Mórahalom, dél felől Ásotthalom, nyugat felől Öttömös, északnyugat felől pedig Pusztamérges. Ülléssel az 5433-as út, Pusztamérgessel az 5435-ös út köti össze. A mai Rúzsa területén…'),
    ('Rábacsanak', 'A falu kelet-nyugati irányban terül el. Fésüs település, a főutcára hat mellékutca fűződik fel. A község határát a Linkó-árok szeli át. Szannyal a 8408-as út köti össze. Első írásos említése 1351-ből való. Birtokosa a középkortól a győri püspökség, amelynek…'),
    ('Rábacsécsény', 'A szomszédos települések: észak felől Enese 8, északkelet felől Rábapatona 15 (légvonalban 6), kelet felől Mérges 5 (légvonalban 2,5), délkelet felől Rábaszentmihály 1,5, délnyugat felől Bodonhely 6 (légvonalban 3), nyugat felől Bágyogszovát 10 (légvonalban 6), északnyugat felől pedig Kóny 13 (légvonalban 6,5) kilométerre helyezkedik el. A megyeszékhely, Győr mintegy 21 kilométer távolságra található.'),
    ('Rábagyarmat', 'Oklevelekben először 1157-ben szerepel. Későbbi előfordulások: 1350 Gyrmath. 1548-ban szerepel Alsó- és Felsőgyarmath, 1576-ban Kis- és Nagy-Gyarmat. 1593 Utraque Gyarmat. Szentgotthárdtól 12 kilométerre keletre, a Rába termékeny völgyének déli peremén, a Vasi-Hegyhát erdeinek tövében fekszik. A Rábagyarmat és Rátót közötti Rába-híd a 20. században épült, addig csak néhány gázló és a vízimolnárok ladikjai biztosították az összeköttetést.'),
    ('Rábahídvég', 'A Rába bal partján fekszik, Vasvártól 5 kilométerre nyugat-északnyugatra. A szomszédos települések: észak felől Sorkifalud és Gyanógeregye, északkelet felől Püspökmolnári, délkelet felől Vasvár, délnyugat felől Egyházashollós, északnyugat felől pedig Nemesrempehollós. A település környéke már az őskorban is lakott volt, melyet bizonyítanak az itt talált mamutcsontok, ember által használt eszközök.'),
    ('Rábakecöl', 'A község belterületét a 8611-es és a 8428-as utak érintik, ezeken közelíthető meg a közvetlen szomszéd települések (Beled, Vásárosfalu és Kenyeri) irányából helyezkedik el. Az ország távolabbi részei felől a 86-os főúton vagy az M86-os autóúton érhető el a legegyszerűbben: mindkettő érinti a község északi határszélét, s az M86-os legközelebbi csomópontja alig 1,5 kilométerre esik Rábakecöl központjától.'),
    ('Rábapatona', 'A Kisalföldön fekszik, Győrtől 18 kilométerre Sopron irányában, a Rába és a Rábca által közrefogott területen. Belterülete a Rába bal (nyugati) parti oldalán helyezkedik el. Központja a főútról, illetve az M85-ös itteni csomópontjától letérve érhető el, a 84 128-as számú mellékúton. Rábapatona megállóhelye a belterület északi szélén helyezkedik el, a község központjától 3,5 kilométerre.'),
    ('Rábapaty', 'Sárvártól mintegy 6 kilométerre északra fekszik, a Rába folyó mellett. Keleti határában ered a Pereszteg-patak. A szomszédos települések: észak felől Jákfa, északkelet felől Ostffyasszonyfa, dél felől Sárvár (Rábasömjén), nyugat felől Ölbő, északnyugat felől pedig Zsédeny. Közigazgatási területe északnyugat felől, egy-egy rövid szakaszon érintkezik még Pósfa és Hegyfalu határszélével is.'),
    ('Rábapordány', 'Magyarország északnyugati részén, Csornától 9 kilométerre délkeletre található. A falu határa a Kisalföldre jellemző sík vidék, amelyet jellegzetes út menti nyárfasorok szabdalnak. A község főutcája a belterületén kelet-nyugati irányban végighúzódó 8423-as út, ezen közelíthető meg Bágyogszovát és Szilsárkány felől. Szláv személynévből származó nevét egy 1351-es okmány említi először „possessio Pardan” formában helyezkedik el.'),
    ('Rábasebes', 'Magyarország északnyugati részén, a Rába bal partján helyezkedik el, közel a tőle nyugatra található Vág településhez és a folyó másik oldalán vele szemközt elhelyezkedő Kemenesszentpéterhez. Közigazgatási területén, lakott területeitől északra áthalad a 8425-ös út, ezen érhető el Vág és Szany felől is. Központja vonatkozásában azonban zsáktelepülésnek tekinthető, mert csak az előbbi útból délnek kiágazó 84 133-as számú mellékúton érhető el.'),
    ('Rábaszentandrás', 'A megyeszékhely, Győr irányából a legegyszerűbb a 85-ös főutat (vagy az M85-ös autóutat) választani Csornáig, ott rátérni a 86-os főútra, utóbbiról Szilsárkány után lekanyarodni a 8408-as útra, onnét pedig Szany központjában rátérni a 8424-esre helyezkedik el. Egy másik, valamivel rövidebb, de több településen átvezető…'),
    ('Rábaszentmihály', 'A település a Rába jobb partján fekszik, a folyón átívelő híd mellett. A legközelebbi szomszédja a túlsó parton fekvő Rábacsécsény. A község Árpád-kori település, mely 2004. év augusztusában ünnepelte 800 éves fennállását. Az 1204-ből származó oklevél „Rába-földnek” nevezte, amit II.'),
    ('Rábaszentmiklós', 'Talaja jobbára laza, meszes homok, homokos öntésiszap, a Marcal és a Rába között kötött, agyagos szerkezetű. Uralkodó széliránya az északnyugati. Felszíne síkság, melyet kisebb, lapos hátak tesznek változatossá: a tengerszint feletti magassága 114–120 méter között váltakozik. A községet fennállása során többféle néven említették az írásos források.'),
    ('Rábatamási', 'Magyarország északnyugati részén, a Rábaközben helyezkedik el, a csornai kistérség nyugati részén. Határos a kapuvári kistérséggel. A község határa a településtől északra messze (több, mint 8 kilométerre) felnyúlik, ezt a hansági szabad területek meghódításának köszönheti. A vidéken 10-12 ezer év óta él ember. Kezdetben, a Hanság lápvilágában, majd az avar településeken helyezkedik el.'),
    ('Rábatöttös', 'A falu a Sorok-patak folyása közelében fekszik, Szombathelytől 17 kilométerre délkeletre. Neve valószínűleg a Tuet személynévből ered, ennek előzménye a tő (= növényi szár) főnév. Rábatöttöst 1274-ből, Gutaházát 1406-ből említik legkorábban az ismert okleveles források. Előbbinek templomát 1342-ben említi először oklevél.'),
    ('Rábcakapi', 'Magyarország északnyugati részén, Csornától 13 kilométerre helyezkedik el. A szomszéd települések: kelet felől Tárnokréti, dél felől Cakóháza, délkelet felől pedig Bősárkány. Észak felől több kilométeren át jánossomorjai, egy jóval rövidebb szakaszon pedig lébényi külterületekkel határos. Csak közúton közelíthető meg, legegyszerűbben a 85-ös vagy a 86-os főutak, illetve az M85-ös autóút felől.'),
    ('Rácalmás', 'A Duna jobb partján, Budapesttől mintegy 61 kilométerre délre, Dunaújvárostól 4 kilométerre északra található, A közvetlenül határos települések: észak felől Kulcs, északkelet felől Makád [a Csepel-szigeten], kelet felől Tass, délkelet felől Szalkszentmárton [mindkettő a Duna túlsó, bal partján], dél felől Dunaújváros, délnyugat felől Nagyvenyim, nyugat felől Perkáta, északnyugat felől pedig Adony.'),
    ('Ráckeresztúr', 'A község a Szent László-völgy alsó szakaszának bal partján helyezkedik el. A római korból nagy kiterjedésű településnyomok, az úgynevezett „római" híd és út maradványai tanúskodnak. Mindez azt mutatja, hogy a római korban egy belső út vezetett a Szent László-patak völgyében. A mai Dunántúl földje, amint a régészeti leletek mutatják, már 4500 évvel ezelőtt lakott volt.'),
    ('Ráckeve', 'A múltban is rendelkezett már városi ranggal, de azt valamikor a 19. században elvesztette és csak 1989-ben kapta meg újra. Budapesttől mintegy 50 kilométerre délre, a Csepel-szigeten, a déli irányban kitáguló Csepeli-síkon, a Ráckevei-Duna-ág mindkettő partján helyezkedik el. Itt található a folyóág legdélebbi, gépjárművel is igénybe vehető hidja, az 1896-ban épült Árpád híd.'),
    ('Rád', 'Vác és Penc között fekszik, Váctól 9 kilométerre keletre. A községen áthaladó helyközi autóbuszjáratok: 312, 334, 335, 336, 337, 338. A falu a 10. század végétől lakott település, nevét az I. István feleségével, Gizellával Magyarországra jött bajor lovagok egyike, Wassenburgi Vencellin fiáról, Rádról kapta. 1264-ben Rádi Simon V. István „ifjabb király” Hatvanban székelő alnádorának, a Szolnok nemzetségből származó Gothardnak volt kiküldötte Zagyvaszántón.'),
    ('Rádfalva', 'Harkány nyugati vonzáskörzetében helyezkedik el, a szomszédos települések: északkelet felől Diósviszló, délkelet felől Drávaszerdahely, dél felől Drávacsepely, délnyugat felől Drávapiski, nyugat felől Kórós, északnyugat felől pedig Hegyszentmárton. Rádfalva (Rád, Drávarád) nevét 1077-ben említették először az oklevelek, Drawa, Draua formában helyezkedik el.'),
    ('Rádóckölked', 'Két, egykor önálló falu, a Nagykölked szomszédságában fekvő Kiskölked és az Egyházasrádóc melletti Pusztarádóc egyesítésével jött létre. Körmendtől 8 kilométerre északra fekszik. A szomszédos települések: észak felől Ják, kelet felől Egyházasrádóc, dél felől Körmend, délnyugat felől Harasztifalu, nyugat felől pedig Nagykölked. Külterületei délkelet felé messze elnyúlnak a község központjától, így abban az irányban határos még Magyarszecsőddel és Molnaszecsőddel is.'),
    ('Ráksi', 'Igaltól délre, Szentgáloskér, Igal és Magyaratád közt fekszik. Észak-déli irányban a Kaposvár-Szántód közti 6505-ös út halad rajta keresztül, nyugati irányban, Mernye felé a 6513-as út indul innen helyezkedik el. Szántódtól, a Balaton partjától 40 kilométerre fekszik, míg Kaposvártól körülbelül 24 kilométerre. Budapesttől való távolsága légvonalban 140 kilométer, közúton 160 kilométer, ez autóval legalább 2–2,5 órás utazást jelent. 154-172 méter magasan fekszik, főutcája észak-déli irányban nyúlik el, míg mellékutcái erre merőlegesen húzódnak.'),
    ('Rákóczibánya', 'Összes belterülete mintegy 52,5 hektár. A Novohrad-Nógrád UNESCO Globális Geopark települései közé tartozik. A szomszédos települések: észak felől Kazár, délkelet felől Nemti, délnyugat felől Bátonyterenye kisterenyei településrésze, északnyugat felől pedig Vizslás. Szomszédai közül Kazár esik hozzá a legközelebb, a két község központja között mintegy három kilométer a távolság.'),
    ('Rákóczifalva', 'Rákóczifalva a Tisza bal partján Szolnoktól délre, a folyótól távolabb fekszik. Északon Szolnok, keleten Kengyel, délen Rákócziújfalu a szomszédja. A tiszaroffi víztározó építését megelőző régészeti kutatások felderítették, hogy az áradásoktól védett tisza-parti területet az őskortól lakják.'),
    ('Rákócziújfalu', 'A községtől délnyugatra folyik a Tisza, medre itt írja le a Közép-Tisza-vidék hatalmas kanyarulatát (vezseny-martfűi kanyar). A legközelebbi szomszédos települések észak felől Rákóczifalva, dél felől pedig Martfű, de közigazgatási területe határos még Vezsennyel és Kengyellel is. Az autóbuszos közúti közösségi közlekedést a Volánbusz szolgáltatja. A település a középkori (Tisza)Varsány (amely 1691-ben egy tatárdúlás, illetve a Rákóczi-szabadságharc idején egy rác…'),
    ('Rápolt', 'A Szatmári-síkság délkeleti csücskében, a Szamos folyó partján épült, mintegy 172 lakosú pici település a megyeszékhely Nyíregyházától 78, a környező települések közül Győrtelektől 9, Ököritófülpöstól pedig 4 kilométer távolságra található. A település neve 1366-ban egy idevaló királyi ember nevében tűnik fel először az oklevelekben, Rapolt alakban helyezkedik el.'),
    ('Rásonysápberencs', 'A megye leghosszabb nevű települése (Sátoraljaújhelynél 1 karakterrel hosszabb, de mindkettő 14 betű). A Cserehát tájegység délkeleti részén helyezkedik el, a Vasonca-patak völgyében, a megyeszékhely Miskolctól 30 kilométerre északkeletre. A közvetlenül szomszédos települések: észak felől Detek, kelet felől Ináncs, dél felől Léh, nyugat felől Monaj, északnyugat felől pedig Selyeb.'),
    ('Rátka', 'A Zempléni-hegység délnyugati lejtői alatt fekszik, a Tokaji borvidéken, a megye székhelyétől, Miskolctól 42 kilométerre északkeletre. A közvetlen szomszédos települések: észak felől Tállya, délkelet felől Mád, dél felől pedig a Szerencshez tartozó Ond. Északnyugat felől a legközelebbi település Golop, de közigazgatási területeik nem érintkeznek egymással.'),
    ('Rátót', 'Rátót a hagyomány szerint eredetileg Gasztony majora volt. 1428-ben Rathodfolua néven említik először, ekkor Péter deáknak 4 adózó jobbágyportáját említik a helységben. Neve a régi magyar Ratolt személynévből származik, melynek előzménye a német Ratold személynév. 1460-ban Poss. Ratholthfalwa, 1482-ben "Poss. Ratholthfolua al. nom. Vnakatheleke" néven említik.'),
    ('Réde', 'Ezt az ideális földrajzi fekvésű vidéket már a magyar írásbeliség kezdeténél régebbi idők óta lakják, és az itt élők számára mindig biztos megélhetést és barátságos otthont adott. Az idelátogatók számára a tiszta erdei levegő a tavakkal, patakokkal, tarka vadvirágos rétekkel gazdagon díszített természeti környezet felüdítő helyszín a túrázásra. Tamási Áron így ír: „Azért vagyunk a világon, hogy valahol otthon legyünk benne”.'),
    ('Rédics', 'Rédics a Hetés tájegységben fekszik, a szlovén határ mellett. Közigazgatási határa dél és délnyugat felől mintegy 9 kilométer hosszan egybeesik az országhatárral. Különálló településrészei Dedeskecskés és Felsőlenke, a központjától délkeletre helyezkedik el.'),
    ('Rém', 'Bajától mintegy 22 kilométerre keletre helyezkedik el. A szomszédos települések: észak felől Érsekhalma, kelet felől Borota, délkelet felől Felsőszentiván, dél felől Csávoly, nyugat felől Sükösd, északnyugat felől pedig Nemesnádudvar. A korabeli feljegyzésekben már az 1400-as évek elején szerepel Rym néven a település mint puszta. A török megszállásig a környék egyik legnagyobb falva volt, ahol az itt lakó jobbágyság állattenyésztéssel és gabonatermesztéssel foglalkozott.'),
    ('Répcelak', 'A Kisalföld déli részén fekszik, a Rábával itt párhuzamosan futó Répce jobbparti oldalán. A szomszédos települések: észak felől Csánig, kelet felől Rábakecöl, dél felől Nick, délnyugat felől Vámoscsalád, északnyugat felől pedig Répceszemere helyezkedik el. Közigazgatási határa a fentieken túlmenően, észak felől egy rövid szakaszon érintkezik Dénesfa területével is.'),
    ('Répceszemere', 'Természetföldrajzi szempontból a Répce-síksághoz tartozik, amely ebben a térségben a sűrű völgyhálózat révén enyhén hullámos felszínű táj. A környék eredeti természetes növénytakaróját már csak a közeli csáfordjánosfai védett keményfás ligeterdő őrzi. Kevés híja van annak, hogy nem határos kelet felől még Csániggal is. A környék nagyobb városai közül Sárvár 25, az Alpokalján fekvő kisváros, Kőszeg 35, Szombathely 38, Sopron pedig 50 kilométerre fekszik.'),
    ('Répceszentgyörgy', 'A szomszédos települések: kelet felől Hegyfalu, dél felől Pósfa, délnyugat felől Szeleste, nyugat felől Gór, észak felől pedig a Répce bal partján fekvő Chernelházadamonya. A megyeszékhely, Szombathely körülbelül 25 kilométerre, Sárvár, illetve Répcelak egyaránt nagyjából 15–15 kilométerre található. A közúti tömegközlekedést a Volánbusz autóbuszai biztosítják.'),
    ('Répcevis', 'Kőszeg közelében, közvetlenül a magyar–osztrák határ mellett fekszik, a Kisalföld és az Alpokalja találkozásánál. A szomszédos települések a határ magyar oldalán: észak felől Zsira, kelet felől Gyalóka, délkelet felől Szakony, délnyugat felől pedig Peresznye. Északnyugat felől Ausztriához tartozó területek határolják, a legközelebbi település abból az irányból Locsmánd (Lutzmannsburg).'),
    ('Répáshuta', 'A két legközelebbi település: Bükkszentkereszt 11 kilométerre keletre és Felsőtárkány 23 kilométerre délnyugatra helyezkedik el. Határos még észak felől Miskolc legnyugatibb külterületeivel, délkelet felől Kisgyőrrel, dél felől Cserépfaluval, délnyugat felől Bükkzsérccel, északnyugat felől pedig Nagyvisnyóval is. Autóbusszal az 1383-as és a 3755-ös járatokkal érhetjük el a települést.'),
    ('Rétalap', 'Szomszédos települések Bőny mellett Bana, Tárkány, Kerékteleki, Mezőörs. Korábban zsáktelepülés volt, teljes szélességű közúti összeköttetése ma is csak Bőnnyel van, ahonnan a 8136-os útból, annak 36+700-as kilométerszelvényénél dél-délkelet felé kiágazó 81 138-as út vezet a településre. A falu éghajlata erősen kontinentális jellegű. Az éves csapadékmennyiség 550–570 milliméter.'),
    ('Rétközberencs', 'A mai nevét 1898-ban vette fel, korábban Berencs néven említették. Írásos dokumentumokban 1289-ben olvasható először a Berencs névvel, de már kb. 5000 éve is lakott terület volt. A régészeti kutatások során több újkőkori edény és szerszám, bronzkori harcicsákány és arany ékszer került elő, valamint teljes épségben két honfoglalás kori sírt sikerült megmenteni az utókor számára helyezkedik el.'),
    ('Rétság', 'A megye legkisebb közigazgatási területű és lélekszámú városa. Budapesttől 55, Balassagyarmattól 25 kilométerre található, a Börzsöny és a Cserhát határán elhelyezkedő Nógrádi-medencében. Ez az adottság határozza meg a környék jellegét is. A szomszédos települések: észak felől Borsosberény, kelet felől Bánk, délkelet felől Felsőpetény, dél felől Nőtincs, nyugat felől Tolmács, északnyugat felől pedig Diósjenő.'),
    ('Révfülöp', 'A település és környéke a második világháború után vált kedvelt balatoni üdülőhellyé. Az évente megrendezett és hagyományos tömegrendezvénnyé vált Balaton-átúszó versenyt a Révfülöp és Balatonboglár közé eső 5,2 kilométeres távon rendezik, ez is rengeteg látogatót vonz a településre.'),
    ('Révleányvár', 'Sátoraljaújhelytől délkeletre, Ricse keleti szomszédjában, a Tisza mellett fekvő település. Nevének első tagja a Tisza itteni révje után kapta nevét, míg nevének második tagja földváráról kapta nevét, melyet a Tisza túlsó partján fekvő Kisvárda várurai a folyón való átkelés biztosítására 1440-ben várat emeltek ide, melyet Várdai László jegyese Pálóczi Agatha tiszteletére először Szűzvár-nak, később pedig Leányvár-nak neveztek el.'),
    ('Rózsafa', 'Szigetvártól keletre helyezkedik el, Nagypeterd déli szomszédságában. A további szomszédos települések: kelet felől Szentdénes, délkelet felől Sumony, dél felől Bánfa, délnyugat felől Katádfa, nyugat felől Dencsháza, északnyugat felől pedig Botykapeterd. Csak közúton érhető el, az 58 104-es számú mellékúton, a 6-os főútról Nagypeterdnél letérve. A település neve a hagyományok szerint az Árpád-korban Vidusfalva, Vitusfa volt.'),
    ('Rózsaszentmárton', 'A megye nyugati részén, a 2402-es és a 2404-es utak találkozásánál, Gyöngyöstől nyugatra, Ecséd, Petőfibánya, Apc és Szűcsi között fekvő település. Rózsaszentmárton, korábbi nevén Fancsal már az őskorban is lakott hely volt. Kőkorszakbeli emlékek kerültek elő a község határából helyezkedik el. A falu keletkezésének feltételezett időpontja az 1000-től 1050-ig terjedő időszakra esik.'),
    ('Röjtökmuzsaj', 'Soprontól mintegy 30 kilométerre délkeletre fekszik. A közvetlenül szomszédos települések: észak felől Hegykő, északkelet felől Fertőszentmiklós, dél felől Pusztacsalád, délnyugat felől Sopronkövesd, nyugat felől Ebergőc, északnyugat felől pedig Nagylózs. Éghajlata mérsékelt égövi, kedvező, csapadékos, jó adottságú a mezőgazdasági termeléshez helyezkedik el.'),
    ('Rönök', 'Fontos útja még a 7453-as út, amely Őriszentpéterrel köti össze. Neve szláv eredetű lehet. Az egyik változat szerint a ribnik (= halastó) főnévből, a másik szerint a Rudnik szláv helynévből, melynek előzménye a ruda (= érc) főnév származik. 1336-ban már külön említik Alsó- és Felsőrönököt is Olsowryunuk, Felseuryunuk alakban. 1360-ban Runuk, 1413-ban Rednek, 1415-ben Rewnek, 1422-ben Renuk néven említik oklevelek.'),
    ('Röszke', 'Röszke a Tisza folyó és a déli országhatár mentén terül el. Központja Szeged belvárosától 11 kilométerre, az országhatártól pedig mintegy 3 kilométerre terül el. Északkelet, kelet és délkelet felől Szegedhez tartozó külterületi határrészek övezik, délnyugati szomszédja a már Szerbiához tartozó Horgos, nyugat felől Mórahalommal, északnyugat felől pedig Domaszékkel határos.'),
    ('Sajtoskál', 'Sárvártól 18 kilométerre északnyugatra fekszik, a Metőc-patak mentén. A szomszédos települések: észak felől Simaság, északkelet felől Iván, kelet felől Nemesládony, délkelet felől Tompaládony, dél felől Mesterháza, délkelet felől pedig Chernelházadamonya. Nyugat felől az amúgy távolabb eső Bőhöz tartozó, lakatlan külterületek határolják, abból az irányból a legközelebbi település Lócs, de utóbbival a közigazgatási területeik nem érintkeznek.'),
    ('Sajóbábony', 'Az ország egyetlen városi ranggal rendelkező zsáktelepülése (amely ráadásul csak egy öt számjegyű mellékúton [a 25 138-as úton] érhető el). Sajóbábony Miskolctól 13 kilométerre északra, a Bükk-vidéken, a Tardonai-dombság és a Sajó-medencének a találkozásánál helyezkedik el. A település két markánsan elkülönülő részre oszlik: a falura és a lakótelepre helyezkedik el.'),
    ('Sajóecseg', 'A Sajó-völgyben, a Sajó és a Bódva folyók találkozásánál fekszik, Miskolctól körülbelül 10 kilométer közúti távolságra, a Bükk-vidék keleti peremén. A Sajó folyó több ágra bomlik Sajóecseg területén. A települést délről a - sajóbábonyi egykori Észak-Magyarországi Vegyiművek közeléből érkező - Bábony-patak határolja, amely nyugati irányból ugyancsak a falu területén ömlik a Sajóba.'),
    ('Sajógalgóc', 'A Sajó bal partján, Kazincbarcika vonzáskörzetében fekszik, a várostól 10 kilométerre nyugatra, Putnoktól hasonló távolságra keletre. A megyeszékhely Miskolctól 35 kilométerre északnyugatra, Ózdtól 30 kilométerre északkeletre található. A közvetlenül határos települések: észak felől Dövény, kelet felől Sajókaza, délkelet felől Vadna, délnyugat felől Sajóvelezd, nyugat felől pedig Dubicsány.'),
    ('Sajóhídvég', 'Nevével ellentétben nem a Sajó partján fekszik, feltehetően a folyó évszázadokkal korábban keletebbre folyt, a Hernád torkolata pedig északabbra volt a mainál. A közvetlenül határos települések: észak felől Berzék, északkelet felől Tiszalúc, dél felől Köröm, nyugat felől pedig Ónod. A fentieken túl keleten érintkezik a határa még Girincs területével is.'),
    ('Sajóivánka', 'Kazincbarcikától 5, Miskolctól 27 kilométer távolságra fekszik, a Sajó völgyében. A környező települések: észak felől Sajókaza, kelet felől Kazincbarcika, délnyugat felől Nagybarca, nyugat felől pedig Vadna. Sajókazával és azon keresztül Aggtelek térségéével a 2603-as út köti össze. A község nevével írásban először a Váradi regestrumban találkozhatunk 1222-ben.'),
    ('Sajókaza', 'Miskolctól 26 kilométerre északnyugatra, a Sajó bal partján fekszik. A közvetlenül szomszédos települések: észak felől Felsőnyárád, északkelet felől Kurityán, kelet felől Szuhakálló, délkelet felől Kazincbarcika, dél felől Sajóivánka, délnyugat felől Vadna, nyugat felől Sajógalgóc, északnyugat felől pedig Dövény és Jákfalva. Neve vagy magyar törzsnévből, vagy az ótörök eredetű Quaz személynévből származik, mások szerint azonban az ószláv koza (= kecske) főnévből való. 1231-ben Kaza néven említik először.'),
    ('Sajókeresztúr', 'Miskolctól északra, Szirmabesenyő és Sajóecseg között fekszik. Az őskortól lakott település. Egyike azoknak a Sajó menti, Bükk-vidéken található településeknek, amelyeket a 13–14. században a szőlőművelés, a bortermelés és a kereskedelem indított el a mezővárosi fejlődés útján. Első írásos említése a Miskolc nemzetség birtokainak összeírásából, a 14–15. századból származik Kerestwr formában helyezkedik el.'),
    ('Sajókápolna', 'Sajószentpétertől délnyugatra, a parasznyai völgy alján fekszik. További szomszédos települések: délkelet felől Sajóbábony, dél felől Sajólászlófalva, délnyugat felől Kondó, északnyugat felől pedig Alacska. Sajókápolna nevét 1317 és 1342 között említette először oklevél p.'),
    ('Sajólád', 'Az aktív keresők mintegy 90%-a Miskolcon és Tiszaújvárosban dolgozik. A Sajó mentén helyezkedik el. Teljes lakott területe és közigazgatási határának nagy része a bal parti oldalon, de egy viszonylag nagy (több mint 5 négyzetkilométernyi) területével átnyúlik a folyó túlsó partjára is. A közvetlenül határos települések: észak felől Alsózsolca, északkelet felől Hernádnémeti, kelet felől Bőcs, délkelet felől Berzék, dél felől Ónod, délnyugat felől Nyékládháza és Mályi, nyugat felől pedig Sajópetri.'),
    ('Sajólászlófalva', 'A település a Bükk-vidék északi részén, a Tardonai-dombság területén fekszik, 21 kilométerre Miskolctól. A festői dombokkal övezett, erdőkkel borított Pitypalatty-völgyben elhelyezkedő hat község (Varbó, Parasznya, Radostyán, Kondó, Sajólászlófalva és Sajókápolna) egyike, amelyek szinte egymásba karolva adnak otthont az ott élőknek és kínálnak látnivalókat a térségbe látogatóknak.'),
    ('Sajómercse', 'A megye nyugati részén helyezkedik el, Ózdtól kelet-északkeleti irányban, Putnoktól délre. Belterülete az Upponyi-hegység északi részén alacsony hegyvonulatok közé zárva, a Királd-patakon át, a Sajóba ömlő Mercsei-patak völgyében épült fel. Felszínét döntően felső miocén riolittufa fedi, hasznosítható nyersanyaga a barnaszén, területén jelentős az erdők aránya.'),
    ('Sajónémeti', 'Határszélét délkeleten érinti még a 2525-ös út is. Neve német település emlékét őrzi. A község neve először 1219-ben fordul elő Nemhy alakban írva, a Váradi regestrumban helyezkedik el. A 13. században Nymti, Nymthy, Nemti alakot találunk. 1413-ban már Nemethy, s a 15. századtól már mint Sajónémeti szerepel. Önálló pallosjoggal bíró település volt.'),
    ('Sajópetri', 'Miskolc agglomerációjának délkeleti részén helyezkedik el, a Sajó jobb parti oldalán, Kistokajtól mintegy 5 kilométerre. A közvetlenül határos települések: észak felől a Sajó túlpartján elterülő Alsózsolca, kelet felől az épp átellenben fekvő Sajólád, nyugat felől Kistokaj, északnyugat felől pedig a Miskolchoz tartozó Szirma. Dél felől a legközelebbi település Ónod, délnyugat felől pedig Mályi, de közigazgatásilag egyikkel sem határos.'),
    ('Sajópálfala', 'A Sajó völgyében fekszik, a megyeszékhely Miskolctól 12 kilométer-re északkeletre. A közvetlenül határos települések: északkelet felől Szikszó, dél felől Arnót, délnyugat felől Szirmabesenyő, északnyugat felől pedig Sajóvámos. Közösségi közlekedéssel a Volánbusz által üzemeltetett 3706-os busszal közelíthető meg. A települést 1320-ban említik először, akkor még Pálfalva néven helyezkedik el.'),
    ('Sajópüspöki', 'Ózdtól 12, Putnoktól 10 kilométer távolságra helyezkedik el. A község szlovák határ menti oldalát dombok övezik, másik oldalán folyik a Sajó. A Sajó-völgy településeként a felszínét nagy részben folyóvízi homok, kavics, teraszkavics, kisebb részben lösz és glaciális vályog fedi. Éghajlata a mérsékelten nedves típushoz közelít, ezért a megművelhető területeken a szántóföldi és a kevésbé meleg igényes kertészeti növények termesztését részesítik előnyben.'),
    ('Sajósenye', 'A Sajó völgyében fekszik, a megyeszékhely Miskolctól kb. 12 kilométer-re északkeletre. A közvetlenül határos települések: délkelet felől Sajóvámos, délnyugat felől Sajókeresztúr, nyugat felől Sajóecseg, északnyugat felől pedig Boldva. Már az Árpád-korban létezett. Akkoriban jelentős településként tartották számon, ami később sem változott. Az 1300-as években Sene, Scienne néven található.'),
    ('Sajószentpéter', 'Különálló belterületi településrésze Dusnokpuszta, a központjától mintegy 2-2,5 kilométerre északra helyezkedik el. Miskolctól 13 kilométerre fekszik, nem messze a Sajó és a Bódva találkozásától A közvetlenül határos települések: észak felől Edelény, északkelet felől Borsodszirák és Ziliz, kelet felől Boldva, délkelet felől Sajóecseg, dél felől Sajóbábony, délnyugat felől Sajókápolna, nyugat felől Alacska, északnyugat felől pedig Berente és Múcsony.'),
    ('Sajószöged', 'A további szomszédos települések: észak felől Girincs, északkelet felől Sajóörös, dél felől Nemesbikk, délnyugat felől Hejőbába, nyugat felől Szakáld, északnyugat felől pedig Nagycsécs. Sajószöged megállóhely a belterület déli szélén létesült, közúti elérését csak önkormányzati utak biztosították. Neve személynévből keletkezett, alapja a szög = szeg, amely személynévnek is használatos volt (cegu).'),
    ('Sajóvelezd', 'Kazincbarcika és Putnok között fekszik, utóbbi délkeleti szomszédságában, mintegy 4 kilométerre, a Sajó jobb parti, déli oldalán. Belterülete a folyóba torkolló mercsei és királdi völgy betorkolásától keletre alakult ki. Az árterület jó mezőgazdasági művelést biztosít, míg a hegység keleti és nyugati lejtőin gyümölcs- és szőlőtermelést lehet folytatni.'),
    ('Sajóvámos', 'A település viszonylag sík területen helyezkedik el. Határában több patak is folyik, így Diós-patak, a Hosszúvölgyi-patak és a Kis-Sajó. A község felszínének legelterjedtebb képződménye a folyami kavics. A közúti kapcsolatok terén is szomszédosnak tekinthető települések: északnyugat felől Sajósenye (1 kilométer), dél felől Sajópálfala (1 kilométer), délnyugat felől pedig Szirmabesenyő (4 kilométer).'),
    ('Sajóörös', 'A Sajó folyó jobb partján terül el, Tiszaújváros északi-északnyugati szomszédságában. További határos települések: nyugat felől Sajószöged, észak felől pedig Kiscsécs és Kesznyéten (e két utóbbi település a folyó túlsó partján fekszik). Az ország távolabbi pontjai felől a legegyszerűbben a 3-as főúton, majd Nyékládháza után a 35-ös főúton közelíthető meg, Sajószöged központjában északkelet felé letérve.'),
    ('Salföld', 'A Balatontól körülbelül 3 kilométerre északra fekszik. A területen már 900 körül megjelentek a honfoglaló magyarok: a dimbes-dombos vidék Kál horka, majd Vérbulcsú nemzetségek szálláshelye volt. Később Koppány vezéré lett ez a földterület. Az Árpád-házi királyok idején Salkőkútnak nevezték, valószínűleg azért, mert az egyik legismertebb birtokos, az Atyusz nemzetségbeli tagja, Sal (Saul) volt, akitől fennmaradt két végrendelet (1221-ből és 1227-ből), mint hiteles írásbeli dokumentum.'),
    ('Salgótarján', 'Salgótarján Észak-Magyarországon helyezkedik el. A Salgótarján név a Salgó és a Tarján nevek összetételéből keletkezett. A Salgó a közeli Salgó várra utal, mely név a salgó (ragyogó, fényes) melléknévből származik. A Tarján a honfoglaló magyar törzsek egyikének a neve volt, mely ótörök eredetű szó, jelentése fejedelem, alkirály. Salgótarján a Novohrad-Nógrád UNESCO Globális Geopark települése.'),
    ('Salköveskút', 'A mai formájában 1935-ben jött létre, Salfa és Köveskút falvak egyesítésével. A Gyöngyös-sík északi részén, Szombathelytől 10 kilométerre északkeletre fekszik. Sopron térsége felől Vasasszonyfa érintésével közelíthető meg, a 8639-es, majd a 8643-as úton helyezkedik el. Közigazgatási határszélén, központjától több kilométerre északkeletre elhalad még a 8636-os út is.'),
    ('Salomvár', 'A településen polgárőrség működik. Salomvár története az Árpád-házi királyok uralkodásának idejére vezethető vissza. 1213-ban miután Gertrudis (Gertrúd) királynét meggyilkolták, a királyi gyermekeket, köztük Béla herceget (a későbbi IV. Béla királyt) a Vasvári ispán Miska és fia Salamon rejtették el. András halicsi hadjáratáról visszatérve köszönetképpen megajándékozta őket.'),
    ('Sand', 'Nagykanizsától légvonalban 10 kilométerre kelet-délkeletre található. A falu története két részre osztható. Az első rész az alapítástól az 1700-as évek közepéig tart. A török megszállás és a mértéktelen adóztatás következtében a település elnéptelenedett, pusztasággá vált. A második rész 1745-től, az újra megtelepedéstől napjainkig tart. Az első ismert írásos említés Sandról 1372-ből származik, ahol az akkori feljegyzések alapján Sond néven említik a települést.'),
    ('Sarkad', 'Gyulától északkeletre körülbelül 14 kilométerre, természetföldrajzi szempontból a Körös menti sík délkeleti peremén, a Fekete-Körös jobb partján, a Kis-Sárrét szomszédságában terül el. Közigazgatási területei észak-déli irányban aránylag hosszan elnyúlnak, így bár a város északi szomszédja Sarkadkeresztúr, északi irányból határos még Okánnyal is. További szomszédai: északkelet felől Méhkerék, kelet felől Kötegyán, dél és délnyugat felől Gyula, nyugat felől Doboz, északnyugaton pedig Tarhos.'),
    ('Sarkadkeresztúr', 'Sarkad északi szomszédságában fekszik, természetföldrajzi szempontból a Kis-Sárrét déli peremén, a Körös menti sík szomszédságában. További szomszédai: észak felől Okány, északkelet felől Mezőgyán (Nagygyanté), kelet felől Újszalonta, délkelet felől pedig Méhkerék. Nyugat felől, egészen az okányi határszélig Sarkadhoz tartozó, jobbára lakatlan külterületek határolják.'),
    ('Sarród', 'A község jelenlegi településrészei három volt településből álltak össze: Sarródból, Fertőújlakból és Nyárligetből. Fertőújlak neve az 1970-es névváltozást megelőzően Mekszikópuszta (Mexikópuszta) volt. Nyárliget a korábbi Nyárasmajor elnevezésből keletkezett.'),
    ('Sarud', 'A szomszédos települések: észak felől Újlőrincfalva, délnyugat felől Tiszanána, nyugat felől pedig Kömlő. Északnyugat felől Besenyőtelekhez tartozó külterületekkel határos. Nevében valószínűleg Sarolt(u) fejedelemasszony neve rejlik. Béla király oklevelében egyház utótaggal mint nemesi birtokot lehet fellelni. . A 13. században a Tomaj nemzetség birtoka volt. 1327-ben Károly Róbert király mint lakatlan királyi birtokot adta cserébe az egri püspökségnek a tőle északkeletre fekvő Hídvég (ma Pusztahídvég) vámjával együtt.'),
    ('Segesd', 'Segesd Belső-Somogy egyik, több mint ezeréves történelmi múlttal rendelkező nagyközsége, Nagyatádtól 13 kilométerre északra. Itt ered a Drávát tápláló Rinya-patak egyik ága. A mai község központi részét Alsó- és Felsősegesd alkotja. Különálló településrészek még Felsőbogátpuszta, a központtól keletre és Lászlómajor a település északkeleti széle közelében helyezkedik el.'),
    ('Sellye', 'Az ország egyik legdélebbi fekvésű tájegységének, az Ormánságnak a központja és legnagyobb lélekszámú települése, nevezik az Ormánság fővárosának is. Szigetvártól mintegy 20-25 kilométerre délre, a Dráva-síkon, az Ormánságban helyezkedik el. A tájegység központjának tekinthető. 1997 óta bír városi ranggal. A szomszédos települések: észak felől Kákics, kelet felől Csányoszró, délkelet felől Zaláta, dél felől Sósvertike, délnyugat felől Drávaiványi, nyugati irányból pedig Bogdása.'),
    ('Selyeb', 'Szikszótól északra, Abaújszolnok és Monaj közt fekszik. Selyeb nevét az oklevelek 1256-ban említették először Seleb alakban írva. A település nemesi birtok volt. 1256-ban Monajkeddel és Nyéstával volt határos. 1332-ben a pápai tizedjegyzék szerint papja 10 garas pápai tizedet fizetett. Selyeb birtokosa volt Péchy István és a Tisza család is, melynek itt 1713-ban épült kastélya.'),
    ('Semjén', 'A Bodrogköz magyarországi részének északi szélén fekszik, közvetlenül a magyar-szlovák határ mellett. A szomszédos települések: kelet felől Lácacséke, dél felől Ricse, nyugat felől pedig Kisrozvágy. A határ túloldalán a legközelebbi helység a szlovákiai Kisgéres (Malý Horeš). Csak közúton érhető el, Pácin és Zemplénagárd felől a 3807-es, Ricse felől pedig a 3808-as úton.'),
    ('Semjénháza', 'A község nagyobbik része egy elnyúló dombháton terül el, melyet az Újkúti- és a Rigyáci-patak határol. Szent Anna kápolna, a község legrégebbi építménye (kb.1905-ben épült) Szent Anna római katolikus templom (épült 1998-99) I-II. világháborús hősi emlékmű A település régóta lakott hely. A középső rézkor temetkezését csak innen ismerjük, a régészek hamvasztásos sírokat is találtak.'),
    ('Seregélyes', 'Seregélyes híres kastélyáról, mely a szomszédos Zichyújfalut is egykor birtokló Zichy család tulajdonában volt. Seregélyes és Zichyújfalu földesura (így a két település is) közeli kapcsolatban és rokonságban állt egymással. Ma a nagyközséghez több kisebb különálló településrész is tartozik, ezek közül a legnagyobb Szőlőhegy (egykori nevén Józan), ahol a nagyközség népességének csaknem egynegyede él.'),
    ('Serényfalva', 'A Putnoki-dombságban, a Keleméri-patak völgyében fekszik, nem messze a szlovák határtól. Ózdtól 15 kilométer, Miskolctól 42 kilométer választja el. A települést először a 13. század elején említik a krónikák. Ekkor a Hanva nemzetség birtokolta, elsősorban pásztorkodásra…'),
    ('Siklós', 'Hozzá tartozik Máriagyűd is. A Villányi-hegységtől délre, az Alföld legnyugatibb kiszögellésén, a Nyárád–Harkányi-síkon található. Szomszédságában nyugatra terül el a hozzá legközelebb fekvő város, Harkány. A további települési szomszédai: észak felé Kistótfalu, északkelet felé Vokány, kelet felé Nagytótfalu és Kisharsány, délkelet felé Egyházasharaszti és Alsószentmárton, dél-délnyugat felé Matty és Gordisa, északnyugat felé pedig Túrony és Bisse.'),
    ('Siklósbodony', 'Siklós vonzáskörzetének nyugati részén helyezkedik el, a várostól légvonalban 15, közúton mintegy 18 kilométerre nyugat-északnyugati irányban. A szomszédos települések: észak felől Kisdér, északkelet felől Ócsárd, délkelet felől Babarcszőlős, nyugat felől pedig Hegyszentmárton helyezkedik el. Csak közúton érhető el, a Túrony-Bogádmindszent közti 5815-ös úton.'),
    ('Siklósnagyfalu', 'Siklóstól délkeletre helyezkedik el, nem messze a déli (horvát) országhatártól. A szomszédos települések: észak felől Nagyharsány, kelet felől Kistapolca, délkelet felől Beremend és Kásád, dél felől Old, délnyugat felől Egyházasharaszti, északnyugat felől pedig Kisharsány. Határszélét délkeleten egy aránylag hosszabb szakaszon érinti még az 5708-as út is.'),
    ('Sikátor', 'Győrtől 35 kilométer-re délkeletre, Veszprémtől 46 kilométer-re északra van. Zirc 27, Kisbér 21 kilométer-re fekszik. Azon hat település egyike, amelyeket Veszprém megye Zirci kistérségéből a Győr-Moson-Sopron megyei Pannonhalmai kistérségbe csatoltak át 2002. október 20-án. A település első írásos említését 1392-ben találhatjuk meg, Sykator alakban.'),
    ('Sima', 'A Zempléni-hegység nyugati részén helyezkedik el, Abaújszántótól északkeletre. A közvetlen szomszédos települések: észak felől Baskó, délkelet felől Erdőbénye, délnyugat felől Abaújszántó, nyugat felől Abaújkér, északnyugat felől pedig Boldogkőújfalu. Csak közúton érhető el, Abaújkér vagy Erdőbénye érintésével a 3705-ös úton [illetve Abaújszántótól Abaújkér-Aranyospusztáig a 3714-es, onnan pedig ugyancsak az előbbi úton].'),
    ('Simaság', 'Sárvár és Nagycenk között nagyjából félúton fekszik, előbbitől mintegy 20 kilométerre északra, utóbbitól 22 kilométerre délre. A környék legnagyobb városától, Soprontól 35 kilométerre délkeletre helyezkedik el. A szomszédos települések: észak felől Újkér, kelet felől Iván, dél felől Sajtoskál, délnyugat felől Lócs, nyugat felől pedig Iklanberény. Határa délnyugaton, egy rövid szakaszon érintkezik még az amúgy távolabb fekvő Bő közigazgatási határszélével is.'),
    ('Simonfa', 'A megyeszékhely Kaposvár déli szomszédságában fekszik, a Zselicben. A közvetlenül határos települések: észak felől Kaposvár, északkelet felől Cserénfa, kelet felől Kaposgyarmat, dél felől Bőszénfa, északnyugat felől pedig Zselicszentpál. A 67-esről három helyen is le lehet térni a falu belsőbb részei felé, de oda a főúttól csak önkormányzati utak vezetnek.'),
    ('Simontornya', 'A megye kilencedik legnépesebb települése, 1995-ben kapott városi rangot. A Tolnai-Hegyhát északi csücske és a Mezőföld határán található. A közvetlenül határos települések: északkelet felől Sáregres, délkelet felől Pálfa, dél felől Kisszékely, délnyugat felől Tolnanémedi, északnyugat felől pedig Igar. Kelet felől a legközelebbi település Cece, de a közigazgatási területeik (nagyon kevés híján) nem érintkeznek.'),
    ('Sirok', 'A közvetlenül határos települések: észak felől Bükkszék, északkelet felől Bátor, kelet felől Egerbakta, délkelet felől Egerszólát, dél felől Tarnaszentmária, élnyugat felől Verpelét, nyugat felől Recsk, északnyugat felől pedig Szajla. A település határszélét északnyugaton érinti még a 24…'),
    ('Sitke', 'Sárvár keleti szomszédságában fekszik, a város központjától mintegy 8 kilométerre. A ma közel hétszáz lakosú települést 1946-ban Kissitke és Nagysitke egyesítésével hozták létre helyezkedik el. Első okleveles említése Sitka néven 1251-ből való. A korai település a 15. században vált ketté, addig a Sitkei család birtoka volt. Nagysitke 1426-ban jelent meg először írásban. 1337-ben említették Szent Lőrincnek szentelt templomát és azt, hogy 1427-­ben vásáros hely volt.'),
    ('Sióagárd', 'Sióagárd a Mezőföld déli csücskén, a Sió és Sárvíz közötti hátságon, a megyeszékhelytől, Szekszárdtól nyolc kilométerre fekszik. A közvetlenül határos települések: észak felől Medina, északkelet felől Szedres, délkelet felől Szekszárd Palánk nevű városrésze, délnyugat felől Zomba-Szentgálszőlőhegy, nyugat felől pedig Harc. A síkra épült falu mellett magasodik a Leányvár, a hegyhát legdélibb nyúlványa, mögötte a Szekszárdi-dombság lankái látszanak.'),
    ('Siófok', 'Területe 124,66 km², a Balaton-medence, a Mezőföld és a Külső-Somogy kistájak hármashatárán fekszik. A Balaton és a Duna közötti áruk legfontosabb logisztikai állomása. Emellett egyetemváros, 2024-től itt működik a Debreceni Egyetem egyetlen dunántúli kampusza. Magyarországon a kereskedelmi szálláshelyek 2019-es összesített vendégéjszaka-száma alapján a hatodik legnépszerűbb üdülőtelepülés.'),
    ('Siójut', 'A Sió szabályozása miatt korábbi ártéri jellegét túlnyomórészt elvesztette, a nagy hagyományokkal bíró halászat megszűnt. A löszös területen nagy erőfeszítésekkel honosították meg a szőlőművelést. Az 1950-es évek nagyüzemi gazdálkodása, a téeszesítés eltüntette a Siót övező ligetes galériaerdők nagy részét, a sovány földekről az erózió elhordta a termőréteget, így a környék ma jobbára félsivatagos jellegű, kisebb fasorokkal szabdalt, igen nehezen művelhető, kietlen pusztaság.'),
    ('Sobor', 'Sobor a Rábaköz déli részén, a Rába partján, Győrtől 47 kilométerre délnyugatra, Szanytól 7 kilométerre keletre található. A falut keletről a Rába határolja, északnyugati szélén pedig a Tákó-patak – hivatalos nevén a Sebes-Sobori-csatorna – folyik. A Rába áradása ellen magas, széles töltés védi, az eszteru, amelyen, ha kinyitják a sorompókat, akár autóval is lehet közlekedni.'),
    ('Sokorópátka', 'A dombság három nagy völgyének egyike a Sokorói-völgy, ennek az utolsó települése Sokorópátka. Természeti szépségét a falu határát felölelő erdők, a domborzati viszonyok adják. Kiváló a rálátás a Bakonyra illetve a Kisalföldre helyezkedik el. A szőlőjéről és ízletes málnájáról híres községben még fellelhetők a népi építészet emlékei. A falu közelében található Vadalmás nevű terület vadászházánál juthatunk el a tájvédelmi körzetbe(Pannonhalmi Tájvédelmi Körzet).'),
    ('Solt', 'Területe földtanilag a Föld legfiatalabb hegységrendszerébe, az eurázsiai hegységrendszerbe illeszkedik, ezzel együtt a települést csak sík területek és alacsony dombok veszik körül. Domborzata alföldi viszonylatban így is változatosnak mondható. Felszínének kialakulásában a levantei ópleisztocén süllyedék játszott jelentős szerepet, mint az ősi Duna első erózióbázisa.'),
    ('Soltszentimre', 'Kiskőröstől 20 kilométerre északra, Kecskeméttől 50 kilométerre délnyugatra helyezkedik el. Keletről a Duna–Tisza közi homokhátsághoz tartozó területek, nyugatról szikes puszták határolják. Területének nyugati harmada szinte teljes egészében a Kiskunsági Nemzeti Park Felső-kiskunsági-tavak nevű részegységéhez tartozik. A szomszédos települések: északkelet felől Izsák, dél felől Csengőd, délnyugat felől Akasztó, nyugat felől Dunatetétlen, északnyugat felől pedig Fülöpszállás.'),
    ('Soltvadkert', 'A Duna–Tisza közi homokhátságon, a Bugaci-homokháton, a Kiskunsági Nemzeti Park szomszédságában helyezkedik el, Kiskőröstől közúton 13 kilométerre délkeletre, Kiskunhalastól 20 kilométerre északnyugatra, a megyeszékhelytől, Kecskeméttől pedig mintegy 45 kilométerre délnyugatra. Kiskunmajsa, és azon keresztül Szeged térségével az 5405-ös út köti össze.'),
    ('Solymár', 'Magyarország legnépesebb nagyközsége. 2019-ben 11 277 fős lélekszámú település volt. Területe már a bronzkorban, majd a római korban is lakott volt. Nevének első ismert okirati említése 1266-ból való. [Az egyes forrásokban felbukkanó, 1255-ös legkorábbi okirati említéssel kapcsolatos említések tévedésen alapulnak.] A török hódoltság idején teljesen elnéptelenedett, ezért a 18. század első évtizedeiben németországi telepesekkel népesítették be.'),
    ('Som', 'A som (Cornus) a somvirágúak (Cornales) rendjébe és a somfélék (Cornaceae) családjába tartozó nemzetség. A somfajok az északi félgömb mérsékelt övi és sarkkör alatti részein fordulnak elő. Észak-Amerikától kezdve Európán keresztül Ázsiáig helyezkedik el. A legtöbb faj azonban Kínában, Japánban és az Amerikai Egyesült Államok délkeleti részén található meg.'),
    ('Somberek', 'A Baranyai-dombság keleti peremén található. Mérsékelten meleg, mérsékelten nedves éghajlatú területen 120 méterrel a tengerszint felett fekszik. Belterülete 165, külterülete 2977 hektár. A szomszédos települések: észak felől Palotabozsok, kelet felől Dunaszekcső, délkelet felől Bár, dél felől Mohács, nyugat felől pedig Görcsönydoboka. Csak kis híja van annak, hogy közigazgatási területe nem érintkezik északnyugat felől még Szebény határával is.'),
    ('Somlójenő', 'Veszprém megye nyugati részén helyezkedik el, Devecsertől mintegy 8 kilométerre nyugatra, a Torna patak völgyében. A szomszédos települések: észak felől Somlószőlős, kelet és dél felől Somlóvásárhely, nyugat felől Tüskevár, északnyugat felől pedig Iszkáz. Nagyon kevés híja van annak, hogy nem határos a területe északkelet felől még Dobával is. Belterülete egy rövid leágazással érhető el a főútról, a 73 182-es számú mellékúton.'),
    ('Somlószőlős', 'A Somlótól északnyugatra fekszik. A szomszédos települések: észak felől Somlóvecse, kelet felől Doba, dél felől Somlójenő, nyugat felől Iszkáz, északnyugat felől pedig Kisszőlős. Közigazgatási területe a fentiek mellett, egy-egy rövid szakaszon érintkezik északkeleti irányban Nagyalásony és Pápasalamon, délkeleti irányban pedig Somlóvásárhely határszélével is.'),
    ('Somlóvecse', 'Devecsertől északnyugatra fekszik, légvonalban 12, közúton körülbelül 16 kilométerre. A Somló hegyétől északra, nagyjából 6 kilométerre helyezkedik el. A szomszédos települések: észak felől Nagyalásony, dél felől Somlószőlős, nyugat felől Kisszőlős, északnyugat felől pedig Vid. Viddel egy alsóbbrendű önkormányzati út köti össze. Somlóvecse nevét 1488-ban említette először oklevél Wechee néven, mint a győri püspök birtokát.'),
    ('Somlóvásárhely', 'A a Veszprém–Devecseri-árokban, a Torna-patak völgyében helyezkedik el, Devecser város nyugati szomszédságában. Eredeti neve „Somló” volt, ami a környékére jellemző som szó származéka. Mivel a Szent Lambertról nevezett premontrei apácakolostor állott itt, azért kapta ’’Apácasomlya’’ nevét. 1270: Appachasomlya (Csánki lIl. 215). 1363: Wassarhel (uo.).'),
    ('Somodor', 'Közigazgatási területének keleti szélét egy szakaszon érinti a Kaposvár-Szántód közti 6505-ös út is, de onnan közvetlen leágazás nincs a lakott területei felé. Somodor nevét az 1332-1337 évi pápai tizedjegyzék említette először. Ekkor már azonban népes település lehetett, mivel egyháza is volt. 1389-ben a királyi udvarnokok falujaként szerepelt, 1438-ban Hédervári Lőrinc nádor nyerte királyi jóváhagyással Ozorai Pipó özvegyétől és még 1443-ban is Hédervári Lőrinc birtoka volt. 1536-ban gróf Farkas és Székely Lukács voltak a földesurai.'),
    ('Somogyacsa', 'A megye keleti részén, a Somogyi dombságban, a Koppány-patak mellett fekszik. A legközelebbi város Tab. Somogyacsa (Acsa) nevét 1406-1429-es években Acha alakban írva említette először oklevél. Ekkor részben kisnemeseké, részben a veszprémi püspöké volt, de 1480-ban már az egész birtok a veszprémi püspök birtoka volt, aki még az 1536 évi adólajstromban is földesuraként szerepelt. 1563-ban a török kincstári fejadólajstromban csak 5, az 1573-1574 éviben 8, az 1580-asban 6 házzal volt felvéve.'),
    ('Somogyapáti', 'Körjegyzőségi, szűkebb környezetében szolgáltatási központ. Baranya nyugati-északnyugati részében helyezkedik el, közel a baranyai-somogyi megyehatárhoz. Szomszédai északon Somogyviszló és Vásárosbéc, keleten Csertő, délkeleten Basal, délen Patapoklosi, délnyugaton Merenye, északnyugaton pedig Somogyhatvan helyezkedik el. Földrajzi értelemben a Zselichez tartozik.'),
    ('Somogyaracs', 'Horvátul két neve van a településnek: a đelekoveciek Aračának, a bolhói horvátok Oračnak hívják a falut. Somogyaracs apró, dél-somogyi falu Barcstól 15 kilométerre észak-északnyugatra helyezkedik el. A falu legutolsó birtokosa a gróf Somssich család volt. 1839-ben nyitott az első népiskola, az 1870. évi népszámlálás már 424 lakosról tett említést. 1877-ben egy nagy tűzvészben a falu fele leégett…'),
    ('Somogyaszaló', 'A közvetlenül határos települések: észak felől Mernye, északkelet felől Somodor, délkelet felől Répáspuszta, dél felől Toponár, délnyugat felől Kaposfüred [mindhárom utóbbi Kaposvár része], nyugat felől pedig Magyaregres. Déli határszéle mellett terül el a térség legnagyobb tava, a több patak vizének felduzzasztásával kialakított Deseda. Partszakaszainak egy kisebb része aszalói területen húzódik.'),
    ('Somogybabod', 'A település Balatonlellétől körülbelül 15 kilométerre dél-délkeletre, Kaposvártól mintegy 35 kilométerre északra található. Somogybabod területén régen két település állt. Tard (Tardpuszta) nevét először egy 11. századi irat említi, mint a szentmártoni apátság részbirtoka (1102-ben már temploma is volt), Babod (Babodpuszta) neve pedig az 1332–1337-es pápai tizedjegyzékben fordul elő először.'),
    ('Somogybükkösd', 'Első ismert írásos említése 1462-ben történt, amikor az egykori Filke községgel együtt az Apájfi és a Szelczei család elzálogosította a települést Darabos Lászlónak. Ebben az időben nevét Bykes alakban írták. Néhány évtized múlva a berzencei uradalomhoz tartozott, majd 1550-ben Both György, 1538–1539-ben Keczer János, 1626-ban az Istvánffy család, az 1660-as dézsmajegyzék szerint a Zrínyi család, 1701–1703-ban a Spongor család, az 1800-as években pedig a Domaniczky, Hochreiter, illetve a Kálordy és a Perczel családok birtokolták.'),
    ('Somogycsicsó', 'Előbbieken túl mindössze két másik településsel határos közvetlenül: északkelet felől Kaszóval, délkelet felől pedig Szentával. Délnyugat felől a legközelebbi település Csurgónagymarton, de a közigazgatási területeik nem érintkeznek. A 14. században már létezett a település és Szent György tiszteletére szentelt templomát említették. A Kanizsai család birtoka volt.'),
    ('Somogydöröcske', 'Tamásitól kissé délnyugatra, a Koppány-patak mellett fekvő település. Közigazgatási területét átszeli a Nagykónyi-Törökkoppány-Somogyacsa közti 6508-as út, de a központja csak az abból dél felé kiágazó 65 119-es mellékúton érhető el. Árpád-kori település. Nevét 1138-ban villa Diarugsa alakban, a dömösi prépostság birtokai között említették először. 1267-ben Derekche, 1424-1436 között Derecske írásmóddal fordult elő.'),
    ('Somogyegres', 'Környezete és levegője tiszta. Erdők, tavak veszik körül. A bükkös, tölgyes, gyertyános erdők vadállománya gazdag, kedvelt vadászterület. A szép természeti környezet kellemes pihenő- és kirándulóhely az idelátogatók számára helyezkedik el. Az igali és tamási gyógyfürdők, valamint a Balaton déli partjának látnivalói is könnyen elérhetők innen helyezkedik el.'),
    ('Somogyfajsz', 'A falu a Boronka-melléki Tájvédelmi Körzet határán fekszik, a 6703-as út mentén, amely elvileg Kaposvár és Marcali vonzáskörzeteit hivatott összekötni, de több szakasza nehezen vagy korlátozottan járható földút. Változatos növény- és állatvilága, a biodiverzitás magas foka teszi különlegessé a települést, amely a nevének tanúsága szerint már a honfoglalás korában is lakott lehetett (a Fajsz utótag Fajsz fejedelem nevét őrzi).'),
    ('Somogygeszti', 'Központján a 6513-as út húzódik végig, amely Ráksitól indulva Mernye érintésével Somogyjádig húzódik, összekötve a 67-es főutat a 6505-ös és 6701-es utakkal. A 19. században a Jankovich-Bésán család nagy uradalmat bírt Somogygesztin. Pribéri, vuchini és dunaszekcsői Jankovich-Bésán Géza (1857–1904), a Somogy…'),
    ('Somogyhatvan', 'Somogyhatvan nevét 1421-ben említették először az oklevelek Hatwan írásmóddal. A falu a középkorban valószínűleg a település déli határán húzódó egykori Szentmiklósi kolostor birtokaihoz tartozott. A török idők alatt is kisnemesek által lakott falu a Hódoltság végének felszabadító harcaiban leégett, s lakói délebbre, a falu mai helyére húzódtak. A település birtokosai voltak a Traun, a Draskovich és az Esterházy család is.'),
    ('Somogyhárságy', 'Nagy-Hárságy a Győr nemzetség ősi birtoka volt. Nevét az oklevelek 1346-ban a Győr nemzetségbeliek osztozkodásakor említették először. Ekkor Hárságy Szerdahelyi Dersfi Péternek jutott. 1489-ben már két ilyen nevű helység volt e tájon: Flsewhassagh és Alsowhassagh néven, mindkettő Szerdahelyi Dersfi Istváné volt. 1598-1599-ben Székely Mihály, 1626-ban Imrefy Farkas volt a földesura.'),
    ('Somogyjád', 'Somogyjád környékén mintegy 180 hektár erdő borítja a tájat, a falu külterületének nagy részén viszont a kedvező talaj miatt jelentős mezőgazdasági művelés is folyik. A falu területe 25,06 négyzetkilométer, melyből a belterület 169 hektárnyit tesz ki. Kaposvártól, a megyeszékhelytől, mindössze 17 kilométernyire fekszik. Mivel Somogyjád a Kaposvárt-Fonyóddal összekötő országút mentén fekszik, az autóbuszok viszonylag sűrűn járnak mind a harminc kilométerre fekvő Balaton, mind a megyeszékhely irányába.'),
    ('Somogymeggyes', 'Tabtól nyugatra, körülbelül 10 kilométerre található. Dombokkal tarkított, erdőkkel határolt vidéken fekszik a Kis-Koppány völgyében. Közúton a Kaposvár–Szántód közti 6505-ös útról Kapoly területén nyugatra letérve közelíthető meg, a 65 135-ös úton. A közeli Csicsalpuszta középkori településről az 1055-ben keletkezett tihanyi alapítólevélből értesülhetünk először. 1310-ben a pannonhalmi apátságé volt a terület, később Alsó- és Felső-Köttcse néven rövid időre a székesfehérvári káptalan birtokába került. 1332-37-ben plébániája volt.'),
    ('Somogysimonyi', 'Központján a 6805-ös út halad át, de közigazgatási területének délkeleti szélét érinti a Vése-Nemesvid közti 6816-os út is. Nemesvidtől a Gödör-berki erdő választja el, melynek jellemző fája a tölgy. A sűrű erdőben tavasszal gyöngyvirágmezők díszlenek. Itt nyílik a hegyvidékre jellemző ciklámen is. Az erdő nagyvadjai a dámvad, szarvas, őz és a vaddisznó, de előfordul róka, görény és menyét is.'),
    ('Somogyszentpál', 'A Belső-Somogyban, a Nagy-Berek délnyugati szélén található, Balatonkeresztúrtól délkeletre. A közvetlenül határos települések: észak felől Balatonfenyves, kelet felől Táska, dél felől Csömend, délnyugat felől Marcali, nyugat felől pedig Kéthely. Közigazgatási területe délkelet felől pontszerűen érintkezik még Nikla határával is. Közúton csak két irányból érhető el: Kéthely érintésével, a 68-as főútból kiágazó 67 108-as számú mellékúton, vagy Csömend központjából egy keskeny önkormányzati úton.'),
    ('Somogyszil', 'A címer megalkotásakor a település korábban használt pecsétjeihez, és azok elemeihez nyúltak vissza. Már a 18. század végén használt pecséten megtalálható volt a háromágú korona, az ekevas, a búzakalász (ekkor még csak egy darab) és a könyöklő kar (ekkor még balra fordult). 1835-től a búzakalászok száma három lett, a kar jobbra fordult, a korona azonban hiányzott.'),
    ('Somogyszob', 'Erdőkkel övezett, természeti adottságokban bővelkedő területen fekszik. Délkeleti szomszédja Nagyatád, az északkeleti pedig Segesd, mindkettőtől nagyjából 8-8 kilométerre fekszik. Az 1332-37. évi pápai tizedjegyzékben is szerepel. 1331-ben Tamás erdélyi vajda lett Somogyszob ura. Károly Róbert királynak szóló jelentésében…'),
    ('Somogysámson', 'A vonattal érkezőknek Balatonszentgyörgyön kell az onnan induló buszjáratra átszállniuk. A település szőlő- és borgazdasági szempontból a Balatonboglári borvidék részét képezi. Eredetileg középkori település, neve írott forrásban első ízben a Bertalan veszprémi püspök és a szentmártoni apát között 1533. szeptember 11-én kötött egyezséglevélben fordul elő, amikor már kápolnája is volt.'),
    ('Somogysárd', 'Sörnyepuszta településrészén a 6703-as út halad végig helyezkedik el. A kis települést, mint a Győr nemzetség ősi birtokát az oklevelek először 1364-ben Saard módon írva említik, 1454-től már Sárd írásmóddal szerepel. Első is ismert birtokosai, a Győr nemzetség szerdahelyi ágából való Szerdahelyi család tagjai voltak. Sárd a nemzetség tagjainak 1346 évi osztozkodásakor Szerdahelyi Dersfi Miklósnak jutott.'),
    ('Somogytúr', 'Jellegzetes somogyi falu, a hegyes-völgyes ligetekkel tarkított környékével mindössze 12 kilométerre van Balatonlellétől. A település szőlőtermő területei a Balatonboglári borvidék részét képezik. Somogytúr kétszer élte fénykorát. Először a török megszállás előtt, majd a 18. századi betelepítések után helyezkedik el. Okleveleinkben a Túri puszta 1082-ben szerepel először az oklevelekben Tuuri puszta írásmóddal, mint veszprémi káptalan birtoka.'),
    ('Somogyudvarhely', 'Természetföldrajzilag a Dunántúli-dombság területén, ezen belül is Belső-Somogyban terül el. A legközelebbi szomszédos települések az országhatár magyar oldalán Berzence 5 kilométerre északnyugatra és Bélavár 6 kilométerre dél-délkeletre helyezkedik el. Mindkettőnél közelebb fekszik Somogyudvarhelyhez a határ horvát oldalán fekvő Zsdála, de a két település közt nincs kiépített közúti összeköttetés.'),
    ('Somogyviszló', 'Szomszédai északon Somogyhárságy, keleten Szulimán, délkeleten Csertő, délen és nyugaton pedig Somogyapáti. Földrajzi értelemben a Zselichez tartozik. Somogyviszló (Viszló) nevét 1329-ben említették először Wyzlou módon írva nevét. Ekkor a Monoszló nemzetség tagjai, Gergely bán fiai, László és Dénes voltak a település birtokosai. 1330-ban a Monoszló nemzetségbeliek megosztoztak birtokaikon helyezkedik el.'),
    ('Somogyvámos', 'Somogyvámos a Balatontól délre a Fonyód és Kaposvár közötti úton található. A települést dombok veszik körül, amelyeken rétek és ösvényekkel szabdalt kisebb erdők váltják egymást. Lengyeltóti a legközelebbi város, kb. 14 kilométerre található. A településnek nincs saját vasútállomása, de a Kaposvár–Fonyód vonalon Somogyvártól autóbusszal lehet eljutni.'),
    ('Somogyvár', 'A település már a bronzkorban is lakott volt. A történelmi hagyomány szerint a Somogyi hercegséget öröklő Koppány vezérnek a mai Somogyvár területén vagy a közelében volt a vezéri szállása, és innen indultak lázadó csapatai Veszprém ostromára 997-ben. A közeli Kupa-várhegyen végzett ásatások során egyértelműen bizonyították, hogy az 1091-ben Szent László király által felszentelt Szent Egyed bencés monostor körül valószínűleg csak a 12. században épült várfal.'),
    ('Somogyzsitfa', 'Balatonszentgyörgytől délre, Marcalitól nyugatra, a Marcali-hát nyugati oldalán fekszik. Három részből áll: északon Somogyfehéregyház, középen Felsőzsitfa, délen pedig Szőcsénypuszta terül el. Szőcsénypuszta településrészt a 6803-as mellett a Marcali–Galambok közti 6805-ös út is érinti. Szőlő- és borgazdasági szempontból a Balatonboglári borvidék részét képezi. 1950-ben jött létre az addig önálló Felsőzsitfa és Somogyfejéregyház községek egyesítésével.'),
    ('Somoskőújfalu', 'Somoskőújfalu az Északi-középhegységben, azon belül is a Cserhát északkeleti vonulatában helyezkedik el. Salgótarjántól északra, a Karancs és a Medves közti völgyben fekszik. A Karancs és a Medves hegységeket általában együtt említik, mintha egy hegységről lenne szó, pedig származástanilag a Karancs a 25 millió éves Cserháthoz, a Medves pedig a mindössze 1,5–2 millió éves ajnácskői bazaltvidékhez sorolható.'),
    ('Sonkád', 'A falu déli határában, ahol a két folyóág kettéválik, az Új-Túron található a Kisbukógát, melynek környéke kedvelt kirándulóhely. Az Öreg-Túr és környéke a Szatmár-beregi Tájvédelmi Körzethez tartozik, ahol ez a folyóág nagy számú kanyarulatot leírva, erdős-ligetes részek között meanderezik a Tisza irányába. A gazdag vízi növény- és állatvilág, a vízhez kötődő ősi mesterségek megmaradt tárgyi emlékei megkapó élményeket nyújtanak az erre járóknak.'),
    ('Soponya', 'Székesfehérvártól mintegy 25 kilométerre délre található, a Sárvíz völgyének nyugati oldalán. A környező települések: Aba, Káloz, Csősz, Tác (Gorsium) és Kisláng. Soponya első ismert okirati említése 1192-ből származik. Az évszázadok során volt a település királyi, királynéi és nemesi birtok is, illetve Soponya és Nagyláng sokáig két különálló településnek számított.'),
    ('Sopron', 'A Nyugat-Dunántúl harmadik, valamint Győr után megyéje második legnépesebb települése. „A leghűségesebb város” . Magyarország egyik legrégebbi városa, a határhoz való közelsége miatt pedig kapcsolatot teremt hazánk és nyugati szomszédunk, Ausztria között. Műemlékekben a második leggazdagabb település Magyarországon, kereskedelmi szálláshelyeken eltöltött vendégéjszakák tekintetében pedig Magyarország 9. legnépszerűbb települése. 2016-ban ICOMOS-díjat kapott a Várfal sétány és a Várkerület megújítása.'),
    ('Sopronhorpács', 'A Nyugat-magyarországi peremvidék nyugati kavicstakarós peremén, a Répce-síkon fekszik, közvetlenül az osztrák határ mellett, attól 5 kilométerre. Éghajlata mérsékelt, ám mivel hatással van rá az Alpok közelsége, így csapadékosabb, szelesebb és kissé hidegebb is az országos átlagnál. A napfénytartam évi átlaga 1900 óra, az évi középhőmérséklet 10 °C fok, a csapadék átlagos mennyisége pedig 625 mm/év.'),
    ('Sopronkövesd', 'Soprontól 20 kilométerre délkeletre, a Kisalföld nyugati határszélén fekszik. Felszíni vizeit a Füles-patak gyűjti össze. Nyugati határában ered a Kardos-ér. A szomszédos települések: észak felől Pereszteg, északkelet felől Nagylózs, kelet felől Röjtökmuzsaj, dél felől Lövő és Völcsej, nyugat felől pedig a már Ausztriához tartozó Füles (Nikitsch). Közigazgatási területe a fentieken túlmenően, kelet felől érintkezik még Ebergőc, délkelet felől Pusztacsalád és Újkér, délnyugat felől pedig Sopronhorpács határszéleivel is.'),
    ('Sopronnémeti', 'Magyarország északnyugati részén, majdnem a Rábaköz közepén helyezkedik el. Szomszédai keleten 3,8 kilométerre Szilsárkány, délkeleten 4,4 kilométerre Szil, délnyugaton 3,5 kilométerre Magyarkeresztúr, északnyugatra 2 kilométerre pedig Potyond. Nevével ellentétben a legközelebbi város Csorna, 9 kilométerre északkeletre helyezkedik el. A Rába vízgyűjtő területéhez tartozik.'),
    ('Sorkifalud', 'Dömötöri, Sorkikisfalud, Szentléránt és Taródháza 1939. évi egyesítéséből jött létre. Szombathelytől 17 kilométerre délkeletre fekszik, a Sorok patak mellett. Az ország távolabbi részei irányából a 87-es vagy a 86-os főutak érintésével közelíthető meg. Nevét a Sorok patak nevéről kapta, amely mellett fekszik. A patak neve feltételezések szerint Sur vezér nevéből származik, melyhez kicsinyítő képző járult. 1943-ban változtatták…'),
    ('Sorkikápolna', 'A Gyöngyös-sík déli peremén, a Sorok-patak jobb partján fekszik, Szombathelytől 15 kilométerre délkeletre. Külterületeit érintik még a 8704-es és a 8705-ös utak is. Arról a Szent László tiszteletére emelt kápolnáról kaphatta nevét, amely 1301-ben a szomszédos Sorokpolány határában állott. 1418-ban Zalak faluval kapcsolatban "Poss. Kapolna alio nomine Zalak ac poss.'),
    ('Sormás', 'Neve Saramás alakban fordul elő először 1347-ben helyezkedik el. E magyar helységnév a kígyóvirág, vadhagyma jelentésű sárma növényre vezethető vissza. Mivel közel fekszik a kulcsfontosságú kanizsai várhoz, sokat szenvedett a hódoltság éveiben. Többször teljesen elpusztították. 1347-ben szerepel először oklevelekben Saramás néven, mint a saramási Fábián család birtoka.'),
    ('Sorokpolány', 'A Gyöngyös-sík déli peremén, a Sorok-patak jobb partján emelkedő magaslaton fekszik, Szombathelytől 14 kilométerre dél-délkeletre. Sorokpolány 1939-ben keletkezett Sorkipolány és Sorokújfalu egyesítésével. 1265-ben Pulan néven említik először. Neve az ősszláv polanya (= nyílt kopár térség, síkság) főnévből származik. 1301-ben Palan, 1410-ben Polyan néven említik. 1301-ben Szent-László tiszteletére szentelt kápolna állt határában helyezkedik el.'),
    ('Sukoró', 'Sukoró a Velencei-hegység keleti, a Velencei-medencébe ereszkedő lankáin, a Velencei-tó északi partján fekszik, a Velencei-hegység lábánál. Keletről Velence, északkeletről Nadap és délnyugatról Pákozd határolja. Sukoró a Buda és az Adriai-tenger között futó fő kereskedelmi út mellett feküdt. A középkorban Sukoró Pákozd után a környék meghatározó települése.'),
    ('Sumony', 'Szigetvártól délkeletre, Szentlőrinctől délnyugati irányban helyezkedik el. A szomszédos települések: észak felől Szentdénes, északkelet felől Királyegyháza, kelet felől Gyöngyfa, délkelet felől Magyarmecske és Gilvánfa, dél felől Csányoszró, délnyugat felől Okorág, északnyugat felől pedig Bánfa és Rózsafa. Sumony nevét az oklevelek 1290-ben említették először Sumon írásmóddal, majd 1332-ben Somon alakban írták. 1290-ben a pécsi káptalan által állított [egyházi] nemes tanúk között Sumonyra való lakosok is szerepeltek.'),
    ('Surd', 'A településen polgárőrség működik. Csurgótól északnyugatra, Zákány és Nemespátró közt fekvő település. Surd Árpád-kori település. Az 1565–1566. évi török kincstári fejadójegyzékben csak 2 házzal vették fel. 1626-ban Szalay János birtoka volt, az 1660. évi dézsmaváltságjegyzék szerint a falut több nemescsalád lakta. 1659-ben már evangélikus lelkésze…'),
    ('Szabadegyháza', 'A Közép-Mezőföldön, a Duna és Sárvíz között, a Velencei-tótól délre fekszik. A közvetlenül határos települések: észak felől Zichyújfalu, északkelet felől Pusztaszabolcs, délkelet felől Perkáta, délnyugat felől Sárosd, északnyugat felől pedig Seregélyes. A vidék nem volt ismeretlen a rómaiak előtt. Valahol a környéken futott az Intercisa (Dunaújváros) – Gorsium (Tác) útvonal.'),
    ('Szabadhídvég', 'A Külső-Somogy dombvidékének határán, a Sió jobb partján, Mezőkomárommal szemben helyezkedik el. Múltjáról az első írásos adat 1344-ből származik, amikor „villa Hiydwegh”, azaz Hídvég falu megnevezést említ az oklevél. Területén a 20. század előtt több település is volt, mai határait és elnevezését 1922-ben nyerte el, amikor egyesítették Városhidvéget, Faluhidvéget és Szabadhegyet.'),
    ('Szabadi', 'A legközelebbi város a 9 kilométerre fekvő Dombóvár. Bár nincs túl közel a Balaton déli partjához, a település szőlőtermő területei mégis a Balatonboglári borvidék részét képezik. Szabadi neve először az 1332–1337-es pápai tizedjegyzékben bukkant fel. A falu pecsétjét 1788 óta használták. Lakossága évszázadokon keresztül, egészen az 1970-es évekig 500 fő körül mozgott (jelentős német kisebbséggel), ám ekkor megkezdődött az addig szinte kizárólag mezőgazdaságból élő lakosság elvándorlása, legtöbben a közeli városokban az iparban találtak munkát.'),
    ('Szabadkígyós', 'A település a Tiszántúl délkeleti részén, Békéscsabától 11 kilométerre, a megyeszékhely déli szomszédságában található. További szomszédai: kelet felől Gyula, délkelet felől Kétegyháza, nyugat felől pedig Újkígyós. A település mellett található a Körös–Maros Nemzeti Park. Békéscsaba felől a 4433-as út vezet a településre, de csak a külterületeit érinti, a központtól mintegy 2 kilométerre keletre halad el.'),
    ('Szabadszentkirály', 'A további szomszédos települések: északkelet felől Bicsérd, délkelet felől Pécsbagota, dél felől Velény, délnyugat felől Gerde, nyugat felől pedig Királyegyháza. Szabadszentkirály (Szentkirály) nevét az oklevelek 1326-ban említették először Bart néven. 1332-1335 között Bart. (sac.) de S. Rege formában említették nevét. 1326-ban a pécsi káptalan kiküldöttjeként szereplő papja volt említve.'),
    ('Szabadszállás', 'A szomszédos települések: észak felől Kunszentmiklós (18 kilométerre), északkelet felől Kunadacs (10 kilométerre), kelet felől Kerekegyháza és Fülöpháza (20, illetve 17 kilométerre), dél felől Fülöpszállás (6 kilométerre), délnyugat felől Solt (18 kilométerre), nyugat felől Újsolt (8 kilométerre), északnyugat felől pedig Dunavecse (19 kilométerre).'),
    ('Szabolcs', 'Fő nevezetessége a 950 körül emelt szabolcsi földvár. Területe 5,88 négyzetkilométer, északról a Tisza ártéri síksága, a Bodrogköz határolja. Talaj típusos lösz, éghajlata mérsékelten meleg, száraz. Felszínét a régi, feltöltődő állapotban lévő Tisza-meder-maradványok és kisebb mocsarak tagolják. A falu határát a 18. században még nagy kiterjedésű tölgyerdők borították, a folyó partját széles sávban ártéri erdők szegélyezték.'),
    ('Szabolcsbáka', 'Szabolcsbáka Nyíregyházától mintegy 58 kilométerre található az Északkelet-Nyírségben. A közvetlen szomszédos települések: észak felől Pap, északkelet felől Lövőpetri, délkelet felől Gemzse, délnyugat felől Gyulaháza, északnyugat felől pedig Anarcs. A legközelebbi város Kisvárda, 9 kilométerre északnyugatra helyezkedik el. A Kisvárdát Vásárosnaménnyal összekötő 4108-as út mentén fekszik, ezen érhető el mindkét végponti város felől.'),
    ('Szabolcsveresmart', 'Lakott területei teljes egészében a folyó bal parti oldalán terülnek el, de közigazgatási területének egy csekély, másfél négyzetkilométert sem elérő hányada a túlparti oldalra esik. Veresmart (Szabolcsveresmart) nevét az oklevelek a 14. század elejétől említik. 1329-ben a Zichy család oklevéltárában már előfordult neve, Poss. Weresmorth és Villa Weresmorth néven. 1334-ben a Várday család tagjait írták a település birtokosának.'),
    ('Szada', 'A Szada név egyesek szerint a finnugor nyelvből származik, és valaminek a száját (száda), bejáratát jelenti. (Így névetimológiailag hasonlít többek között Taktaszadára) Gödöllő felől nézve a település pont a Sződ–Rákos-patak széles völgyének felső bejáratánál fekszik. Más magyarázat szerint szláv eredetű, és kertet jelent. Az első írásos emléke 1325-ös oklevélben van.'),
    ('Szajk', 'Az Árpád-kori múltra visszatekintő, a török után újratelepült község a rendszerváltás, önkormányzati rendszer kiépülését követően látványos fejlődésnek indult. Ennek alapját a kedvező természeti és közlekedésföldrajzi adottságok, valamint a helyi lakosság munkája, szorgalma adta, ami a történelmi hagyományokból, etnikai adottságokból is következett.'),
    ('Szajla', 'Két különálló településrész alkotja: az ófalu a Tarna jobb, Szajla-Újfalu pedig másfél-két kilométerre északkeletre, a kis folyó bal parti oldalán. Utóbbi a szomszédos Terpessel teljesen összenőtt, ott található a község polgármesteri hivatala is. A szomszédos települések: észak felől Terpes, északkelet felől Bükkszék, délkelet felől Sirok, délnyugat felől Recsk, északnyugat felől pedig Kisfüzes.')
) AS v(name, panel_leiras)
WHERE c.name = v.name;

